    "q.l36#10.o1" to "La profondità non è misurabile",
    "q.l36#10.o2" to "La profondità è sempre poca",
    "q.l36#10.o3" to "La profondità determina la sopravvivenza",
    "q.l36#10.e" to "Trattare un problema ingegneristico come criterio medico porta a rinunciare in anticipo. La decisione guarda solo tempo, vie aeree e temperatura.",

    "q.l36#11.p" to "Secondo la versione 2023, quali elementi entrano nella scelta della strategia?",
    "q.l36#11.o0" to "Tempo di seppellimento",
    "q.l36#11.o1" to "Se le vie aeree sono libere",
    "q.l36#11.o2" to "Se si riesce a misurare la temperatura centrale e quanto vale",
    "q.l36#11.o3" to "Profondità del seppellimento",
    "q.l36#11.e" to "I primi tre formano l'albero decisionale. Il quarto dice solo quanto devi scavare e non cambia la strategia.",

    "q.l36#12.p" to "Quali sono i punti chiave nella gestione dell'arresto da ipotermia?",
    "q.l36#12.o0" to "Movimentare con delicatezza, evitando scossoni",
    "q.l36#12.o1" to "Isolare termicamente tutto il corpo",
    "q.l36#12.o2" to "Monitorare di continuo ritmo cardiaco e temperatura centrale",
    "q.l36#12.o3" to "Riscaldare sul posto fino a 35 °C prima di trasportare",
    "q.l36#12.e" to "Sul posto non si riesce a riscaldare efficacemente: insistere sul «prima scaldiamo e poi partiamo» fa perdere tempo. L'obiettivo è arrivare il prima possibile a un centro con ECLS.",

    "q.l36#13.p" to "Su vie aeree e ventilazione, cosa è corretto?",
    "q.l36#13.o0" to "Liberare naso e bocca da neve e ghiaccio",
    "q.l36#13.o1" to "In caso di dubbio sull'ostruzione, considerare le vie aeree libere",
    "q.l36#13.o2" to "Ventilare prima di pensare alle compressioni",
    "q.l36#13.o3" to "Valutare le vie aeree solo dopo l'estrazione completa",
    "q.l36#13.e" to "I primi tre puntano tutti a «ventilare presto». L'ultimo fa perdere i minuti più importanti.",

    "q.l36#14.p" to "Metti in ordine la gestione di un seppellimento «fino a 60 minuti, nessun segno vitale».",
    "q.l36#14.o0" to "Liberare naso e bocca e valutare le vie aeree",
    "q.l36#14.o1" to "Iniziare subito la respirazione di soccorso",
    "q.l36#14.o2" to "Iniziare le compressioni toraciche",
    "q.l36#14.o3" to "Isolare termicamente, proteggere la colonna e organizzare il trasporto",
    "q.l36#14.e" to "La ventilazione precede le compressioni: è la differenza più importante tra arresto asfittico da valanga e arresto cardiaco di origine cardiaca.",

    "q.l36#15.p" to "Metti in ordine la valutazione per un seppellimento «oltre 60 minuti».",
    "q.l36#15.o0" to "Confermare che il tempo di seppellimento supera davvero i 60 minuti",
    "q.l36#15.o1" to "Valutare se le vie aeree sono completamente ostruite",
    "q.l36#15.o2" to "Provare a misurare la temperatura centrale",
    "q.l36#15.o3" to "Decidere secondo il ramo corrispondente se iniziare la rianimazione",
    "q.l36#15.e" to "L'ordine è «prima il tempo, poi le vie aeree, infine la temperatura». Se manca un'informazione in uno dei tre passi, si sceglie il ramo che favorisce il salvataggio.",

    "q.l36#16.p" to "La linea decisionale per la rianimazione secondo ICAR MedCom 2023 è di ______ minuti di seppellimento.",
    "q.l36#16.a0" to "60",
    "q.l36#16.e" to "La vecchia soglia di 35 minuti è superata. Materiali didattici e banca domande vanno allineati a 60 minuti.",

    "q.l36#17.p" to "Con temperatura centrale inferiore a ______ °C e vie aeree libere, si tenta la rianimazione indipendentemente dal tempo di seppellimento.",
    "q.l36#17.a0" to "30",
    "q.l36#17.e" to "30 °C è il criterio parallelo che porta la «protezione ipotermica» dentro la decisione.",

    "q.l36#18.p" to "L'ipotermia causa solo lo 0–4 % dei decessi da valanga, quindi l'ordine è prima ______ e poi riscaldamento.",
    "q.l36#18.a0" to "ventilare",
    "q.l36#18.a1" to "la ventilazione",
    "q.l36#18.a2" to "le vie aeree",
    "q.l36#18.e" to "Prima ventilare e poi riscaldare: nel soccorso in valanga questo ordine è ancora più rigoroso che nell'ipotermia ordinaria.",

    "q.l36#19.p" to "Abbina ogni situazione di seppellimento alla gestione corrispondente (versione 2023).",
    "q.l36#19.l0" to "Fino a 60 minuti, nessun segno vitale",
    "q.l36#19.l1" to "Oltre 60 minuti, vie aeree libere, temperatura non misurabile",
    "q.l36#19.l2" to "Oltre 60 minuti, vie aeree ostruite, temperatura non misurabile",
    "q.l36#19.l3" to "Temperatura misurabile inferiore a 30 °C, vie aeree libere",
    "q.l36#19.r0" to "Trattare come asfissia e ventilare il prima possibile",
    "q.l36#19.r1" to "Trattare come arresto ipotermico e iniziare la rianimazione",
    "q.l36#19.r2" to "Trattare come arresto asfittico e non iniziare la rianimazione",
    "q.l36#19.r3" to "Tentare la rianimazione indipendentemente dal tempo e trasportare in ECLS",
    "q.l36#19.e" to "I quattro rami coprono la grande maggioranza delle situazioni sul posto. Ricordare le condizioni dei rami è più affidabile che memorizzare le conclusioni.",

    "q.l36#20.p" to "Abbina ogni criterio di sospensione della rianimazione al suo significato.",
    "q.l36#20.l0" to "Lesioni mortali",
    "q.l36#20.l1" to "Corpo completamente congelato",
    "q.l36#20.l2" to "Vie aeree ostruite e oltre 60 minuti",
    "q.l36#20.l3" to "Potassio marcatamente elevato",
    "q.l36#20.r0" to "La lesione in sé non è curabile",
    "q.l36#20.r1" to "Il corpo è in stato di congelamento e il riscaldamento non ha senso",
    "q.l36#20.r2" to "Trattare come arresto asfittico e non iniziare la rianimazione",
    "q.l36#20.r3" to "Indica ipossia prolungata, con prognosi molto sfavorevole",
    "q.l36#20.e" to "Tutti e quattro sono prove che «dal punto di vista medico non c'è più possibilità di inversione». La valutazione spetta a personale addestrato e va documentata.",

    "q.l36#21.p" to "Sul posto qualcuno sostiene che «oltre 35 minuti non si rianima»: come rispondi?",
    "q.l36#21.o0" to "Quella è la soglia del 2013; la versione 2023 è passata a 60 minuti e ha aggiunto il criterio della temperatura",
    "q.l36#21.o1" to "Ha ragione",
    "q.l36#21.o2" to "Dipende dai casi",
    "q.l36#21.o3" to "Decida lui",
    "q.l36#21.e" to "Nei materiali in circolazione i 35 minuti sono ancora molto presenti. Aggiornare la soglia è uno dei valori più concreti di questo tipo di corso.",

    "q.l36#22.p" to "Scenario: seppellimento di 20 minuti, all'estrazione non respira, naso e bocca con neve sciolta ma non completamente pieni. Cosa si fa?",
    "q.l36#22.o0" to "Liberare naso e bocca, ventilare, iniziare le compressioni e trasportare il prima possibile",
    "q.l36#22.o1" to "Considerarlo ostruito e non rianimare",
    "q.l36#22.o2" to "Riscaldare prima di tutto",
    "q.l36#22.o3" to "Aspettare la valutazione della squadra professionista",
    "q.l36#22.e" to "Fino a 60 minuti più assenza di ostruzione completa significa trattare come asfissia e rianimare a fondo. La neve sciolta non costituisce ostruzione.",

    "q.l36#23.p" to "Scenario: seppellimento di 70 minuti, vie aeree libere, temperatura centrale 28 °C, nessun segno vitale. Cosa si fa?",
    "q.l36#23.o0" to "Continuare la rianimazione, movimentare con delicatezza, isolare termicamente e trasportare in un ospedale con ECLS",
    "q.l36#23.o1" to "Sospendere la rianimazione",
    "q.l36#23.o2" to "Solo riscaldare e osservare",
    "q.l36#23.o3" to "Riscaldare fino a 35 °C e poi trasportare",
    "q.l36#23.e" to "Il nucleo dell'arresto ipotermico è «portare dove si può riscaldare»: la rianimazione non si interrompe durante il trasporto.",

    "q.l36#24.p" to "Perché si dice che «il cuore freddo è molto sensibile»?",
    "q.l36#24.o0" to "Una movimentazione brusca può scatenare fibrillazione ventricolare: serve movimentare con delicatezza e in orizzontale",
    "q.l36#24.o1" to "Perché ha freddo",
    "q.l36#24.o2" to "Perché batte piano",
    "q.l36#24.o3" to "Perché la pressione è bassa",
    "q.l36#24.e" to "È il motivo per cui il paziente ipotermico va movimentato «piatto, stabile, piano»: oltre alla protezione della colonna, c'è questa seconda ragione.",

    "q.l36#25.p" to "Durante il soccorso un compagno crolla emotivamente e insiste per sospendere la rianimazione: cosa deve fare il capo cordata?",
    "q.l36#25.o0" to "Farlo uscire dalle manovre ma continuare la rianimazione, lasciando che siano i criteri e il personale addestrato a decidere",
    "q.l36#25.o1" to "Sospendere subito",
    "q.l36#25.o2" to "Rimproverarlo",
    "q.l36#25.o3" to "Fargli continuare le compressioni",
    "q.l36#25.e" to "L'emozione va accolta, ma la decisione medica non può dipendere dall'emozione. Cambiare persona invece di fermare le manovre è la soluzione più responsabile.",
    // ---------- l37 Il trittico: ricerca ARVA e sondaggio ----------
    "q.l37#0.p" to "Le quattro fasi della ricerca in valanga, in che ordine vanno?",
    "q.l37#0.o0" to "Ricerca del segnale e degli indizi → ricerca grossolana → ricerca fine → sondaggio puntuale",
    "q.l37#0.o1" to "Ricerca grossolana → ricerca fine → sondaggio puntuale → ricerca del segnale",
    "q.l37#0.o2" to "Sondaggio puntuale → ricerca fine → ricerca grossolana",
    "q.l37#0.o3" to "Ricerca → scavo → sondaggio",
    "q.l37#0.e" to "Le quattro fasi sono una progressione che restringe il campo: dall'intero pendio, a pochi metri, a un punto sulla neve, alla profondità esatta. Saltare un passaggio fa perdere tempo.",

    "q.l37#1.p" to "Qual è di norma la distanza tra le corsie di ricerca ARVA?",
    "q.l37#1.o0" to "Circa 40 metri, e circa 20 metri dal bordo del deposito",
    "q.l37#1.o1" to "10 metri",
    "q.l37#1.o2" to "80 metri",
    "q.l37#1.o3" to "Più larga è, meglio è",
    "q.l37#1.e" to "40 metri è il valore didattico di riferimento, non il limite dello strumento. Se il livello di addestramento non è certo, si scende a 30 metri: meglio fare qualche passata in più.",

    "q.l37#2.p" to "Prima di iniziare la ricerca, qual è la cosa più importante per tutto il gruppo?",
    "q.l37#2.o0" to "Mettere tutti gli ARVA in ricezione e spegnere telefoni e macchine fotografiche",
    "q.l37#2.o1" to "Scavare prima una buca di prova",
    "q.l37#2.o2" to "Fare prima una foto",
    "q.l37#2.o3" to "Raccogliere prima la corda",
    "q.l37#2.e" to "Se qualcuno è ancora in trasmissione la ricerca non funziona; le interferenze elettroniche riducono la distanza utile. Sono due cose da fare nel primo passo.",

    "q.l37#3.p" to "Nella fase di ricerca del segnale, a cosa si guarda per primo?",
    "q.l37#3.o0" to "Agli indizi visibili sulla neve (guanti, punte di bastoncino, cinghie dello zaino)",
    "q.l37#3.o1" to "Alla lettura dell'ARVA",
    "q.l37#3.o2" to "Alla stratigrafia della neve",
    "q.l37#3.o3" to "Alla direzione del vento",
    "q.l37#3.e" to "Un indizio in superficie può ridurre l'area di ricerca a poche decine di metri. Tenere gli occhi sull'ARVA fa perdere proprio questi indizi.",

    "q.l37#4.p" to "A quanto va ridotta la distanza nella fase di ricerca grossolana?",
    "q.l37#4.o0" to "A 3–5 metri",
    "q.l37#4.o1" to "A 20 metri",
    "q.l37#4.o2" to "A 0,5 metri",
    "q.l37#4.o3" to "A 10–15 metri",
    "q.l37#4.e" to "Solo dopo i 3–5 metri si passa alla ricerca fine. È il punto in cui si «passa dalla corsa alla camminata», e dove la precisione comincia a contare.",

    "q.l37#5.p" to "Durante la ricerca grossolana la distanza letta aumenta: cosa significa?",
    "q.l37#5.o0" to "Che la direzione è sbagliata e si deve tornare indietro",
    "q.l37#5.o1" to "Che il segnale è troppo forte",
    "q.l37#5.o2" to "Che lo strumento è guasto",
    "q.l37#5.o3" to "Che la persona sepolta si è spostata",
    "q.l37#5.e" to "L'ARVA legge una distanza: se cresce, si sta andando nella direzione opposta. La decisione va presa in fretta, senza continue verifiche sul posto.",

    "q.l37#6.p" to "Qual è il gesto corretto nella fase di ricerca fine?",
    "q.l37#6.o0" to "Avvicinare l'ARVA alla superficie della neve, incrociare le direzioni, trovare il punto di lettura minima e marcarlo",
    "q.l37#6.o1" to "Girare su sé stessi in piedi",
    "q.l37#6.o2" to "Scendere in linea retta lungo il pendio",
    "q.l37#6.o3" to "Infilare la sonda a caso",
    "q.l37#6.e" to "Stare vicini alla neve riduce l'errore dovuto alla rifrazione del segnale. Marcare il punto minimo serve a dare alla sonda un punto di partenza chiaro.",

    "q.l37#7.p" to "Nel sondaggio puntuale, la sonda deve formare 90 gradi con cosa?",
    "q.l37#7.o0" to "Con la superficie della neve (il piano del pendio)",
    "q.l37#7.o1" to "Con il piano orizzontale",
    "q.l37#7.o2" to "Con il pendio, a 45 gradi",
    "q.l37#7.o3" to "Con un angolo qualsiasi",
    "q.l37#7.e" to "Sul pendio, «perpendicolare al suolo» fa attraversare gli strati di traverso e l'angolo del pendio amplifica la profondità letta. Nel soccorso tra compagni si sonda a 90 gradi rispetto alla neve.",

    "q.l37#8.p" to "Se il primo sondaggio non trova nulla, cosa si fa?",
    "q.l37#8.o0" to "Si allarga la ricerca su una maglia di 25 centimetri di lato",
    "q.l37#8.o1" to "Si cambia sonda con una più lunga",
    "q.l37#8.o2" to "Si scava subito con la pala",
    "q.l37#8.o3" to "Si abbandona quel punto",
    "q.l37#8.e" to "25 centimetri (circa 10 pollici) è la maglia standard. Più larga lascia buchi, più stretta fa perdere tempo.",

    "q.l37#9.p" to "Dopo aver toccato un ostacolo duro, come si capisce se è una persona?",
    "q.l37#9.o0" to "Si cerca una resistenza «morbida, elastica, simile a un corpo» e si confronta la profondità con il terreno circostante",
    "q.l37#9.o1" to "Se si tocca qualcosa di duro si scava e basta",
    "q.l37#9.o2" to "Si guarda se sulla sonda c'è sangue",
    "q.l37#9.o3" to "Si ascolta il rumore",
    "q.l37#9.e" to "Rocce e blocchi di ghiaccio danno una resistenza dura e fragile, un corpo è elastico. Inoltre la persona sepolta di norma non è più profonda del terreno attorno.",

    "q.l37#10.p" to "Una volta trovata la persona, cosa si fa con la sonda?",
    "q.l37#10.o0" to "Si lascia infilata sul posto come riferimento di posizione e di profondità",
    "q.l37#10.o1" to "Si estrae subito",
    "q.l37#10.o2" to "Si infila ancora più a fondo",
    "q.l37#10.o3" to "Si passa a un compagno",
    "q.l37#10.e" to "La sonda lasciata sul posto è il «centro del bersaglio» per chi scava, e il riferimento per capire se si sta scavando nel punto giusto.",

    "q.l37#11.p" to "Se la profondità supera la lunghezza della sonda, cosa si fa?",
    "q.l37#11.o0" to "Si tolgono circa 1 metro di neve, si riposiziona con l'ARVA e si sonda di nuovo",
    "q.l37#11.o1" to "Si continua a sondare con forza",
    "q.l37#11.o2" to "Si rinuncia",
    "q.l37#11.o3" to "Si cambia persona alla sonda",
    "q.l37#11.e" to "Insistere non serve, perché non si arriva in fondo. Accorciare la distanza e riposizionare è l'unica procedura che funziona.",

    "q.l37#12.p" to "Perché nel soccorso organizzato la sonda va tenuta verticale (e non perpendicolare alla neve)?",
    "q.l37#12.o0" to "Per avere letture di profondità confrontabili tra i soccorritori e un fronte di sondaggio coerente",
    "q.l37#12.o1" to "Perché si fa meno fatica",
    "q.l37#12.o2" to "Perché è più veloce",
    "q.l37#12.o3" to "Perché lo dice la norma",
    "q.l37#12.e" to "La linea di sondaggio organizzata è una «superficie» e richiede dati di profondità comparabili. Il soccorso tra compagni lavora su un punto solo, quindi la perpendicolare alla neve è più precisa.",

    "q.l37#13.p" to "Quali controlli sull'ARVA si fanno prima di partire?",
    "q.l37#13.o0" to "Batteria carica",
    "q.l37#13.o1" to "Una prova di trasmissione",
    "q.l37#13.o2" to "Saper passare in ricezione, saper marcare e mascherare",
    "q.l37#13.o3" to "Portarlo addosso, non in fondo allo zaino",
    "q.l37#13.e" to "Se ne manca uno, al momento critico non funziona. In fondo allo zaino è l'errore più comune: se lo zaino finisce sotto la neve o si stacca, l'ARVA è perso.",

    "q.l37#14.p" to "Quali sono i punti da controllare su una sonda?",
    "q.l37#14.o0" to "Lunghezza adeguata alla profondità della neve locale",
    "q.l37#14.o1" to "Cordino e bloccaggio integri",
    "q.l37#14.o2" to "Si apre e si blocca con una mano sola",
    "q.l37#14.o3" to "Più leggera è, meglio è",
    "q.l37#14.e" to "Per le squadre di soccorso si consigliano almeno 3 metri (UIAA 157); per uso personale 240–320 centimetri. La leggerezza è un vantaggio, ma contano di più robustezza e affidabilità del bloccaggio.",

    "q.l37#15.p" to "Quando ci sono più persone sepolte, quali comportamenti sono corretti?",
    "q.l37#15.o0" to "Marcare o mascherare il primo segnale",
    "q.l37#15.o1" to "Passare poi al secondo segnale",
    "q.l37#15.o2" to "Non insistere su un solo segnale trascurando le altre zone",
    "q.l37#15.o3" to "Salvare solo il più vicino",
    "q.l37#15.e" to "Con più sepolti il rischio più grande è «trovarne uno solo». Le funzioni di marcatura e mascheramento esistono esattamente per questo.",

    "q.l37#16.p" to "Metti in ordine corretto una ricerca completa.",
    "q.l37#16.o0" to "Tutto il gruppo passa in ricezione e spegne le fonti di disturbo",
    "q.l37#16.o1" to "Ricerca del segnale lungo le corsie",
    "q.l37#16.o2" to "Ricerca grossolana fino a 3–5 metri",
    "q.l37#16.o3" to "Ricerca fine, punto di lettura minima e marcatura",
    "q.l37#16.o4" to "Sondaggio puntuale e sonda lasciata sul posto",
    "q.l37#16.e" to "I cinque passi sono una progressione dalla «superficie» al «punto». Ogni passo che si prova a saltare si paga il doppio in quello successivo.",

    "q.l37#17.p" to "Metti in ordine le operazioni del sondaggio puntuale.",
    "q.l37#17.o0" to "Partire dal punto di lettura minima, sonda a 90 gradi rispetto alla neve",
    "q.l37#17.o1" to "Se non si trova nulla, allargare su maglia di 25 centimetri",
    "q.l37#17.o2" to "Fermarsi quando si sente una resistenza elastica",
    "q.l37#17.o3" to "Lasciare la sonda come riferimento e iniziare lo scavo",
    "q.l37#17.e" to "L'errore più frequente è l'ultimo passo: molti estraggono la sonda appena toccato qualcosa e lo scavo resta senza riferimento.",

    "q.l37#18.p" to "La distanza tra le corsie di ricerca ARVA è di circa ______ metri.",
    "q.l37#18.a0" to "40",
    "q.l37#18.e" to "In caso di dubbio si scende a 30 metri. Una corsia troppo larga lascia passare il segnale: è la causa più comune di ricerca fallita.",

    "q.l37#19.p" to "Il lato della maglia di sondaggio puntuale è di ______ centimetri.",
    "q.l37#19.a0" to "25",
    "q.l37#19.e" to "Circa 10 pollici. Una maglia troppo larga lascia passare il corpo, una troppo stretta fa perdere tempo.",

    "q.l37#20.p" to "Nel soccorso tra compagni la sonda si inserisce a 90 gradi rispetto a ______.",
    "q.l37#20.a0" to "alla superficie della neve",
    "q.l37#20.a1" to "alla neve",
    "q.l37#20.e" to "La perpendicolare al piano orizzontale fa amplificare la profondità letta dall'angolo del pendio: è l'errore geometrico più comune nei principianti.",

    "q.l37#21.p" to "Abbina ogni fase della ricerca al suo obiettivo.",
    "q.l37#21.l0" to "Ricerca del segnale e degli indizi",
    "q.l37#21.l1" to "Ricerca grossolana",
    "q.l37#21.l2" to "Ricerca fine",
    "q.l37#21.l3" to "Sondaggio puntuale",
    "q.l37#21.r0" to "Trovare il primo segnale",
    "q.l37#21.r1" to "Ridurre la distanza a 3–5 metri",
    "q.l37#21.r2" to "Trovare sulla neve il punto più vicino alla persona sepolta",
    "q.l37#21.r3" to "Confermare posizione e profondità con la sonda",
    "q.l37#21.e" to "Quattro obiettivi che convergono progressivamente. Ricordare gli obiettivi, più che i gesti, permette di adattarsi a terreni diversi.",

    "q.l37#22.p" to "Abbina ogni attrezzo al suo requisito essenziale.",
    "q.l37#22.l0" to "ARVA",
    "q.l37#22.l1" to "Sonda",
    "q.l37#22.l2" to "Pala",
    "q.l37#22.l3" to "Casco",
    "q.l37#22.r0" to "Digitale a tre antenne, portato addosso, sa marcare e mascherare",
    "q.l37#22.r1" to "Lunghezza adeguata alla neve, bloccaggio con una mano",
    "q.l37#22.r2" to "Lama metallica, manico affidabile, si estrae in fretta",
    "q.l37#22.r3" to "Indossato per tutta la ricerca e tutto lo scavo",
    "q.l37#22.e" to "Il più trascurato dei quattro è il casco: durante lo scavo cadono ancora blocchi di neve e pezzi di ghiaccio dall'alto.",

    "q.l37#23.p" to "Durante la ricerca qualcuno si ferma a verificare più volte il primo segnale: cosa fai?",
    "q.l37#23.o0" to "Gli ricordi di marcare o mascherare e di continuare a coprire il resto dell'area",
    "q.l37#23.o1" to "Lo lasci continuare",
    "q.l37#23.o2" to "Ti fermi anche tu",
    "q.l37#23.o3" to "Rinunci alla ricerca",
    "q.l37#23.e" to "Con più sepolti, «trovare prima tutti i segnali» conta più che «portare un punto alla perfezione».",

    "q.l37#24.p" to "Perché nella fase di ricerca si chiede di spegnere telefoni e macchine fotografiche?",
    "q.l37#24.o0" to "I dispositivi elettronici disturbano il segnale dell'ARVA e riducono la distanza utile di ricerca",
    "q.l37#24.o1" to "Per risparmiare batteria",
    "q.l37#24.o2" to "Per stare in silenzio",
    "q.l37#24.o3" to "Per non fare fotografie",
    "q.l37#24.e" to "Il disturbo riduce la larghezza utile della corsia e porta indirettamente a cercare male. È la consegna che più spesso viene presa alla leggera.",

    "q.l37#25.p" to "La squadra è di due persone, uno cerca e uno scava: è una divisione sensata?",
    "q.l37#25.o0" to "Sì, ma appena la sonda trova il punto i due devono alternarsi nello scavo, non scavare uno da solo",
    "q.l37#25.o1" to "No, devono cercare insieme",
    "q.l37#25.o2" to "No, devono aspettare i soccorsi",
    "q.l37#25.o3" to "Sì, e non serve alternarsi",
    "q.l37#25.e" to "La chiave in due è «trovato il punto, ci si alterna». Scavare da soli senza sosta porta all'esaurimento in pochi minuti e l'efficienza crolla.",

    "q.l37#26.p" to "Prima di iniziare la ricerca si nota neve sospesa sopra il deposito: cosa si fa?",
    "q.l37#26.o0" to "Si designa prima un osservatore e si sceglie una via di avvicinamento sicura, poi si cerca",
    "q.l37#26.o1" to "Si entra di corsa",
    "q.l37#26.o2" to "Si aspetta che smetta di nevicare",
    "q.l37#26.o3" to "Si rinuncia alla ricerca",
    "q.l37#26.e" to "I soccorritori sepolti da una seconda valanga sono un tipo di incidente reale. Osservatore e via di avvicinamento fanno parte della ricerca, non sono un passaggio in più.",

    "q.l37#27.p" to "Che senso hanno i due obiettivi «10 minuti per il contatto, 18 minuti per lo scavo»?",
    "q.l37#27.o0" to "Sono indicatori interni alla squadra, per allenarsi e per il debriefing: non sono una garanzia",
    "q.l37#27.o1" to "Sono una promessa medica",
    "q.l37#27.o2" to "Sono un obbligo di norma",
    "q.l37#27.o3" to "Sono una prestazione dell'attrezzatura",
    "q.l37#27.e" to "Servono a far capire alla squadra «dove si è perso tempo». Prenderli come promessa fa perdere lucidità proprio quando non vengono rispettati.",
    // ---------- l38 Scavo e nastro trasportatore di neve ----------
    "q.l38#0.p" to "Qual è il primo principio dello scavo?",
    "q.l38#0.o0" to "Lavorare sempre dal lato a valle",
    "q.l38#0.o1" to "Scavare dall'alto verso il basso",
    "q.l38#0.o2" to "Scavare dal lato a monte verso il basso",
    "q.l38#0.o3" to "Scavare di lato, in piano",
    "q.l38#0.e" to "Lavorare a valle dà tre vantaggi: la neve si butta verso il basso, il canale ha pendenza e chi scava non sta sopra la persona sepolta.",

    "q.l38#1.p" to "La regola tradizionale «1,5 volte la profondità» descrive cosa?",
    "q.l38#1.o0" to "La distanza da arretrare lungo il pendio partendo dalla sonda",
    "q.l38#1.o1" to "La larghezza del canale",
    "q.l38#1.o2" to "La lunghezza della sonda",
    "q.l38#1.o3" to "Il tempo di scavo",
    "q.l38#1.e" to "Arretrare serve a creare spazio per smaltire la neve. È una regola empirica, e la ricerca più recente offre un'alternativa.",

    "q.l38#2.p" to "Cosa sostiene la ricerca del 2023 sul nastro trasportatore circa il punto di partenza dello scavo?",
    "q.l38#2.o0" to "Con almeno 3 persone e spazio sufficiente, scavare direttamente dalla sonda lungo la linea di massima pendenza",
    "q.l38#2.o1" to "Arretrare sempre di 1,5 volte la profondità",
    "q.l38#2.o2" to "Scavare dall'alto",
    "q.l38#2.o3" to "Scavare di lato in orizzontale",
    "q.l38#2.e" to "Partire spostati allunga il tempo per arrivare alla testa. La conclusione vale però a condizione di avere personale sufficiente: non si applica sempre.",

    "q.l38#3.p" to "In quali casi è consigliato spostare il punto di partenza dello scavo?",
    "q.l38#3.o0" to "Quando la sepoltura è molto superficiale e i piedi sono quasi alla stessa profondità, oppure con personale insufficiente serve una soluzione a una persona",
    "q.l38#3.o1" to "Sempre",
    "q.l38#3.o2" to "Quando la neve è molto dura",
    "q.l38#3.o3" to "Quando è buio",
    "q.l38#3.e" to "In questi due casi lo spostamento riduce il trasporto inutile. In tutti gli altri, partire dalla sonda è più rapido.",

    "q.l38#4.p" to "Di norma quant'è largo il canale del nastro trasportatore?",
    "q.l38#4.o0" to "1–2 metri",
    "q.l38#4.o1" to "0,3 metri",
    "q.l38#4.o2" to "3–4 metri",
    "q.l38#4.o3" to "Più stretto è, meglio è",
    "q.l38#4.e" to "Troppo stretto e lo smaltimento è inefficiente, troppo largo e il volume da scavare esplode. 1–2 metri è il punto di equilibrio tra efficienza e lavoro.",

    "q.l38#5.p" to "Sotto circa quanti gradi di pendenza la neve rotola di nuovo verso la sonda?",
    "q.l38#5.o0" to "26 gradi",
    "q.l38#5.o1" to "10 gradi",
    "q.l38#5.o2" to "45 gradi",
    "q.l38#5.o3" to "60 gradi",
    "q.l38#5.e" to "26 gradi è il valore critico indicato dalla ricerca. Se la pendenza non basta, la neve buttata fuori scivola di nuovo dentro e il lavoro è vano.",

    "q.l38#6.p" to "Fra le tre tecniche di smaltimento della neve, quale è la più efficiente?",
    "q.l38#6.o0" to "Spazzare (paddling)",
    "q.l38#6.o1" to "Paleggiare (scooping)",
    "q.l38#6.o2" to "Tagliare a blocchi (cutting)",
    "q.l38#6.o3" to "Sono equivalenti",
    "q.l38#6.e" to "Spazzare significa «spingere via» la neve con un gesto continuo e frequente. Tagliare a blocchi serve solo con neve dura, perché prima bisogna ridurla in blocchi.",

    "q.l38#7.p" to "A cosa serve designare un capo scavo?",
    "q.l38#7.o0" to "Guarda la direzione, la neve soprastante e la posizione del sepolto, evitando che tutti tengano la testa bassa a scavare",
    "q.l38#7.o1" to "A controllare il lavoro",
    "q.l38#7.o2" to "A fare fotografie",
    "q.l38#7.o3" to "A risparmiare manodopera",
    "q.l38#7.e" to "Quando tutto il gruppo tiene la testa bassa si scava nella direzione sbagliata e si ignora una seconda valanga. Il capo scavo è l'unico che «alza lo sguardo».",

    "q.l38#8.p" to "Arrivati al viso, in che ordine cambiano le manovre?",
    "q.l38#8.o0" to "Prima liberare bocca e naso e verificare la pervietà delle vie aeree, poi torace e braccia, infine gambe e resto del corpo",
    "q.l38#8.o1" to "Prima le gambe",
    "q.l38#8.o2" to "Prima tirare le spalle",
    "q.l38#8.o3" to "Prima liberare lo zaino",
    "q.l38#8.e" to "Solo se la gabbia toracica può espandersi si può ventilare. Liberare prima le gambe ritarda la ventilazione, tirare le spalle può provocare lesioni alla colonna.",

    "q.l38#9.p" to "Su cosa si basa l'affermazione «si può salvare anche da soli»?",
    "q.l38#9.o0" to "Nelle condizioni dello studio, con il nastro trasportatore a risorse limitate una persona sola arriva a 1,5 metri di profondità in 18 minuti",
    "q.l38#9.o1" to "Sul fatto che le persone hanno potenziale",
    "q.l38#9.o2" to "Sul fatto che la neve è leggera",
    "q.l38#9.o3" to "Sul fatto che il sepolto si libera da solo",
    "q.l38#9.e" to "La velocità di scavo di circa 13,2 cm/min con neve dura e 25,3 cm/min con neve morbida è un dato di ricerca: per questo la soluzione a una persona vale la pena di essere allenata.",

    "q.l38#10.p" to "Qual è all'incirca la velocità di scavo con neve dura e con neve morbida?",
    "q.l38#10.o0" to "Circa 13 cm/min con neve dura, circa 25 cm/min con neve morbida",
    "q.l38#10.o1" to "5 cm/min in entrambi i casi",
    "q.l38#10.o2" to "50 cm/min in entrambi i casi",
    "q.l38#10.o3" to "Con neve dura è più veloce",
    "q.l38#10.e" to "Questa differenza spiega perché le condizioni della neve cambiano le previsioni sui tempi di soccorso, e perché il taglio a blocchi si usa solo con neve dura.",

    "q.l38#11.p" to "Qual è l'errore più comune quando si scava in molti?",
    "q.l38#11.o0" to "Tutti ammassati sullo stesso punto, senza catena di smaltimento né rotazione",
    "q.l38#11.o1" to "Scavare troppo largo",
    "q.l38#11.o2" to "Scavare troppo in fretta",
    "q.l38#11.o3" to "Usare la pala",
    "q.l38#11.e" to "Stare ammassati significa intralciarsi e non reggere il ritmo. La rotazione è molto più rapida di «uno che resiste da solo».",

    "q.l38#12.p" to "Quali ruoli vanno assegnati obbligatoriamente quando si organizza uno scavo?",
    "q.l38#12.o0" to "Capo scavo",
    "q.l38#12.o1" to "Chi scava e chi smaltisce la neve",
    "q.l38#12.o2" to "Osservatore di sicurezza",
    "q.l38#12.o3" to "Chi annota tempi e posizione",
    "q.l38#12.e" to "Quattro ruoli per avere qualcuno responsabile di «direzione, energia, sicurezza e tempo». Se ne manca uno, quel punto va fuori controllo.",

    "q.l38#13.p" to "Quali pratiche riportano indietro la neve già buttata fuori?",
    "q.l38#13.o0" to "Scavare dall'alto o dal lato a monte",
    "q.l38#13.o1" to "Canale con pendenza troppo bassa (sotto circa 26 gradi)",
    "q.l38#13.o2" to "Accumulare la neve sopra la sonda",
    "q.l38#13.o3" to "Disporre il canale lungo la linea di massima pendenza",
    "q.l38#13.e" to "Le prime tre fanno tornare indietro la neve. La quarta è invece la pratica corretta.",

    "q.l38#14.p" to "Sul «punto di partenza dello scavo», quali affermazioni sono corrette?",
    "q.l38#14.o0" to "La regola tradizionale è 1,5 volte la profondità, tagliando di lato dal lato a valle",
    "q.l38#14.o1" to "La semplificazione di Avalanche.org è un passo indietro se la profondità è sotto 1 metro, due passi se è maggiore",
    "q.l38#14.o2" to "ISSW 2023 sostiene che con personale sufficiente si scava dalla sonda lungo la linea di massima pendenza",
    "q.l38#14.o3" to "La regola e la ricerca si contraddicono del tutto: bisogna sceglierne una",
    "q.l38#14.e" to "Le tre versioni sono «un principio più due generazioni di esperienza». Insegnarle nell'ordine principio → regola → aggiornamento evita che la regola diventi superstizione.",

    "q.l38#15.p" to "Metti in ordine corretto uno scavo standard.",
    "q.l38#15.o0" to "Verificare il fronte di lavoro a valle e il rischio di seconda valanga",
    "q.l38#15.o1" to "Aprire un canale a V dal punto di partenza verso la sonda",
    "q.l38#15.o2" to "Organizzare la catena di smaltimento e la rotazione",
    "q.l38#15.o3" to "Arrivati al viso, liberare prima bocca e naso",
    "q.l38#15.e" to "Il senso dell'ordine è «prima la sicurezza, poi l'efficienza, infine la priorità alle vie aeree».",

    "q.l38#16.p" to "Metti in ordine le operazioni dopo l'arrivo al viso.",
    "q.l38#16.o0" to "Liberare bocca e naso da neve e schegge di ghiaccio, verificare le vie aeree",
    "q.l38#16.o1" to "Liberare torace e braccia perché la gabbia toracica possa espandersi",
    "q.l38#16.o2" to "Liberare gambe e resto del corpo",
    "q.l38#16.o3" to "Applicare le regole di rianimazione e organizzare il trasporto",
    "q.l38#16.e" to "Questo ordine è l'opposto di «prima finire di scavare, poi soccorrere», ma è quello giusto: la finestra per ventilare dura pochi minuti.",

    "q.l38#17.p" to "La pendenza critica del canale del nastro trasportatore è di circa ______ gradi.",
    "q.l38#17.a0" to "26",
    "q.l38#17.e" to "Sotto questo angolo i blocchi di neve rotolano di nuovo verso la sonda e l'efficienza dello smaltimento crolla.",

    "q.l38#18.p" to "La regola tradizionale consiglia di partire a circa ______ volte la profondità, arretrando lungo il pendio dalla sonda.",
    "q.l38#18.a0" to "1,5",
    "q.l38#18.a1" to "1.5",
    "q.l38#18.e" to "1,5 è una regola empirica. Con personale sufficiente conviene partire direttamente dalla sonda lungo la linea di massima pendenza.",

    "q.l38#19.p" to "L'obiettivo nel soccorso tra compagni è il contatto entro ______ minuti e lo scavo completato entro 18 minuti.",
    "q.l38#19.a0" to "10",
    "q.l38#19.e" to "10 / 18 sono indicatori interni di allenamento e debriefing, utili a capire «dove si è perso tempo».",

    "q.l38#20.p" to "Abbina ogni tecnica di smaltimento alle sue condizioni d'uso.",
    "q.l38#20.l0" to "Spazzare (paddling)",
    "q.l38#20.l1" to "Paleggiare (scooping)",
    "q.l38#20.l2" to "Tagliare a blocchi (cutting)",
    "q.l38#20.l3" to "Catena di smaltimento (conveyor)",
    "q.l38#20.r0" to "La più efficiente, adatta alla maggior parte della neve sciolta",
    "q.l38#20.r1" to "La seconda, adatta a portare la neve fuori dal canale",
    "q.l38#20.r2" to "La più lenta, si usa solo con neve dura",
    "q.l38#20.r3" to "Il modo di organizzare il lavoro in tanti",
    "q.l38#20.e" to "L'ordine di efficienza impone «prima spazzare, poi paleggiare, tagliare solo con neve dura». La catena non è una tecnica, è un'organizzazione.",

    "q.l38#21.p" to "Abbina ogni errore comune alla sua conseguenza.",
    "q.l38#21.l0" to "Scavare dal lato a monte",
    "q.l38#21.l1" to "Canale con pendenza troppo bassa",
    "q.l38#21.l2" to "Tirare il corpo appena toccata la persona",
    "q.l38#21.l3" to "Estrarre la sonda dopo aver trovato il punto",
    "q.l38#21.r0" to "I blocchi rotolano sul viso: lento e pericoloso",
    "q.l38#21.r1" to "La neve rifluisce e va smaltita più volte",
    "q.l38#21.r2" to "Può aggravare lesioni alla colonna e spingere neve in bocca e naso",
    "q.l38#21.r3" to "Si perde il riferimento di posizione e profondità",
    "q.l38#21.e" to "Sono quattro errori molto comuni e tutti evitabili con un allenamento fatto prima.",

    "q.l38#22.p" to "La neve è dura e la squadra è di tre persone: come si sceglie il punto di partenza?",
    "q.l38#22.o0" to "Dalla sonda lungo la linea di massima pendenza, usando il taglio a blocchi nel tratto di neve dura",
    "q.l38#22.o1" to "Arretrare di 3 volte la profondità",
    "q.l38#22.o2" to "Scavare dall'alto",
    "q.l38#22.o3" to "Aspettare l'attrezzatura",
    "q.l38#22.e" to "Con personale sufficiente si segue la linea di massima pendenza; la neve dura cambia solo la tecnica (taglio a blocchi), non il principio.",

    "q.l38#23.p" to "Perché «scavare tutti insieme con foga» non è più veloce?",
    "q.l38#23.o0" to "Ci si intralcia, non si regge il ritmo e nessuno guarda la neve soprastante",
    "q.l38#23.o1" to "Perché in tanti si suda",
    "q.l38#23.o2" to "Perché le pale non bastano",
    "q.l38#23.o3" to "Perché manca un capo",
    "q.l38#23.e" to "Scavare è un'attività ad altissima intensità: in pochi minuti si esaurisce. Rotazione, capo scavo e catena di smaltimento trasformano la manodopera in velocità.",

    "q.l38#24.p" to "Durante lo scavo si trova un grosso blocco duro accanto alla persona sepolta: cosa si fa?",
    "q.l38#24.o0" to "Liberare prima il passaggio per le vie aeree, senza ritardare la ventilazione per spostare il blocco",
    "q.l38#24.o1" to "Spostare prima il blocco",
    "q.l38#24.o2" to "Romperlo con la piccozza",
    "q.l38#24.o3" to "Girarci attorno",
    "q.l38#24.e" to "Il blocco si gestisce dopo. La finestra per le vie aeree dura pochi minuti e ha priorità sul «fare pulizia» della scena.",

    "q.l38#25.p" to "Se sul posto c'è una sola pala, cosa conviene fare?",
    "q.l38#25.o0" to "Fa scavare chi ha più energia, gli altri spingono la neve con mani e sci, alternandosi",
    "q.l38#25.o1" to "Uno scava fino in fondo",
    "q.l38#25.o2" to "Aspettare una seconda pala",
    "q.l38#25.o3" to "Usare lo zaino al posto della pala",
    "q.l38#25.e" to "La soluzione corretta con una sola pala è il «nastro trasportatore a risorse limitate»: uno scava, gli altri portano fuori la neve.",

    "q.l38#26.p" to "Nel debriefing risulta che «il contatto ha richiesto 14 minuti»: su quale fase conviene riflettere?",
    "q.l38#26.o0" to "Sulla ricerca e localizzazione: quale delle quattro fasi è stata lenta",
    "q.l38#26.o1" to "Sulla fase di scavo",
    "q.l38#26.o2" to "Sulla fase di chiamata dei soccorsi",
    "q.l38#26.o3" to "Sull'acquisto dell'attrezzatura",
    "q.l38#26.e" to "Il tempo di contatto dipende da ricerca e localizzazione, mentre lo scavo determina il «tempo di estrazione». Sono due indicatori da leggere separatamente.",
    // ---------- l42 Principi di sicurezza e gestione del rischio ----------
    "q.l42#0.p" to "Cosa significa il principio «quattro, tre, tre»?",
    "q.l42#0.o0" to "Lasciare un terzo di margine su energia, tempo e materiale",
    "q.l42#0.o1" to "Tre persone, tre ore, tre itinerari",
    "q.l42#0.o2" to "Tre attrezzi, tre tipi di meteo",
    "q.l42#0.o3" to "Tre controlli, tre conferme",
    "q.l42#0.e" to "Tenere margine non è prudenza eccessiva: è mettere l'imprevisto a budget fin dall'inizio. Se si consuma tutto, alla prima variazione resta solo la fortuna.",

    "q.l42#1.p" to "Quali sono le tre «novità» di «tre novità, non si parte»?",
    "q.l42#1.o0" to "Itinerario nuovo, compagni nuovi, attrezzatura nuova",
    "q.l42#1.o1" to "Stagione nuova, meteo nuovo, quota nuova",
    "q.l42#1.o2" to "Programma nuovo, budget nuovo, obiettivo nuovo",
    "q.l42#1.o3" to "Guida nuova, auto nuova, scarpe nuove",
    "q.l42#1.e" to "Ogni «novità» è un'incognita. Sommarne tre significa portare l'incertezza al massimo in una sola uscita.",

    "q.l42#2.p" to "Perché «prima ridurre le conseguenze, poi la probabilità»?",
    "q.l42#2.o0" to "Una conseguenza, una volta accaduta, non si recupera, mentre la probabilità si può solo ridurre, non eliminare",
    "q.l42#2.o1" to "Perché ridurre le conseguenze costa meno",
    "q.l42#2.o2" to "Perché la probabilità non è calcolabile",
    "q.l42#2.o3" to "L'ordine non conta",
    "q.l42#2.e" to "Procedere in cordata, indossare il casco, tenere libera una via di ritirata: sono tutte misure «anche se accade, non è fatale». Funzionano molto meglio di «stare attenti».",

    "q.l42#3.p" to "Qual è l'ordine corretto del principio STOP?",
    "q.l42#3.o0" to "Fermarsi, pensare, osservare, pianificare",
    "q.l42#3.o1" to "Osservare, fermarsi, pensare, pianificare",
    "q.l42#3.o2" to "Pensare, osservare, fermarsi, pianificare",
    "q.l42#3.o3" to "Fermarsi, osservare, pensare, pianificare",
    "q.l42#3.e" to "Solo fermandosi si può davvero pensare e osservare. Sotto pressione la prima reazione è continuare a camminare: è l'azione predefinita più pericolosa.",

    "q.l42#4.p" to "A cosa serve, in un piano, la voce «in quali casi si rinuncia»?",
    "q.l42#4.o0" to "A spostare la decisione fuori dalla pressione emotiva e dall'obiettivo",
    "q.l42#4.o1" to "A scrivere un piano più completo",
    "q.l42#4.o2" to "A superare i controlli",
    "q.l42#4.o3" to "A nulla di concreto",
    "q.l42#4.e" to "In montagna, con la stanchezza e la pressione dell'obiettivo, decidere sul momento di rinunciare è quasi impossibile. Solo la condizione scritta prima ha forza.",

    "q.l42#5.p" to "Quale NON fa parte dei tre cardini per un campo sicuro?",
    "q.l42#5.o0" to "Piazzare il campo il più vicino possibile all'acqua",
    "q.l42#5.o1" to "Evitare le trappole del terreno",
    "q.l42#5.o2" to "Tenere libera una via di evacuazione",
    "q.l42#5.o3" to "Raccogliere i materiali critici in un punto solo",
    "q.l42#5.e" to "Accamparsi a ridosso dell'acqua è lo scenario tipico degli incidenti da piena. Il senso dei tre cardini è «prima garantire di potersene andare», il panorama e la comodità vengono dopo.",

    "q.l42#6.p" to "La squadra ha appena cambiato attrezzatura e sta percorrendo un itinerario nuovo: secondo la regola delle «tre novità» cosa si fa?",
    "q.l42#6.o0" to "Togliere almeno una delle due, oppure abbassare la difficoltà fino a poter verificare l'attrezzatura",
    "q.l42#6.o1" to "Nessun problema, l'attrezzatura nuova è più sicura",
    "q.l42#6.o2" to "Accelerare il ritmo",
    "q.l42#6.o3" to "Separarsi",
    "q.l42#6.e" to "L'attrezzatura nuova va verificata, l'itinerario nuovo va assimilato. Con due novità insieme, se qualcosa va storto non si capisce la causa.",

    "q.l42#7.p" to "Riguardo a «rischio = conseguenza × probabilità», quale affermazione è corretta?",
    "q.l42#7.o0" to "Con conseguenze molto gravi, anche una probabilità bassa va gestita",
    "q.l42#7.o1" to "Se la probabilità è bassa si può ignorare",
    "q.l42#7.o2" to "Basta guardare la probabilità",
    "q.l42#7.o3" to "Basta guardare la conseguenza",
    "q.l42#7.e" to "Il senso del prodotto è questo: quando la conseguenza è abbastanza grande, anche un evento molto improbabile deve essere coperto da un piano.",

    "q.l42#8.p" to "Quali misure riducono la conseguenza?",
    "q.l42#8.o0" to "Procedere in cordata e allestire ancoraggi",
    "q.l42#8.o1" to "Indossare il casco",
    "q.l42#8.o2" to "Tenere libera una via di ritirata",
    "q.l42#8.o3" to "Migliorare la forma fisica",
    "q.l42#8.e" to "Le prime tre riducono il danno «quando accade». Migliorare la forma fisica abbassa la probabilità, non la conseguenza.",

    "q.l42#9.p" to "Quali misure riducono la probabilità?",
    "q.l42#9.o0" to "Consultare meteo e bollettino valanghe",
    "q.l42#9.o1" to "Aclimatarsi in anticipo",
    "q.l42#9.o2" to "Scegliere itinerari collaudati",
    "q.l42#9.o3" to "Portare una sola radio",
    "q.l42#9.e" to "Le prime tre riducono le occasioni di incontrare il pericolo. L'ultima non ha rapporto con il rischio e anzi toglie ridondanza.",

    "q.l42#10.p" to "In quali situazioni va attivato lo STOP?",
    "q.l42#10.o0" to "Ci si accorge che l'itinerario non corrisponde alla carta",
    "q.l42#10.o1" to "Il tempo cambia in modo evidente in poco tempo",
    "q.l42#10.o2" to "Un compagno è in condizioni anomale ma non sa spiegare perché",
    "q.l42#10.o3" to "Si è mezz'ora indietro sulla tabella di marcia",
    "q.l42#10.e" to "Le prime tre sono segnali di «informazione diversa dalle attese». Mezz'ora di ritardo è una fluttuazione normale: prima si ricontrolla l'orario, poi si decide.",

    "q.l42#11.p" to "Metti in ordine la gestione di un rischio.",
    "q.l42#11.o0" to "Riconoscere i fattori di pericolo (terreno, meteo, condizioni delle persone)",
    "q.l42#11.o1" to "Valutare conseguenza e probabilità",
    "q.l42#11.o2" to "Scegliere prima le misure che riducono la conseguenza",
    "q.l42#11.o3" to "Applicare e fissare un momento di verifica",
    "q.l42#11.e" to "L'ultimo passo è il più trascurato: senza un momento di verifica, le misure smettono di funzionare senza che nessuno se ne accorga.",

    "q.l42#12.p" to "Metti in ordine il controllo delle «tre novità», prima di partire.",
    "q.l42#12.o0" to "Elencare itinerario nuovo, compagni nuovi e attrezzatura nuova di questa uscita",
    "q.l42#12.o1" to "Valutare l'incognita che ciascuna voce porta",
    "q.l42#12.o2" to "Decidere quale togliere o quanto abbassare la difficoltà",
    "q.l42#12.o3" to "Scrivere la decisione nel piano e comunicarla ai compagni",
    "q.l42#12.e" to "Il punto chiave è il terzo: togliere una voce è una decisione attiva, non un «poi staremo attenti».",

    "q.l42#13.p" to "Il principio «quattro, tre, tre» lascia ______ di margine su energia, tempo e materiale.",
    "q.l42#13.a0" to "un terzo",
    "q.l42#13.a1" to "1/3",
    "q.l42#13.a2" to "un terzo circa",
    "q.l42#13.e" to "Un terzo è un valore empirico. Più si consuma il margine, meno spazio resta quando arriva un cambiamento.",

    "q.l42#14.p" to "Il rischio è uguale alla conseguenza moltiplicata per ______.",
    "q.l42#14.a0" to "la probabilità",
    "q.l42#14.a1" to "la probabilità che accada",
    "q.l42#14.e" to "Scomporre il rischio in due fattori permette di capire «quale dei due abbassare»: di norma prima la conseguenza.",

    "q.l42#15.p" to "Con «tre novità, non si parte», conviene avere al massimo ______ «novità» nella stessa uscita.",
    "q.l42#15.a0" to "1",
    "q.l42#15.a1" to "una",
    "q.l42#15.a2" to "2",
    "q.l42#15.a3" to "due",
    "q.l42#15.e" to "Una è l'ideale, due è già il limite. Con tre, il piano poggia su tre incognite contemporaneamente.",

    "q.l42#16.p" to "Abbina ogni misura al suo effetto.",
    "q.l42#16.l0" to "Procedere in cordata",
    "q.l42#16.l1" to "Consultare il bollettino valanghe",
    "q.l42#16.l2" to "Tenere libera una via di ritirata",
    "q.l42#16.l3" to "Aclimatarsi in anticipo",
    "q.l42#16.r0" to "Riduce la conseguenza (la caduta non è più a carico di uno solo)",
    "q.l42#16.r1" to "Riduce la probabilità (si evitano i giorni ad alto rischio)",
    "q.l42#16.r2" to "Riduce la conseguenza (se peggiora, si può uscire)",
    "q.l42#16.r3" to "Riduce la probabilità (meno mal di montagna)",
    "q.l42#16.e" to "La differenza tra le quattro sta nel «cambiare il risultato» o «cambiare la probabilità». Capirlo dice dove investire.",

    "q.l42#17.p" to "Abbina ogni principio al suo ambito d'uso.",
    "q.l42#17.l0" to "Quattro, tre, tre",
    "q.l42#17.l1" to "Tre novità, non si parte",
    "q.l42#17.l2" to "STOP",
    "q.l42#17.l3" to "Conseguenza × probabilità",
    "q.l42#17.r0" to "Ripartizione di tempi e risorse",
    "q.l42#17.r1" to "Scelte e rinunce prima di partire",
    "q.l42#17.r2" to "Sul posto, quando ci si accorge che qualcosa non torna",
    "q.l42#17.r3" to "Scelta tra più alternative",
    "q.l42#17.e" to "I quattro strumenti servono a «pianificare, preparare, gestire sul posto, scegliere». Non si sostituiscono: lavorano in fasi diverse.",
    // ---------- l43 Vita al campo e cura personale ----------
    "q.l43#0.p" to "Quali sono le tre cause principali dei problemi di pelle in quota?",
    "q.l43#0.o0" to "Secchezza, raggi ultravioletti, vento",
    "q.l43#0.o1" to "Freddo, umidità, sfregamento",
    "q.l43#0.o2" to "Carenza di ossigeno, bassa pressione, basse temperature",
    "q.l43#0.o3" to "Alimentazione, sonno, stress",
    "q.l43#0.e" to "Queste tre cose agiscono insieme e la barriera cutanea si rompe in fretta. Idratare e proteggere dal sole non è un lusso, è mantenere la capacità di lavorare.",

    "q.l43#1.p" to "Qual è l'uso corretto di una piastra scalda-corpo?",
    "q.l43#1.o0" to "Sulla zona lombare, sull'addome o all'esterno dello scarpone, mai direttamente sulla pelle",
    "q.l43#1.o1" to "Direttamente sulla pelle",
    "q.l43#1.o2" to "Sulla fronte",
    "q.l43#1.o3" to "Su tutto il corpo quando si dorme",
    "q.l43#1.e" to "Applicata sulla pelle può provocare ustioni a bassa temperatura, che in quota guariscono molto lentamente. Serve a contrastare l'abbassamento della temperatura centrale.",

    "q.l43#2.p" to "Come si smaltisce correttamente l'acqua per lavare i piatti?",
    "q.l43#2.o0" to "Filtrare i residui e disperdere l'acqua, portando via i residui",
    "q.l43#2.o1" to "Versarla nel torrente",
    "q.l43#2.o2" to "Versarla accanto alla tenda",
    "q.l43#2.o3" to "Versarla nella buca della latrina",
    "q.l43#2.e" to "I residui sono inquinamento e richiamo per gli animali. Filtrare e portare via, disperdendo l'acqua, è la pratica a basso impatto.",

    "q.l43#3.p" to "Perché lo strato intimo va lavato per primo?",
    "q.l43#3.o0" to "Il sale del sudore irrita e rompe la pelle, e in quota una lesione guarisce male",
    "q.l43#3.o1" to "Perché è più bello",
    "q.l43#3.o2" to "Perché pesa poco",
    "q.l43#3.o3" to "Perché costa poco",
    "q.l43#3.e" to "Sale e batteri sullo strato intimo irritano la pelle in continuazione. Una lesione, con secchezza e freddo, può restare aperta per settimane.",

    "q.l43#4.p" to "Il piumino si è sporcato o bagnato: cosa si fa?",
    "q.l43#4.o0" to "Non si lava: si scrolla la neve in superficie e si lascia asciugare",
    "q.l43#4.o1" to "Si strofina con detersivo",
    "q.l43#4.o2" to "Si strizza",
    "q.l43#4.o3" to "Si asciuga sul fuoco",
    "q.l43#4.e" to "Dopo il lavaggio è quasi impossibile recuperare il gonfiante sul campo. Bagnato si lascia asciugare, non si mette sul fuoco: il calore rovina tessuto e piuma.",

    "q.l43#5.p" to "Quale NON fa parte delle tre regole d'ordine al campo?",
    "q.l43#5.o0" to "Mettere il cibo in tenda per la notte",
    "q.l43#5.o1" to "Scarpe nell'abside",
    "q.l43#5.o2" to "Cibo fuori dalla tenda",
    "q.l43#5.o3" to "Rifiuti raccolti e appesi in alto",
    "q.l43#5.e" to "Il cibo in tenda porta gli animali direttamente nella zona dove si dorme e lascia l'odore a lungo sul sacco. Le tre regole insieme prevengono umidità, animali e contaminazione.",

    "q.l43#6.p" to "Perché in quota è importante proteggere le labbra?",
    "q.l43#6.o0" to "Le labbra non hanno melanina a proteggerle e, una volta screpolate, mangiare e parlare fanno male",
    "q.l43#6.o1" to "Perché è più bello",
    "q.l43#6.o2" to "Perché si abbronzano",
    "q.l43#6.o3" to "Perché si gonfiano",
    "q.l43#6.e" to "Le labbra sono la zona più trascurata nella protezione solare ed è quella che «facendo male» compromette l'alimentazione. Il burrocacao va tenuto addosso.",

    "q.l43#7.p" to "Come va organizzato il tempo per la cura personale?",
    "q.l43#7.o0" to "Come una breve routine fissa ogni giorno (pochi minuti mattina e sera), non «quando c'è tempo»",
    "q.l43#7.o1" to "Quando c'è il sole",
    "q.l43#7.o2" to "Una volta alla settimana",
    "q.l43#7.o3" to "Secondo l'umore",
    "q.l43#7.e" to "Il valore della cura viene dalla continuità. Una routine fissa si esegue anche da stanchi; decidere sul momento di solito significa saltarla.",

    "q.l43#8.p" to "Quali oggetti vanno «uno per persona, con il nome sopra»?",
    "q.l43#8.o0" to "Le posate",
    "q.l43#8.o1" to "Gli articoli per l'igiene",
    "q.l43#8.o2" to "La tazza",
    "q.l43#8.o3" to "La tenda",
    "q.l43#8.e" to "I primi tre sono oggetti che vanno in bocca o toccano la pelle: condividerli trasmette problemi intestinali e cutanei. La tenda si assegna per persona, non serve marcarla.",

    "q.l43#9.p" to "Quali azioni di cura vanno fatte ogni giorno in quota?",
    "q.l43#9.o0" to "Mettere la protezione solare (anche sulle labbra)",
    "q.l43#9.o1" to "Idratare la pelle",
    "q.l43#9.o2" to "Cambiare calze asciutte e far asciugare gli scarponi",
    "q.l43#9.o3" to "Fare la doccia ogni giorno",
    "q.l43#9.e" to "Le prime tre determinano direttamente lo stato della pelle e dei piedi. La doccia quotidiana in quota non è realistica né necessaria: basta la pulizia locale.",

    "q.l43#10.p" to "Quali situazioni vanno evitate con le piastre scalda-corpo?",
    "q.l43#10.o0" to "Applicarle direttamente sulla pelle",
    "q.l43#10.o1" to "Tenerle a lungo sullo stesso punto mentre si dorme",
    "q.l43#10.o2" to "Applicarle su una parte già congelata",
    "q.l43#10.o3" to "Applicarle sulla zona lombare",
    "q.l43#10.e" to "Le prime tre possono causare ustioni a bassa temperatura o aggravare il danno quando la sensibilità è ridotta. La zona lombare è un punto d'uso normale.",

    "q.l43#11.p" to "Metti in ordine la routine appena arrivati al campo.",
    "q.l43#11.o0" to "Togliere lo strato intimo bagnato e aggiungere uno strato caldo",
    "q.l43#11.o1" to "Montare la tenda, stendere il materassino, far asciugare scarponi e calze",
    "q.l43#11.o2" to "Bollire l'acqua, mangiare, bere",
    "q.l43#11.o3" to "Seguire la routine di cura (sole, idratazione, labbra, piccole lesioni)",
    "q.l43#11.e" to "Il senso dell'ordine è «fermare prima la perdita di calore». Cucinare prima di cambiarsi è l'errore più comune.",

    "q.l43#12.p" to "La piastra scalda-corpo va messa sulla zona lombare, sull'addome o all'esterno dello scarpone, mai direttamente sulla ______.",
    "q.l43#12.a0" to "pelle",
    "q.l43#12.a1" to "cute",
    "q.l43#12.e" to "Sulla pelle può causare ustioni a bassa temperatura, e un'ustione in quota guarisce con grande difficoltà.",

    "q.l43#13.p" to "La regola d'ordine del campo impone che il cibo non entri in ______.",
    "q.l43#13.a0" to "tenda",
    "q.l43#13.a1" to "tenda da sonno",
    "q.l43#13.e" to "L'odore del cibo attira gli animali nella zona dove si dorme e resta a lungo su sacco a pelo e vestiti.",

    "q.l43#14.p" to "Abbina ogni azione di cura al problema che previene.",
    "q.l43#14.l0" to "Protezione solare e burrocacao",
    "q.l43#14.l1" to "Idratazione della pelle",
    "q.l43#14.l2" to "Cambiare con calze asciutte",
    "q.l43#14.l3" to "Piastra scalda-corpo",
    "q.l43#14.r0" to "Scottature da raggi ultravioletti (compreso il rischio di cecità da neve)",
    "q.l43#14.r1" to "Pelle secca e barriera cutanea compromessa",
    "q.l43#14.r2" to "Vesciche e macerazione",
    "q.l43#14.r3" to "Abbassamento della temperatura centrale",
    "q.l43#14.e" to "Quattro azioni per quattro problemi. Nessuna è difficile: difficile è farle ogni giorno.",

    "q.l43#15.p" to "Lavare i vestiti in quota: qual è la soluzione più realistica?",
    "q.l43#15.o0" to "Lavare solo lo strato intimo, con poco detersivo e sciacquo abbondante, e asciugarlo dentro la tenda",
    "q.l43#15.o1" to "Lavare tutto",
    "q.l43#15.o2" to "Non lavare nulla",
    "q.l43#15.o3" to "Strofinare con la neve",
    "q.l43#15.e" to "Acqua e combustibile sono preziosi. Lo strato intimo è l'unico che va davvero lavato; per il resto bastano aria e scrollate.",

    "q.l43#16.p" to "In quota, ogni quanto si consiglia di riapplicare la protezione solare?",
    "q.l43#16.o0" to "Ogni 2–3 ore, e dopo aver sudato o dopo la fusione della neve sulla pelle",
    "q.l43#16.o1" to "Una volta al mattino",
    "q.l43#16.o2" to "Una volta al giorno",
    "q.l43#16.o3" to "Mai",
    "q.l43#16.e" to "Raggi intensi, vento e riflesso della neve consumano in fretta il filtro. Riapplicare conta più che scegliere un fattore alto.",

    "q.l43#17.p" to "Uscire dalla tenda di notte: cosa si trascura più spesso?",
    "q.l43#17.o0" to "Mettere gli scarponi o le scarpe da campo, invece di camminare sulla neve con i soli calzini",
    "q.l43#17.o1" to "Portare la macchina fotografica",
    "q.l43#17.o2" to "Portare l'acqua",
    "q.l43#17.o3" to "Mettere il cappello",
    "q.l43#17.e" to "Calzini bagnati significano una notte al freddo e più rischio di congelamenti e ipotermia. Le scarpe da campo sono l'attrezzo più semplice ed efficace.",

    "q.l43#18.p" to "Come vanno pianificati i consumabili tipo salviette e fazzoletti?",
    "q.l43#18.o0" to "Divisi per giorno, con una scorta di riserva, al riparo dall'umidità",
    "q.l43#18.o1" to "Confezione intera",
    "q.l43#18.o2" to "Portarne molti di più",
    "q.l43#18.o3" to "Non portarli",
    "q.l43#18.e" to "La confezione intera si bagna e occupa spazio. Dividere per giorno controlla il consumo e lascia una riserva se il resto si bagna.",

    "q.l43#19.p" to "Quale articolo di cura personale conviene portare in doppia copia?",
    "q.l43#19.o0" to "Burrocacao e protezione solare",
    "q.l43#19.o1" to "Lo shampoo",
    "q.l43#19.o2" to "Il profumo",
    "q.l43#19.o3" to "Il rasoio",
    "q.l43#19.e" to "Sono due oggetti piccoli, impossibili da sostituire se persi, e che influenzano direttamente l'alimentazione e la barriera cutanea.",
    // ---------- l39 Leadership e ruoli nella squadra ----------
    "q.l39#0.p" to "Qual è la definizione più precisa di leadership?",
    "q.l39#0.o0" to "Il comportamento con cui si influenza il gruppo e lo si rende disposto a raggiungere un obiettivo insieme",
    "q.l39#0.o1" to "Quello che dice chi ha un titolo",
    "q.l39#0.o2" to "Chi è più forte guida",
    "q.l39#0.o3" to "Decide chi ha più anzianità",
    "q.l39#0.e" to "Se la leadership è un comportamento e non una carica, nella squadra compaiono più persone disposte a segnalare i problemi: ed è una forma di ridondanza per la sicurezza.",

    "q.l39#1.p" to "Come si dividono competenze tecniche e competenze relazionali?",
    "q.l39#1.o0" to "Le competenze tecniche dicono «se si può fare», quelle relazionali «se la squadra vuole farlo insieme»",
    "q.l39#1.o1" to "Contano di più le competenze tecniche",
    "q.l39#1.o2" to "Le competenze relazionali sono solo gentilezze",
    "q.l39#1.o3" to "Non hanno rapporto tra loro",
    "q.l39#1.e" to "Saper fare tecnicamente ma non riuscire a far eseguire al gruppo equivale a non aver fatto nulla. In alta montagna il tasso di esecuzione lo decide spesso la parte relazionale.",

    "q.l39#2.p" to "Cosa sono i «tre livelli di responsabilità»?",
    "q.l39#2.o0" to "Comportamento, pensiero, emozione",
    "q.l39#2.o1" to "Pianificazione, esecuzione, debriefing",
    "q.l39#2.o2" to "Capo, vice, membri",
    "q.l39#2.o3" to "Salita, vetta, discesa",
    "q.l39#2.e" to "Guardare solo il comportamento lascia fuori il modo di giudicare e lo stato emotivo. Molti problemi che si ripetono hanno la radice nel secondo e nel terzo livello.",

    "q.l39#3.p" to "Cosa spiega il modello dell'iceberg del conflitto?",
    "q.l39#3.o0" to "Sopra l'acqua c'è la posizione, sotto c'è il bisogno",
    "q.l39#3.o1" to "I conflitti nascono tutti dal carattere",
    "q.l39#3.o2" to "I conflitti non si possono risolvere",
    "q.l39#3.o3" to "Se nessuno parla, non c'è conflitto",
    "q.l39#3.e" to "«Devo arrivare in vetta» è la posizione; sotto può esserci «non voglio deludere i compagni». Rispondere al bisogno apre lo spazio per muovere la posizione.",

    "q.l39#4.p" to "Qual è il rischio dell'«alone dell'esperto»?",
    "q.l39#4.o0" to "Scambiare sicurezza in sé e attrezzatura tecnica per competenza, finché nessuno osa contestare un errore evidente",
    "q.l39#4.o1" to "Che l'esperto costi troppo",
    "q.l39#4.o2" to "Che l'esperto non obbedisca",
    "q.l39#4.o3" to "Che l'esperto sia poco allenato",
    "q.l39#4.e" to "L'alone soffoca le obiezioni. Lo stato più pericoloso per una squadra non è «nessuno sa», ma «nessuno osa dire: aspetta, qui non torna».",

    "q.l39#5.p" to "Qual è il compito più importante di chi segue?",
    "q.l39#5.o0" to "Fare domande, dare riscontri e dire chiaramente «basta» quando è il momento",
    "q.l39#5.o1" to "Obbedire senza discutere",
    "q.l39#5.o2" to "Non dare fastidio",
    "q.l39#5.o3" to "Restare in silenzio",
    "q.l39#5.e" to "Il diritto di fermare il gruppo va riconosciuto a ciascuno, non riservato al capo. Va detto esplicitamente prima di partire.",

    "q.l39#6.p" to "Quando va fissato il turnaround time (l'ora limite di rientro)?",
    "q.l39#6.o0" to "Prima di partire, comunicandolo a tutta la squadra",
    "q.l39#6.o1" to "Poco prima della vetta",
    "q.l39#6.o2" to "Secondo l'umore",
    "q.l39#6.o3" to "Lo decide il più veloce",
    "q.l39#6.e" to "In montagna, con la stanchezza e la pressione dell'obiettivo, un limite deciso sul momento viene quasi sempre spostato. Solo quello fissato prima ha forza.",

    "q.l39#7.p" to "Qual è il tipico abuso del ruolo da parte di un capo?",
    "q.l39#7.o0" to "Usare la carica contro il giudizio, trattando le obiezioni come insubordinazione",
    "q.l39#7.o1" to "Ascoltare le opinioni",
    "q.l39#7.o2" to "Spiegare pubblicamente i criteri della decisione",
    "q.l39#7.o3" to "Ammettere di non essere sicuro",
    "q.l39#7.e" to "La conseguenza diretta della repressione è che l'informazione smette di salire. E l'input più importante per un capo arriva proprio da chi osa parlare.",

    "q.l39#8.p" to "Una persona del gruppo resta sempre in silenzio: qual è la causa più probabile?",
    "q.l39#8.o0" to "Ritiene che parlare non serva, o teme di rovinare i rapporti",
    "q.l39#8.o1" to "Non ha idee",
    "q.l39#8.o2" to "È poco allenata",
    "q.l39#8.o3" to "Non ha capito",
    "q.l39#8.e" to "Il silenzio è di solito il risultato di un «costo di espressione» troppo alto. Il capo deve abbassarlo, per esempio chiedendo per primo al più giovane.",

    "q.l39#9.p" to "Qual è di solito il primo passo per gestire un conflitto?",
    "q.l39#9.o0" to "Costruire fiducia: far sentire l'altro ascoltato",
    "q.l39#9.o1" to "Spiegare la ragione",
    "q.l39#9.o2" to "Votare",
    "q.l39#9.o3" to "Cambiare persona",
    "q.l39#9.e" to "Senza fiducia la spiegazione viene percepita come accusa. Prima si accoglie l'emozione, poi si parla di fatti e soluzioni.",

    "q.l39#10.p" to "Quando «portare la squadra all'obiettivo» entra in conflitto con «tenere tutti al sicuro», quale ha priorità?",
    "q.l39#10.o0" to "La sicurezza: l'obiettivo si può riprovare un'altra volta",
    "q.l39#10.o1" to "L'obiettivo",
    "q.l39#10.o2" to "Decide il voto",
    "q.l39#10.o3" to "Decide chi paga",
    "q.l39#10.e" to "L'obiettivo si ripete, le persone no. Nelle spedizioni commerciali è il punto che la pressione economica distorce più facilmente.",

    "q.l39#11.p" to "Quali comportamenti sono espressione di competenze relazionali?",
    "q.l39#11.o0" to "Spiegare con chiarezza i criteri di una decisione",
    "q.l39#11.o1" to "Mantenere la comunicazione sotto pressione",
    "q.l39#11.o2" to "Chiedere attivamente l'opinione di chi tace",
    "q.l39#11.o3" to "Arrivare in vetta per primo",
    "q.l39#11.e" to "I primi tre riguardano tutti «far circolare l'informazione». La velocità è una capacità, non una forma di leadership.",

    "q.l39#12.p" to "Quali pratiche riducono il rischio dell'«alone dell'esperto»?",
    "q.l39#12.o0" to "Incoraggiare le domande dei meno esperti",
    "q.l39#12.o1" to "Spiegare il motivo delle decisioni",
    "q.l39#12.o2" to "Dare a una persona il compito di fare l'avvocato del diavolo",
    "q.l39#12.o3" to "Far parlare solo i più esperti",
    "q.l39#12.e" to "Le prime tre rendono legittimo il dubbio. L'ultima è esattamente ciò che amplifica l'alone.",

    "q.l39#13.p" to "Quali sono comportamenti legittimi di chi segue?",
    "q.l39#13.o0" to "Esprimere un parere diverso",
    "q.l39#13.o1" to "Chiedere che una decisione venga spiegata",
    "q.l39#13.o2" to "Rifiutarsi di proseguire quando lo ritiene insicuro",
    "q.l39#13.o3" to "Lamentarsi in privato senza dirlo",
    "q.l39#13.e" to "Lamentarsi in privato non cambia le decisioni, accumula solo sfiducia. I primi tre sono «disobbedienza costruttiva».",

    "q.l39#14.p" to "Metti in ordine la gestione di un conflitto.",
    "q.l39#14.o0" to "Lasciar finire l'altro e verificare che cosa hai capito",
    "q.l39#14.o1" to "Distinguere la posizione dal bisogno",
    "q.l39#14.o2" to "Proporre alternative spiegandone il costo",
    "q.l39#14.o3" to "Trovare l'accordo e ripeterlo per conferma",
    "q.l39#14.e" to "Il passo decisivo è il secondo: se il bisogno non viene riconosciuto, la soluzione resta un «ciascuno cede un po'» e torna fuori presto.",

    "q.l39#15.p" to "Metti in ordine il processo di una decisione ad alto rischio.",
    "q.l39#15.o0" to "Definire l'obiettivo e le condizioni non negoziabili",
    "q.l39#15.o1" to "Elencare le opzioni e il costo di ciascuna",
    "q.l39#15.o2" to "Valutare il prodotto di probabilità e conseguenza",
    "q.l39#15.o3" to "Fissare un'ora limite ed eseguire",
    "q.l39#15.o4" to "Correggere sulla base delle informazioni nuove",
    "q.l39#15.e" to "È lo scheletro di un processo in nove passi. Il valore vero sta nel quarto: trasformare «quando bisogna tornare indietro» in un numero deciso prima.",

    "q.l39#16.p" to "L'ora limite di rientro fissata prima di una decisione si indica in inglese con ______ time.",
    "q.l39#16.a0" to "turnaround",
    "q.l39#16.e" to "È lo strumento che trasforma la «determinazione» in «regola». Scritto e comunicato, ha forza.",

    "q.l39#17.p" to "I tre livelli di responsabilità sono comportamento, pensiero e ______.",
    "q.l39#17.a0" to "emozione",
    "q.l39#17.a1" to "sentimento",
    "q.l39#17.e" to "Il livello più trascurato è l'emozione, ed è spesso il primo a dare segnali di problema.",

    "q.l39#18.p" to "Abbina ogni ruolo al suo compito principale.",
    "q.l39#18.l0" to "Capo spedizione",
    "q.l39#18.l1" to "Vice o guida",
    "q.l39#18.l2" to "Membro della squadra",
    "q.l39#18.l3" to "Osservatore di sicurezza",
    "q.l39#18.r0" to "Fissare obiettivi e limiti, rendendo comprensibili le decisioni",
    "q.l39#18.r1" to "Eseguire le manovre tecniche e riportare le informazioni dal campo",
    "q.l39#18.r2" to "Fare domande, dare riscontri e dire basta quando serve",
    "q.l39#18.r3" to "Sorvegliare i rischi dell'ambiente senza partecipare alle manovre",
    "q.l39#18.e" to "I quattro ruoli insieme fanno «informazione, esecuzione, contrappeso». Senza contrappeso la decisione diventa quella di una persona sola.",

    "q.l39#19.p" to "Abbina ogni manifestazione del conflitto al bisogno che sta sotto.",
    "q.l39#19.l0" to "«Devo arrivare in vetta comunque»",
    "q.l39#19.l1" to "«Fa come volete, decidete voi»",
    "q.l39#19.l2" to "«Sto bene, non ho niente»",
    "q.l39#19.l3" to "«Lui è sempre quello che rallenta»",
    "q.l39#19.r0" to "Teme di essere disprezzato dai compagni, ha bisogno di riconoscimento",
    "q.l39#19.r1" to "Non vuole assumersi la responsabilità della scelta, ha bisogno di essere protetto",
    "q.l39#19.r2" to "Non vuole essere un peso, ha bisogno di attenzione",
    "q.l39#19.r3" to "È in ansia per il ritmo, ha bisogno di punti fermi",
    "q.l39#19.e" to "Quattro manifestazioni, quattro bisogni. Solo rispondendo al bisogno si può cambiare il comportamento.",

    "q.l39#20.p" to "Il più esperto dice «questa via l'ho fatta, nessun problema», ma la carta mostra una zona di seracchi più avanti: cosa fai?",
    "q.l39#20.o0" to "Chiedere di controllare insieme carta e terreno, usando i fatti per tarare l'esperienza",
    "q.l39#20.o1" to "Credergli",
    "q.l39#20.o2" to "Smentirlo subito davanti a tutti",
    "q.l39#20.o3" to "Separarsi",
    "q.l39#20.e" to "L'esperienza è un input prezioso, non una conclusione. Verificarla con carta e terreno rispetta la persona senza affidarsi ciecamente.",

    "q.l39#21.p" to "Un membro del gruppo ripete «per me va bene tutto»: qual è la risposta più sensata?",
    "q.l39#21.o0" to "Dargli opzioni concrete tra cui scegliere, invece di una domanda aperta",
    "q.l39#21.o1" to "Prendere per buono che vada bene tutto",
    "q.l39#21.o2" to "Non chiedergli più nulla",
    "q.l39#21.o3" to "Decidere al posto suo e informarlo dopo",
    "q.l39#21.e" to "«Va bene tutto» spesso significa «non voglio subire le conseguenze della scelta». Opzioni concrete abbassano il costo di espressione e fanno emergere l'informazione.",

    "q.l39#22.p" to "Dopo aver deciso di rinunciare, cosa deve essere chiaro al capo?",
    "q.l39#22.o0" to "Il motivo (che cosa ha visto), i limiti (a quali condizioni si rivaluta) e i passi successivi",
    "q.l39#22.o1" to "Solo che non si può non rinunciare",
    "q.l39#22.o2" to "Solo l'emozione del momento",
    "q.l39#22.o3" to "Niente, non serve spiegare",
    "q.l39#22.e" to "Spiegare il motivo trasforma l'«obbedire» in «capire». Chi ha capito sarà il primo a portare informazioni la volta dopo.",

    "q.l39#23.p" to "Perché «votare se proseguire» non è tecnicamente affidabile?",
    "q.l39#23.o0" to "La maggioranza può non avere le informazioni per giudicare, e la pressione distorce ciò che si dice",
    "q.l39#23.o1" to "Perché votare è troppo lento",
    "q.l39#23.o2" to "Perché mancano i votanti",
    "q.l39#23.o3" to "Perché il capo non è d'accordo",
    "q.l39#23.e" to "Il voto trasforma la decisione in una «distribuzione di opinioni», mentre in montagna serve un giudizio basato su informazioni e criteri. Le opinioni si raccolgono, la decisione va motivata.",

    "q.l39#24.p" to "Nel gruppo cala il silenzio, nessuno vuole fare la parte del cattivo: qual è il modo più efficace per romperlo?",
    "q.l39#24.o0" to "Il capo dice per primo la propria preoccupazione, rendendola un tema discutibile",
    "q.l39#24.o1" to "Richiamare pubblicamente qualcuno",
    "q.l39#24.o2" to "Aspettare ancora",
    "q.l39#24.o3" to "Rinunciare senza spiegare",
    "q.l39#24.e" to "Il primo che esprime un dubbio abbassa molto il costo per tutti gli altri. Il capo è la persona più adatta a farlo.",

    "q.l39#25.p" to "Se il capo ha sbagliato una valutazione creando una situazione pericolosa, cosa deve fare?",
    "q.l39#25.o0" to "Ricostruire pubblicamente l'errore e dire che cosa è cambiato, invece di minimizzare",
    "q.l39#25.o1" to "Non parlarne",
    "q.l39#25.o2" to "Attribuirlo al meteo",
    "q.l39#25.o3" to "Cambiare argomento",
    "q.l39#25.e" to "Ammettere un errore aumenta la fiducia invece di ridurla. Minimizzare insegna al gruppo a nascondere: è questo il vero pericolo.",
    // ---------- l40 Nutrizione e rifornimento sopra gli 8.000 m ----------
    "q.l40#0.p" to "Qual è il primo principio dell'alimentazione in alta quota?",
    "q.l40#0.o0" to "Garantire i carboidrati: la cosa più importante è riuscire a mangiarli",
    "q.l40#0.o1" to "Prima le proteine",
    "q.l40#0.o2" to "Prima i grassi",
    "q.l40#0.o3" to "Mangiare poco per alleggerire il carico",
    "q.l40#0.e" to "I carboidrati danno energia in fretta e consumano poco ossigeno: in quota sono la fonte più «conveniente». Quando non si riesce a mangiare, il primo sforzo va fatto sui carboidrati.",

    "q.l40#1.p" to "Fra i tre macronutrienti, quale ha la densità energetica più alta?",
    "q.l40#1.o0" to "I grassi",
    "q.l40#1.o1" to "I carboidrati",
    "q.l40#1.o2" to "Le proteine",
    "q.l40#1.o3" to "Sono uguali",
    "q.l40#1.e" to "I grassi danno circa 9 kcal/g, più del doppio di carboidrati e proteine. È il motivo per cui in quota si preferiscono frutta secca e bustine d'olio.",

    "q.l40#2.p" to "Qual è il problema dell'idea «tanto in montagna passo ai grassi»?",
    "q.l40#2.o0" to "La quota di energia dai grassi richiede un allenamento lungo, non si cambia in pochi giorni",
    "q.l40#2.o1" to "I grassi non piacciono",
    "q.l40#2.o2" to "I grassi pesano troppo",
    "q.l40#2.o3" to "I grassi fanno venire freddo",
    "q.l40#2.e" to "L'adattamento metabolico si misura in settimane o mesi. L'allenamento prima della partenza migliora l'uso dei grassi, ma non si può contare che avvenga sul posto.",

    "q.l40#3.p" to "Quando l'appetito cala in quota, qual è la strategia più efficace?",
    "q.l40#3.o0" to "Piccole quantità frequenti, scegliendo cibi ad alta densità energetica e facili da mandar giù",
    "q.l40#3.o1" to "Forzarsi a fare tre pasti abbondanti",
    "q.l40#3.o2" to "Bere solo bevande sportive",
    "q.l40#3.o3" to "Aspettare di avere fame",
    "q.l40#3.e" to "Con appetito ridotto «mangiare tanto in una volta» è quasi impossibile. Spezzare il totale in molte porzioni piccole è l'unico modo sostenibile.",

    "q.l40#4.p" to "A cosa serve soprattutto la parte di cibo «che si mangia camminando»?",
    "q.l40#4.o0" to "Mantenere il ritmo, integrando energia senza doversi fermare",
    "q.l40#4.o1" to "Dare sazietà",
    "q.l40#4.o2" to "Integrare proteine",
    "q.l40#4.o3" to "Sostituire i pasti",
    "q.l40#4.e" to "Se bisogna fermarsi per mangiare, il ritmo si rompe. Il valore di gel, caramelle gommose e barrette è proprio «non interrompere il movimento».",

    "q.l40#5.p" to "Che effetto ha la disidratazione sull'alimentazione?",
    "q.l40#5.o0" to "Riduce insieme appetito e lucidità, rendendo il deficit energetico più difficile da colmare",
    "q.l40#5.o1" to "Nessun effetto",
    "q.l40#5.o2" to "Aumenta l'appetito",
    "q.l40#5.o3" to "Incide solo sulla sete",
    "q.l40#5.e" to "La mancanza d'acqua toglie la voglia di mangiare e rende imprecisa la percezione di «quanto manca». Bere e mangiare vanno pianificati insieme.",

    "q.l40#6.p" to "Riguardo agli aminoacidi ramificati (BCAA), qual è l'atteggiamento corretto?",
    "q.l40#6.o0" to "Ci sono studi sul rapporto con il metabolismo dell'ammoniaca, ma le prove sono limitate: non sostituiscono le calorie totali",
    "q.l40#6.o1" to "Possono sostituire del tutto il cibo",
    "q.l40#6.o2" to "Più se ne prendono, meglio è",
    "q.l40#6.o3" to "Sono del tutto inutili",
    "q.l40#6.e" to "Gli integratori servono per ottimizzazioni marginali. Se le calorie totali non bastano, nessun integratore compensa.",

    "q.l40#7.p" to "Perché in alta quota il fabbisogno energetico giornaliero aumenta invece di calare?",
    "q.l40#7.o0" to "Freddo, carico e carenza di ossigeno aumentano il dispendio a riposo e il lavoro respiratorio",
    "q.l40#7.o1" to "Perché in quota la gravità è maggiore",
    "q.l40#7.o2" to "Perché si dorme male",
    "q.l40#7.o3" to "Perché si è tesi",
    "q.l40#7.e" to "Il fabbisogno sale e l'appetito scende: è da qui che nasce il deficit energetico d'alta quota. La strategia va costruita su questo contrasto.",

    "q.l40#8.p" to "Come va organizzato il rifornimento nel giorno di vetta?",
    "q.l40#8.o0" to "Un pasto caldo a base di carboidrati prima di partire, poi integrare ogni 45–60 minuti in cammino",
    "q.l40#8.o1" to "Non mangiare prima, per essere più leggeri",
    "q.l40#8.o2" to "Mangiare solo dopo la vetta",
    "q.l40#8.o3" to "Tirare avanti tutto il giorno con il caffè",
    "q.l40#8.e" to "Partire a digiuno esaurisce il glicogeno già nelle prime due ore. Solo integrazioni piccole e frequenti reggono oltre dieci ore.",

    "q.l40#9.p" to "Che significato ha il cibo caldo in alta quota?",
    "q.l40#9.o0" to "Fornisce calore, acqua e sostegno psicologico, ed è più facile da accettare",
    "q.l40#9.o1" to "È solo un rito",
    "q.l40#9.o2" to "Serve a integrare proteine",
    "q.l40#9.o3" to "Aiuta a digerire le fibre",
    "q.l40#9.e" to "Il cibo caldo risolve tre problemi in una volta: energia, idratazione e morale. È il motivo per cui in campo la cucina non si sostituisce con «solo cibo secco».",

    "q.l40#10.p" to "Se un compagno non riesce a mangiare da due giorni, cosa deve allarmare di più?",
    "q.l40#10.o0" to "L'esaurimento energetico che porta a ipotermia e perdita di lucidità, e la possibilità che sia un mal di montagna in peggioramento",
    "q.l40#10.o1" to "Che dimagrirà",
    "q.l40#10.o2" to "Che avrà stitichezza",
    "q.l40#10.o3" to "Che avrà carenza di vitamine",
    "q.l40#10.e" to "«Non riesco a mangiare» in quota è insieme causa e sintomo. Se non migliora va valutato come mal di montagna, non solo come mancanza di appetito.",

    "q.l40#11.p" to "Quali criteri guidano la scelta del cibo da cammino in quota?",
    "q.l40#11.o0" to "Alta densità energetica",
    "q.l40#11.o1" to "Che non indurisca con il freddo e sia facile da masticare",
    "q.l40#11.o2" to "Che non richieda molta acqua per essere inghiottito",
    "q.l40#11.o3" to "Che abbia volume grande",
    "q.l40#11.e" to "Il freddo indurisce cioccolato e barrette, e a -20 °C un alimento indurito è quasi immangiabile. Un volume grande occupa spazio e resta a metà.",

    "q.l40#12.p" to "Quali comportamenti sono corretti per bere e mangiare?",
    "q.l40#12.o0" to "Bere a sufficienza prima di partire",
    "q.l40#12.o1" to "Bere a piccoli sorsi e spesso durante il cammino",
    "q.l40#12.o2" to "Abbinare sali minerali e integrazione energetica",
    "q.l40#12.o3" to "Recuperare tutto in una volta al campo",
    "q.l40#12.e" to "Bere molto in una volta appesantisce l'intestino e non corregge il deficit della giornata. Solo l'integrazione distribuita funziona.",

    "q.l40#13.p" to "Quali pratiche aumentano davvero quanto si mangia in montagna?",
    "q.l40#13.o0" to "Portare gusti che già piacciono",
    "q.l40#13.o1" to "Dividere il cibo in porzioni piccole, in un posto a portata di mano",
    "q.l40#13.o2" to "Alternare consistenze diverse",
    "q.l40#13.o3" to "Portare un solo alimento, il più calorico",
    "q.l40#13.e" to "In quota l'«avversione al cibo» è comune: lo stesso gusto per giorni diventa impossibile. Varietà e gusti familiari sono strategie pratiche.",

    "q.l40#14.p" to "Metti in ordine il ritmo di rifornimento di una giornata.",
    "q.l40#14.o0" to "Al risveglio bere, colazione a base di carboidrati",
    "q.l40#14.o1" to "Dopo la partenza, piccole integrazioni ogni 45–60 minuti",
    "q.l40#14.o2" to "Un'integrazione in più prima di una salita lunga",
    "q.l40#14.o3" to "Al campo, cibo caldo e acqua",
    "q.l40#14.e" to "La chiave del ritmo è «non aspettare la fame». Aspettarla significa glicogeno già esaurito, e a quel punto servono 20–30 minuti perché l'integrazione faccia effetto.",

    "q.l40#15.p" to "Qual è l'ordine corretto per gestire il «non riesco a mangiare»?",
    "q.l40#15.o0" to "Reintegrare liquidi e verificare se c'è disidratazione",
    "q.l40#15.o1" to "Passare a cibi calorici facili da mandar giù, in piccole dosi frequenti",
    "q.l40#15.o2" to "Valutare se ci sono sintomi di mal di montagna",
    "q.l40#15.o3" to "Se non migliora, considerare la discesa",
    "q.l40#15.e" to "La disidratazione è il primo passo reversibile. Se esclusa e la persona continua a non mangiare, va valutata come patologia, non con più insistenze.",

    "q.l40#16.p" to "La densità energetica dei grassi è di circa ______ kcal/g.",
    "q.l40#16.a0" to "9",
    "q.l40#16.e" to "Carboidrati e proteine danno circa 4 kcal/g. È questo divario a spiegare la preferenza per frutta secca, bustine d'olio e cioccolato.",

    "q.l40#17.p" to "Durante il cammino si consiglia di integrare ogni ______ minuti (indica un valore).",
    "q.l40#17.a0" to "45–60",
    "q.l40#17.a1" to "45-60",
    "q.l40#17.a2" to "45",
    "q.l40#17.a3" to "60",
    "q.l40#17.a4" to "50",
    "q.l40#17.e" to "Piccole dosi frequenti funzionano meglio di dosi grandi e rare, e disturbano meno l'intestino.",

    "q.l40#18.p" to "Abbina ogni nutriente al suo ruolo.",
    "q.l40#18.l0" to "Carboidrati",
    "q.l40#18.l1" to "Grassi",
    "q.l40#18.l2" to "Proteine",
    "q.l40#18.l3" to "Acqua ed elettroliti",
    "q.l40#18.r0" to "Disponibili più in fretta, prima scelta in quota",
    "q.l40#18.r1" to "Densità energetica più alta, energia di lungo periodo",
    "q.l40#18.r2" to "Riparazione e mantenimento, non fonte principale di energia",
    "q.l40#18.r3" to "Mantengono la circolazione e la termoregolazione",
    "q.l40#18.e" to "Le proporzioni si possono modulare, ma il ruolo di base dei carboidrati non è sostituibile.",

    "q.l40#19.p" to "Abbina ogni situazione alla scelta più adatta.",
    "q.l40#19.l0" to "Salita lunga",
    "q.l40#19.l1" to "Attesa al freddo estremo",
    "q.l40#19.l2" to "Due ore prima della vetta",
    "q.l40#19.l3" to "Rientro al campo",
    "q.l40#19.r0" to "Gel e caramelle gommose, carboidrati da mangiare camminando",
    "q.l40#19.r1" to "Cibo molto grasso e calorico, che non indurisce facilmente",
    "q.l40#19.r2" to "Un pasto caldo a base di carboidrati",
    "q.l40#19.r3" to "Cibo caldo, acqua ed elettroliti",
    "q.l40#19.e" to "Lo stesso cibo rende diversamente secondo la situazione. Comporre per situazione funziona meglio che «comprare un mucchio di barrette».",

    "q.l40#20.p" to "Un compagno, per alleggerirsi, ha portato solo proteine in polvere: come lo giudichi?",
    "q.l40#20.o0" to "Non va bene: le proteine non sono la fonte principale di energia e in quota servono carboidrati a sufficienza",
    "q.l40#20.o1" to "Va bene, le proteine sono più pure",
    "q.l40#20.o2" to "Va bene, le proteine pesano meno",
    "q.l40#20.o3" to "Dipende dal gusto",
    "q.l40#20.e" to "Usare le proteine per l'energia è una «via inefficiente», che aumenta il carico renale e il rischio di disidratazione. In quota l'energia deve venire da carboidrati e grassi.",

    "q.l40#21.p" to "Il cibo si è indurito per il freddo: qual è la soluzione più pratica?",
    "q.l40#21.o0" to "Tenere la parte da mangiare a contatto con il corpo, scaldandola con il calore corporeo",
    "q.l40#21.o1" to "Metterla in acqua calda",
    "q.l40#21.o2" to "Morderla con forza",
    "q.l40#21.o3" to "Rinunciare a mangiarla",
    "q.l40#21.e" to "Tenerla addosso è il metodo più semplice ed efficace. Nello zaino, a -20 °C, una barretta è come un sasso.",

    "q.l40#22.p" to "Perché «mangiare» è di per sé una capacità d'alta quota?",
    "q.l40#22.o0" to "Riuscire a mantenere l'introito con poco ossigeno e poco appetito determina direttamente forza e lucidità",
    "q.l40#22.o1" to "Perché chi mangia è fortunato",
    "q.l40#22.o2" to "Perché il cibo costa",
    "q.l40#22.o3" to "Perché bisogna fare le foto",
    "q.l40#22.e" to "All'inizio il deficit energetico non si manifesta come fame, ma come movimenti più lenti, sensazione di freddo e giudizio peggiore. Riuscire a mangiare con continuità è il risultato di un allenamento.",

    "q.l40#23.p" to "Sull'uso della caffeina in alta quota, quale affermazione è corretta?",
    "q.l40#23.o0" to "Si può usare con moderazione, ma non sostituisce riposo e idratazione",
    "q.l40#23.o1" to "Più se ne prende, meglio è",
    "q.l40#23.o2" to "Va vietata del tutto",
    "q.l40#23.o3" to "Serve solo a tirare avanti per camminare",
    "q.l40#23.e" to "La caffeina può aiutare un po' sul mal di testa, ma usarla per mascherare la stanchezza sposta il problema in un momento più pericoloso.",
    // ---------- l41 Logistica di spedizione e permessi ----------
    "q.l41#0.p" to "Qual è l'essenza della logistica di spedizione?",
    "q.l41#0.o0" to "Un trasporto in più tratte, ognuna con limiti di carico, tempi e rischi propri",
    "q.l41#0.o1" to "Mandare tutto ai piedi della montagna in una volta",
    "q.l41#0.o2" to "Comprare l'attrezzatura più costosa",
    "q.l41#0.o3" to "Trovare la guida migliore",
    "q.l41#0.e" to "Solo considerando la logistica come una catena e non come un punto si fanno le scelte giuste in ogni tratta. Se un anello si rompe, tutto il resto ne risente.",

    "q.l41#1.p" to "Qual è la logica corretta nel preparare i colli?",
    "q.l41#1.o0" to "Confezionare secondo l'ordine di arrivo: prima arriva, prima si apre",
    "q.l41#1.o1" to "Confezionare per categoria",
    "q.l41#1.o2" to "Confezionare per prezzo",
    "q.l41#1.o3" to "Mescolare tutto",
    "q.l41#1.e" to "In un campo d'alta quota lo spazio è poco e il meteo è cattivo: cercare in più casse costa moltissimo. Confezionare per ordine di arrivo risparmia molto tempo esposti.",

    "q.l41#2.p" to "A cosa è di solito legato un permesso d'ascensione?",
    "q.l41#2.o0" to "Ufficiale di collegamento, itinerario e scadenza",
    "q.l41#2.o1" to "Solo al costo",
    "q.l41#2.o2" to "Solo al numero di persone",
    "q.l41#2.o3" to "Solo alla stagione",
    "q.l41#2.e" to "Le tre cose sono vincolate insieme dal permesso. Cambiare itinerario, sforare la scadenza o sostituire persone può richiedere una nuova comunicazione, e talvolta costi aggiuntivi.",

    "q.l41#3.p" to "Qual è la regola tipica del deposito cauzionale per i rifiuti?",
    "q.l41#3.o0" to "Viene restituito solo se tutti i rifiuti sono portati fuori",
    "q.l41#3.o1" to "Si paga e non si recupera",
    "q.l41#3.o2" to "Si paga una multa a peso",
    "q.l41#3.o3" to "È volontario",
    "q.l41#3.e" to "Lo scopo non è incassare, ma trasformare «portare giù i rifiuti» in un vincolo economico. Nel piano vanno previste anche le persone necessarie.",

    "q.l41#4.p" to "Perché non si può aumentare a piacere il carico di portatori e collaboratori?",
    "q.l41#4.o0" to "Ci sono limiti di legge o di settore: sovraccaricare trasferisce il rischio su di loro e rallenta tutta la squadra",
    "q.l41#4.o1" to "Perché si lamentano",
    "q.l41#4.o2" to "Perché si rompe l'attrezzatura",
    "q.l41#4.o3" to "Perché l'assicurazione non paga",
    "q.l41#4.e" to "Sovraccaricare significa costruire la propria efficienza sul danno altrui, e rallenta l'intera catena di trasporto. È un problema etico e insieme gestionale.",

    "q.l41#5.p" to "Cosa significa «tasso di consumo» in un piano di rifornimento?",
    "q.l41#5.o0" to "Persone × giorni × consumo giornaliero, per calcolare il totale e i punti di rifornimento",
    "q.l41#5.o1" to "Quanti chilometri si fanno al giorno",
    "q.l41#5.o2" to "Quanto dislivello si sale al giorno",
    "q.l41#5.o3" to "Quanto pesa lo zaino di ciascuno",
    "q.l41#5.e" to "Combustibile, cartucce e cibo vanno calcolati come tasso. Andando a sensazione si scopre che il gas non basta proprio nei giorni più freddi.",

    "q.l41#6.p" to "La scadenza del permesso si avvicina ma la finestra di meteo non è arrivata: cosa è più sensato fare?",
    "q.l41#6.o0" to "Valutare in anticipo il costo della proroga e i requisiti, e chiedere la proroga o spostare la data",
    "q.l41#6.o1" to "Sforare e salire lo stesso",
    "q.l41#6.o2" to "Cambiare itinerario senza comunicarlo",
    "q.l41#6.o3" to "Chiedere all'ufficiale di collegamento di chiudere un occhio",
    "q.l41#6.e" to "Salire oltre la scadenza fa decadere insieme permesso, assicurazione e soccorso. La proroga costa, ma costa meno di «non poter essere soccorsi».",

    "q.l41#7.p" to "Perché si tiene una scorta di rifornimenti?",
    "q.l41#7.o0" to "Ritardi meteo, usura dell'attrezzatura e condizioni della squadra aumentano i consumi",
    "q.l41#7.o1" to "Per rivenderla",
    "q.l41#7.o2" to "Per alleggerirsi",
    "q.l41#7.o3" to "Per essere conformi",
    "q.l41#7.e" to "In spedizione i consumi non sono mai lineari. La scorta è lo spazio riservato a «restare qualche giorno in più del previsto».",

    "q.l41#8.p" to "Qual è il nucleo della gestione dei materiali nei campi alti?",
    "q.l41#8.o0" to "Una tabella di ripartizione chiara e una rotazione, per evitare campi pieni e campi vuoti",
    "q.l41#8.o1" to "Più materiale è, meglio è",
    "q.l41#8.o2" to "Chi arriva primo prende",
    "q.l41#8.o3" to "Distribuire in parti uguali",
    "q.l41#8.e" to "La tabella fa sapere a ogni campo «cosa ha e quando arriva il resto». Senza tabella i materiali si accumulano nel campo sbagliato.",

    "q.l41#9.p" to "Cosa serve di solito per la certificazione di vetta?",
    "q.l41#9.o0" to "Foto o video in vetta, dichiarazione, permesso e documento d'identità",
    "q.l41#9.o1" to "Solo la foto",
    "q.l41#9.o2" to "Solo la testimonianza dei compagni",
    "q.l41#9.o3" to "Niente",
    "q.l41#9.e" to "Le richieste variano da montagna a montagna, ma «foto + dichiarazione + permesso» vale quasi sempre. Recuperare i documenti al rientro è molto più difficile che prepararli prima.",

    "q.l41#10.p" to "Se il bagaglio non arriva sullo stesso volo, cosa va salvaguardato per primo?",
    "q.l41#10.o0" to "Scarponi e attrezzatura tecnica personale: sono quasi impossibili da sostituire sul posto",
    "q.l41#10.o1" to "I vestiti di ricambio",
    "q.l41#10.o2" to "Gli snack",
    "q.l41#10.o3" to "I souvenir",
    "q.l41#10.e" to "Uno scarpone che non calza rende impossibile camminare, e l'attrezzatura tecnica riguarda la sicurezza. Molte squadre impongono di portare questi due gruppi a mano.",

    "q.l41#11.p" to "Quali voci vanno verificate tratta per tratta in un piano logistico?",
    "q.l41#11.o0" to "Mezzi di trasporto e alternativa",
    "q.l41#11.o1" to "Carico e costo di portatori e collaboratori",
    "q.l41#11.o2" to "Tempi e punti di controllo di ogni tratta",
    "q.l41#11.o3" to "Gli account social dei partecipanti",
    "q.l41#11.e" to "Le prime tre determinano «se si riesce a procedere come previsto». La quarta non ha rapporto con la logistica.",

    "q.l41#12.p" to "Quali costi rientrano di solito in permessi e conformità?",
    "q.l41#12.o0" to "Tassa del permesso e compenso dell'ufficiale di collegamento",
    "q.l41#12.o1" to "Deposito cauzionale per i rifiuti",
    "q.l41#12.o2" to "Costi di proroga",
    "q.l41#12.o3" to "Ammortamento dell'attrezzatura",
    "q.l41#12.e" to "I primi tre sono «costi di conformità» e vanno messi a budget separatamente. L'ammortamento dell'attrezzatura è un costo personale.",

    "q.l41#13.p" to "Quali situazioni vanno evitate nella gestione dei materiali nei campi?",
    "q.l41#13.o0" to "Un campo con materiale in eccesso e un altro senza cibo",
    "q.l41#13.o1" to "Combustibile e cibo stoccati insieme, con rischio di contaminazione",
    "q.l41#13.o2" to "Nessuna tabella di ripartizione, solo memoria",
    "q.l41#13.o3" to "Rotazione secondo il piano",
    "q.l41#13.e" to "Le prime tre sono tutte manifestazioni di gestione mancante. L'ultima è esattamente la pratica corretta.",

    "q.l41#14.p" to "Metti in ordine la pianificazione logistica di una spedizione.",
    "q.l41#14.o0" to "Confermare itinerario, permesso e scadenza",
    "q.l41#14.o1" to "Definire mezzi e tempi di ogni tratta",
    "q.l41#14.o2" to "Confezionare per ordine di arrivo e preparare la tabella di ripartizione",
    "q.l41#14.o3" to "Prevedere scorte e budget per la proroga",
    "q.l41#14.e" to "L'ordine riflette «prima la conformità, poi la logistica, infine i dettagli». Prenotare i trasporti prima di avere il permesso raddoppia il costo di un cambio data.",

    "q.l41#15.p" to "Metti in ordine l'arrivo dei materiali al campo alto.",
    "q.l41#15.o0" to "Trasporto su strada fino al campo base",
    "q.l41#15.o1" to "Trasporto con animali o a spalle fino al campo intermedio",
    "q.l41#15.o2" to "Distribuzione ai campi alti secondo la tabella",
    "q.l41#15.o3" to "Controllo dei materiali critici prima della vetta (gas, cibo, batterie)",
    "q.l41#15.e" to "L'ultimo passo è il più facilmente saltato. Senza controllo prima della vetta, il risultato tipico è «arrivati al campo alto e il gas non basta».",

    "q.l41#16.p" to "Il totale dei rifornimenti si calcola di solito come «persone × giorni × ______».",
    "q.l41#16.a0" to "consumo giornaliero",
    "q.l41#16.a1" to "consumo al giorno",
    "q.l41#16.a2" to "consumo",
    "q.l41#16.e" to "Scrivere il «tasso» nel piano è l'unico modo per calcolare i punti di rifornimento e le scorte.",

    "q.l41#17.p" to "Molte montagne chiedono che tutti i rifiuti siano portati fuori per restituire il ______.",
    "q.l41#17.a0" to "deposito cauzionale",
    "q.l41#17.a1" to "deposito",
    "q.l41#17.e" to "Considerando il deposito come una voce di costo, non ci si accorge all'ultimo giorno che mancano le persone per portare giù i rifiuti.",

    "q.l41#18.p" to "Abbina ogni anello della logistica al suo rischio principale.",
    "q.l41#18.l0" to "Trasporto su strada",
    "q.l41#18.l1" to "Trasporto con animali o portatori",
    "q.l41#18.l2" to "Ripartizione nei campi alti",
    "q.l41#18.l3" to "Scadenza del permesso",
    "q.l41#18.r0" to "Strada interrotta, frane, ritardi dei mezzi",
    "q.l41#18.r1" to "Carico oltre il limite, condizioni delle persone, meteo",
    "q.l41#18.r2" to "Materiali mal distribuiti, cibo o gas esauriti",
    "q.l41#18.r3" to "Sforamento che fa decadere permesso e soccorso",
    "q.l41#18.e" to "I rischi dei quattro anelli sono di natura completamente diversa, quindi anche i piani alternativi vanno scritti separatamente.",

    "q.l41#19.p" to "Abbina ogni documento al suo uso.",
    "q.l41#19.l0" to "Permesso e documenti dell'ufficiale di collegamento",
    "q.l41#19.l1" to "Ricevuta del deposito cauzionale",
    "q.l41#19.l2" to "Foto in vetta e dichiarazione",
    "q.l41#19.l3" to "Assicurazione e numero dei soccorsi",
    "q.l41#19.r0" to "Accesso e controlli di conformità",
    "q.l41#19.r1" to "Base per la restituzione del deposito alla partenza",
    "q.l41#19.r2" to "Richiesta del certificato di vetta",
    "q.l41#19.r3" to "Contatto e pratica di rimborso in caso di incidente",
    "q.l41#19.e" to "Quattro documenti per quattro momenti: entrata, uscita, certificazione, incidente. Se ne manca uno, ci si blocca in quel momento.",

    "q.l41#20.p" to "La squadra vuole attrezzare un tratto di corda fissa fuori dal permesso: cosa va fatto prima?",
    "q.l41#20.o0" to "Verificare se viola il permesso e le norme dell'area protetta, e comunicarlo se necessario",
    "q.l41#20.o1" to "Attrezzare e poi vedere",
    "q.l41#20.o2" to "Attrezzare di notte",
    "q.l41#20.o3" to "Farlo fare a qualcun altro",
    "q.l41#20.e" to "Nelle aree protette la corda fissa è spesso considerata «installazione permanente» e senza autorizzazione può essere irregolare. Prima si verifica, poi si agisce.",

    "q.l41#21.p" to "Il team di collaboratori segnala che il lavoro supera il contratto: qual è la gestione più sensata?",
    "q.l41#21.o0" to "Rinegoziare in base al contratto e al lavoro effettivo, mettendo per iscritto la variazione",
    "q.l41#21.o1" to "Rifiutare il confronto",
    "q.l41#21.o2" to "Imporre di finire comunque",
    "q.l41#21.o3" to "Pagare in nero senza registrare nulla",
    "q.l41#21.e" to "In spedizione le variazioni di manodopera sono normali. Rinegoziare lasciando traccia protegge entrambe le parti.",

    "q.l41#22.p" to "Perché una spedizione deve avere un budget separato per le «proroghe»?",
    "q.l41#22.o0" to "Finestra meteo e ritardi logistici sono la norma, e la proroga comporta costi extra di alloggio, personale e permesso",
    "q.l41#22.o1" to "Per fare acquisti",
    "q.l41#22.o2" to "Per le mance",
    "q.l41#22.o3" to "Per il cambio valuta",
    "q.l41#22.e" to "Il budget per la proroga non è uno spreco: serve a evitare che «per ragioni di soldi» si prenda una decisione pericolosa.",

    "q.l41#23.p" to "Alla partenza dalla montagna, come vanno gestiti i rifiuti?",
    "q.l41#23.o0" to "Portarli fuori tutti, separati secondo il permesso, conservando le ricevute",
    "q.l41#23.o1" to "Seppellirli nella neve",
    "q.l41#23.o2" to "Bruciarli",
    "q.l41#23.o3" to "Lasciarli alla squadra successiva",
    "q.l41#23.e" to "Seppellire e bruciare violano le norme e inquinano le fonti d'acqua. Portare fuori con le ricevute è l'unico modo per riavere il deposito.",

    "q.l41#24.p" to "L'assicurazione sul trasporto dei materiali di spedizione cosa deve coprire soprattutto?",
    "q.l41#24.o0" to "Il costo dell'interruzione di viaggio dovuta a perdita o ritardo dell'attrezzatura",
    "q.l41#24.o1" to "Solo la spedizione",
    "q.l41#24.o2" to "Solo le persone",
    "q.l41#24.o3" to "Niente",
    "q.l41#24.e" to "Un ritardo dell'attrezzatura può chiudere la spedizione. L'assicurazione deve coprire «ritardo e interruzione», non solo lo smarrimento.",

    "q.l41#25.p" to "Qual è il modo più efficace di concordare il carico di lavoro con il team di collaboratori?",
    "q.l41#25.o0" to "Confermare per iscritto carichi, numero di viaggi e costi prima di partire, registrando le variazioni",
    "q.l41#25.o1" to "Accordo verbale",
    "q.l41#25.o2" to "Decidere una volta arrivati",
    "q.l41#25.o3" to "Lasciare che decidano loro",
    "q.l41#25.e" to "Le variazioni sono normali in spedizione. Conferma scritta e registro delle modifiche evitano discussioni sui costi all'ultimo giorno.",

    "q.l41#26.p" to "Cosa deve contenere la «lista di inventario» dei materiali al campo base?",
    "q.l41#26.o0" to "Voce, quantità, campo in cui si trova, data di apertura e responsabile",
    "q.l41#26.o1" to "Solo il totale",
    "q.l41#26.o2" to "Solo le categorie",
    "q.l41#26.o3" to "Niente",
    "q.l41#26.e" to "«Dove, quanto resta, chi lo sta usando» sono i tre elementi dell'inventario. Senza, i materiali finiscono sempre per accumularsi nel posto sbagliato.",

    "q.l41#27.p" to "Se il permesso impone di portare fuori tutti i rifiuti, cosa va previsto in più nel piano?",
    "q.l41#27.o0" to "Persone e capacità di trasporto per il rientro, più pesatura e ricevute",
    "q.l41#27.o1" to "Solo i sacchi per i rifiuti",
    "q.l41#27.o2" to "Solo un budget per le multe",
    "q.l41#27.o3" to "Niente di particolare",
    "q.l41#27.e" to "Al rientro la squadra è più stanca e il tempo più stretto, mentre i rifiuti sono il carico più pesante. Va scritto nel piano di trasporto, altrimenti salta all'ultimo giorno.",
    // ---------- l17 Fondamenti di arrampicata su ghiaccio ----------
    "q.l17#14.p" to "Nel valutare il ghiaccio, cosa significa «ghiaccio marcio» (dinner-plating)?",
    "q.l17#14.o0" to "Il ghiaccio si stacca a lastre e un colpo di piccozza ne fa cadere via grandi pezzi",
    "q.l17#14.o1" to "Che il ghiaccio è molto duro",
    "q.l17#14.o2" to "Che il ghiaccio contiene bolle",
    "q.l17#14.o3" to "Che sulla superficie c'è brina",
    "q.l17#14.e" to "Il ghiaccio marcio indica una struttura scadente: né la piccozza né la vite tengono in modo affidabile. Con vaste zone di ghiaccio marcio si cambia via o si scende.",

    "q.l17#15.p" to "Ghiaccio d'acqua corrente o ghiaccio nero: quale è più adatto alla salita?",
    "q.l17#15.o0" to "Il ghiaccio nero (compatto, senza bolle): è più resistente e la vite tiene bene",
    "q.l17#15.o1" to "Il ghiaccio d'acqua corrente è più stabile",
    "q.l17#15.o2" to "Sono equivalenti",
    "q.l17#15.o3" to "Nessuno dei due",
    "q.l17#15.e" to "Il ghiaccio compatto e trasparente è resistente e la vite morde bene; il ghiaccio d'acqua corrente e quello alveolare hanno vuoti interni e l'affidabilità della protezione cala molto.",

    "q.l17#16.p" to "Nell'inserire una vite da ghiaccio, il corpo va di solito?",
    "q.l17#16.o0" to "Leggermente inclinato verso l'alto (circa 10°), con la maniglia verso il basso per agganciare il moschettone",
    "q.l17#16.o1" to "Perfettamente orizzontale",
    "q.l17#16.o2" to "Inclinato verso il basso",
    "q.l17#16.o3" to "Con un angolo qualsiasi",
    "q.l17#16.e" to "Una leggera inclinazione verso l'alto segue la direzione della forza e riduce il rischio di estrazione. La maniglia verso il basso facilita il moschettone e riduce la possibilità che la corda apra il ghiera.",

    "q.l17#17.p" to "Da cosa dipende la lunghezza migliore della vite?",
    "q.l17#17.o0" to "Dalla qualità del ghiaccio: vite corta sul duro, lunga sul morbido o marcio",
    "q.l17#17.o1" to "Più corta è, meglio è",
    "q.l17#17.o2" to "Più lunga è, meglio è",
    "q.l17#17.o3" to "Non dipende dal ghiaccio",
    "q.l17#17.e" to "Una vite corta non morde nel ghiaccio morbido, una lunga entra con difficoltà e richiede tempo nel duro. Si sceglie «in base al ghiaccio», non «per abitudine».",

    "q.l17#18.p" to "Una sosta su ghiaccio richiede di solito?",
    "q.l17#18.o0" to "Almeno due viti affidabili, collegate e bilanciate con fettuccia o corda",
    "q.l17#18.o1" to "Una sola vite",
    "q.l17#18.o2" to "Tre viti infilate su un'unica fettuccia",
    "q.l17#18.o3" to "Solo nut",
    "q.l17#18.e" to "«Due punti indipendenti e bilanciati» è il minimo. Se una singola vite cede, il sistema cede per intero.",

    "q.l17#19.p" to "Qual è la tecnica per «trovare riposo» su una parete di ghiaccio?",
    "q.l17#19.o0" to "Portare il peso sulla gamba distesa e appendere la piccozza, alternando il rilassamento delle braccia",
    "q.l17#19.o1" to "Restare appesi con entrambe le braccia",
    "q.l17#19.o2" to "Sedersi",
    "q.l17#19.o3" to "Staccare entrambi i piedi",
    "q.l17#19.e" to "Il collo di bottiglia dell'arrampicata su ghiaccio è la «pompa» dell'avambraccio. Chi sa riposare sale decine di metri in più; chi non sa riposare si esaurisce al primo passaggio.",

    "q.l17#20.p" to "Perché occhiali protettivi o maschera sono importanti su ghiaccio?",
    "q.l17#20.o0" to "Ghiaccio e schegge continuano a cadere sul viso",
    "q.l17#20.o1" to "Per estetica",
    "q.l17#20.o2" to "Contro i raggi ultravioletti",
    "q.l17#20.o3" to "Contro l'appannamento",
    "q.l17#20.e" to "Ogni colpo di piccozza fa cadere schegge, e sia chi segue sia chi assicura stanno nella «zona di caduta». La protezione degli occhi è un'attrezzatura necessaria a basso costo.",

    "q.l17#21.p" to "Quando cade ghiaccio, chi assicura deve?",
    "q.l17#21.o0" to "Stare addossato alla parete, il più possibile sotto la roccia, e aver già individuato la traiettoria di caduta",
    "q.l17#21.o1" to "Stare più lontano",
    "q.l17#21.o2" to "Guardare in alto",
    "q.l17#21.o3" to "Proteggersi con le mani",
    "q.l17#21.e" to "Sotto una parete di ghiaccio c'è un «imbuto». Stare addossati è spesso più sicuro che allontanarsi, perché i pezzi cadono con una traiettoria parabolica.",

    "q.l17#22.p" to "Per la discesa su ghiaccio si usa spesso l'«Abalakov» (v-thread): qual è il suo vantaggio?",
    "q.l17#22.o0" to "Non lascia attrezzatura: si recupera la corda tirandola",
    "q.l17#22.o1" to "È il più veloce",
    "q.l17#22.o2" to "È il più sicuro",
    "q.l17#22.o3" to "Non richiede viti",
    "q.l17#22.e" to "Due fori che si incontrano, corda infilata e annodata: si scende e si recupera la corda. Riduce la perdita di materiale, ma richiede angolo e lunghezza corretti.",

    "q.l17#23.p" to "Qual è il fattore che più fa cambiare le condizioni del ghiaccio nell'arco della giornata?",
    "q.l17#23.o0" to "Sole e temperatura: la parete esposta a sud si ammorbidisce nel pomeriggio, quella a nord resta dura",
    "q.l17#23.o1" to "La velocità del vento",
    "q.l17#23.o2" to "La pressione atmosferica",
    "q.l17#23.o3" to "L'umidità",
    "q.l17#23.e" to "La stessa parete può avere due difficoltà diverse tra mattina e pomeriggio. La pianificazione deve considerare «quando quella parete è più stabile».",

    "q.l17#24.p" to "Nella tecnica di piedi su ghiaccio, l'inserimento delle punte frontali deve essere?",
    "q.l17#24.o0" to "Ginocchia flesse, punte inserite in verticale, appoggi distribuiti",
    "q.l17#24.o1" to "Punta appoggiata di piatto sul ghiaccio",
    "q.l17#24.o2" to "Appoggio sul tallone",
    "q.l17#24.o3" to "Colpi rapidi e ripetuti",
    "q.l17#24.e" to "Solo un inserimento verticale morde. Distribuire gli appoggi evita di frantumare lo stesso punto e riduce il rischio di «ghiaccio sbriciolato».",

    "q.l17#25.p" to "Con una forte «pompa» alle braccia, cosa NON va assolutamente fatto?",
    "q.l17#25.o0" to "Insistere fino alla sosta successiva",
    "q.l17#25.o1" to "Cercare una posizione di riposo",
    "q.l17#25.o2" to "Scrollare le braccia",
    "q.l17#25.o3" to "Passare a una posizione più economica",
    "q.l17#25.e" to "La pompa è il segnale che l'avambraccio non riceve abbastanza sangue. Insistere porta a «non riuscire più a stringere la piccozza», che è la causa più comune di caduta su ghiaccio.",

    "q.l17#26.p" to "Perché dopo aver piantato una vite non conviene estrarla e reinserirla più volte?",
    "q.l17#26.o0" to "Il foro si allarga e la struttura del ghiaccio si danneggia, riducendo la tenuta al secondo inserimento",
    "q.l17#26.o1" to "Perché è scomodo",
    "q.l17#26.o2" to "Perché si ghiaccia",
    "q.l17#26.o3" to "Perché si piega",
    "q.l17#26.e" to "Reinserendo nello stesso foro la vite può risultare mobile. Pensare al punto prima di piantarla fa risparmiare tempo ed è più sicuro che provare e riprovare.",

    "q.l17#27.p" to "Qual è la differenza principale di protezione tra ghiaccio e roccia?",
    "q.l17#27.o0" to "La tenuta dei punti dipende dalla qualità del mezzo (il ghiaccio) e cambia con il tempo",
    "q.l17#27.o1" to "Su ghiaccio non serve protezione",
    "q.l17#27.o2" to "Su ghiaccio si usa solo la corda dall'alto",
    "q.l17#27.o3" to "Non c'è differenza",
    "q.l17#27.e" to "La tenuta di nut e spit è relativamente stabile, quella di una vite da ghiaccio cambia con temperatura e tempo. È il motivo per cui la valutazione su ghiaccio è più difficile.",
    // ---------- m06 Introduzione all'arrampicata tecnica ----------
    "q.m06#10.p" to "Fra i tre grandi sistemi dell'arrampicata tecnica, cosa significa «protezione»?",
    "q.m06#10.o0" to "Trattenere la persona con ancoraggi e corda in caso di caduta",
    "q.m06#10.o1" to "Camminare",
    "q.m06#10.o2" to "I movimenti di arrampicata",
    "q.m06#10.o3" to "L'acquisto dell'attrezzatura",
    "q.m06#10.e" to "Movimento, autoprotezione e assicurazione (belay) formano un circuito chiuso: saper camminare, saper proteggere sé stessi, saper proteggere gli altri. Se ne manca uno, non è arrampicata tecnica.",

    "q.m06#11.p" to "Perché nei corsi tecnici l'ordine è di solito «prima impari a frenare, poi ad arrampicare»?",
    "q.m06#11.o0" to "Perché la scivolata è il pericolo più frequente e la frenata è la capacità di base",
    "q.m06#11.o1" to "Perché arrampicare è più difficile",
    "q.m06#11.o2" to "Perché l'attrezzatura arriva in quell'ordine",
    "q.m06#11.o3" to "Perché lo dice il manuale",
    "q.m06#11.e" to "Saper salire senza saper fermarsi ingrandisce il rischio. Frenata, cordata e protezione sono capacità che non servono quando tutto va bene: devono diventare automatiche prima.",

    "q.m06#12.p" to "Qual è il valore di ripetere le simulazioni su terreno sicuro?",
    "q.m06#12.o0" to "I gesti diventano riflessi che non richiedono riflessione, e in situazione reale resta margine per valutare",
    "q.m06#12.o1" to "Per passare il tempo",
    "q.m06#12.o2" to "Per fare fotografie",
    "q.m06#12.o3" to "Per imparare i prezzi dell'attrezzatura",
    "q.m06#12.e" to "Nelle condizioni reali l'attenzione è occupata da meteo, stanchezza e paura. Solo i gesti automatici riescono a uscire nel momento decisivo.",

    // ---------- m07 Sosta, fondamenti ----------
    "q.m07#12.p" to "In che direzione deve essere la ghiera del moschettone?",
    "q.m07#12.o0" to "Lontano dalla parete e lontano da sfregamento e direzione della forza, perché corda o spigolo non possano aprirla",
    "q.m07#12.o1" to "Verso l'alto",
    "q.m07#12.o2" to "Verso il basso",
    "q.m07#12.o3" to "Non importa",
    "q.m07#12.e" to "La ghiera aperta da una forza esterna è un modo di cedimento reale. Scegliendo la direzione sbagliata, l'affidabilità è affidata al caso.",

    "q.m07#13.p" to "Perché una fettuccia che collega due ancoraggi non va fatta passare su uno spigolo vivo?",
    "q.m07#13.o0" to "Gli spigoli vivi tagliano la fettuccia e la resistenza crolla sotto carico",
    "q.m07#13.o1" to "Perché è brutto",
    "q.m07#13.o2" to "Perché scivola",
    "q.m07#13.o3" to "Perché diventa troppo corta",
    "q.m07#13.e" to "Un piccolo taglio nella fettuccia può dimezzarne la resistenza. Se bisogna passare, si mette una protezione o si allunga con una catena.",

    "q.m07#14.p" to "Con che angolo si inserisce di solito una vite da ghiaccio?",
    "q.m07#14.o0" to "Leggermente verso l'alto (circa 10–15 gradi), contro la direzione della forza",
    "q.m07#14.o1" to "Perfettamente orizzontale",
    "q.m07#14.o2" to "Inclinata verso il basso",
    "q.m07#14.o3" to "Con un angolo qualsiasi",
    "q.m07#14.e" to "Una leggera inclinazione verso l'alto segue la direzione della forza, così la vite viene spinta nel ghiaccio invece di essere estratta. Con ghiaccio scadente serve più lunga e più inclinata.",

    "q.m07#15.p" to "Cosa va fatto soprattutto quando la sosta ha un solo ancoraggio?",
    "q.m07#15.o0" to "Aggiungere un backup indipendente, oppure spostarsi su terreno più sicuro",
    "q.m07#15.o1" to "Usarla così com'è",
    "q.m07#15.o2" to "Appendere più moschettoni",
    "q.m07#15.o3" to "Accorciare la corda",
    "q.m07#15.e" to "Il numero di moschettoni non è ridondanza. La ridondanza presuppone che le cause di cedimento siano diverse.",

    // ---------- m08 Obiettivi: Gangshika e Haba ----------
    "q.m08#12.p" to "Su montagne di 5.000 metri come Gangshika e Haba, cosa va pianificato soprattutto in anticipo?",
    "q.m08#12.o0" to "Ritmo di aclimatazione e finestre di meteo, non la difficoltà tecnica",
    "q.m08#12.o1" to "L'acquisto dell'attrezzatura",
    "q.m08#12.o2" to "I punti per le fotografie",
    "q.m08#12.o3" to "La divisione dei compiti",
    "q.m08#12.e" to "La difficoltà dei 5.000 metri sta di solito nella quota e nel meteo, non nella tecnica. Tempo dedicato all'acclimatazione vale più di un movimento in più allenato.",

    "q.m08#13.p" to "Riguardo a permessi e obbligo di guida, qual è il comportamento corretto?",
    "q.m08#13.o0" to "Verificare in anticipo le norme locali e rispettare gli obblighi di guida o registrazione",
    "q.m08#13.o1" to "Chiedere una volta arrivati",
    "q.m08#13.o2" to "Aggirare il posto di controllo",
    "q.m08#13.o3" to "Sistemare tramite un conoscente",
    "q.m08#13.e" to "Molte montagne di 5.000 metri richiedono registrazione o guida. Salire senza permesso fa decadere insieme soccorso e assicurazione.",

    "q.m08#14.p" to "Qual è la logica di un percorso di progressione tipo «tre cime → cima principale»?",
    "q.m08#14.o0" to "Verificare prima aclimatazione e resistenza su un itinerario più facile, poi aggiungere la difficoltà tecnica",
    "q.m08#14.o1" to "Perché costa meno",
    "q.m08#14.o2" to "Perché è vicino",
    "q.m08#14.o3" to "Perché c'è molta gente",
    "q.m08#14.e" to "La progressione consiste nell'aumentare una variabile per volta. Se si aumentano insieme quota e tecnica, quando qualcosa va storto è difficile capirne la causa.",

    "q.m08#15.p" to "Quali informazioni sulla via di ritirata devono essere chiare prima di partire?",
    "q.m08#15.o0" to "Via di discesa, posizione del campo di riserva, presidio medico più vicino e contatti",
    "q.m08#15.o1" to "Solo la via di discesa",
    "q.m08#15.o2" to "Solo il presidio medico",
    "q.m08#15.o3" to "Nessuna",
    "q.m08#15.e" to "Ritirarsi non è solo «tornare indietro». Quando il meteo peggiora, il campo di riserva più vicino può essere l'unica opzione praticabile.",

    // ---------- m10 Meteorologia montana e finestre di tempo ----------
    "q.m10#12.p" to "Quando l'umidità relativa è vicina alla saturazione, qual è il significato meteorologico più diretto?",
    "q.m10#12.o0" to "Base delle nuvole più bassa, maggiore probabilità di nebbia e precipitazioni",
    "q.m10#12.o1" to "La temperatura sale",
    "q.m10#12.o2" to "Il vento cala",
    "q.m10#12.o3" to "La pressione sale",
    "q.m10#12.e" to "La saturazione significa che il vapore inizia a condensare. In montagna il «calo rapido della base delle nuvole» arriva spesso prima dell'inizio della pioggia.",

    "q.m10#13.p" to "Dopo il passaggio di un fronte freddo si osserva di solito?",
    "q.m10#13.o0" to "Temperatura in calo, rotazione del vento, visibilità in miglioramento",
    "q.m10#13.o1" to "Temperatura in aumento",
    "q.m10#13.o2" to "Pioggia continua",
    "q.m10#13.o3" to "Vento in calo",
    "q.m10#13.e" to "Dopo il fronte arriva spesso «bel tempo ma molto freddo e ventoso». È il motivo per cui molte squadre sottovalutano il raffreddamento da vento proprio quando «il tempo migliora».",

    "q.m10#14.p" to "Che significato hanno le nuvole orografiche (appoggiate al fianco della montagna) per la salita?",
    "q.m10#14.o0" to "Indicano vento forte e umidità elevata: la cresta può essere già impraticabile",
    "q.m10#14.o1" to "Sono solo belle da vedere",
    "q.m10#14.o2" to "Indicano tempo stabile",
    "q.m10#14.o3" to "Non hanno rapporto con il vento",
    "q.m10#14.e" to "Le nuvole orografiche sono «vento e umidità resi visibili». Se la nuvola viene spinta via rapidamente, il vento in cresta è quasi certamente oltre il limite.",

    "q.m10#15.p" to "Perché più lunga è la scadenza di una previsione, meno è affidabile?",
    "q.m10#15.o0" to "L'atmosfera è un sistema caotico e l'errore cresce in modo esponenziale nel tempo",
    "q.m10#15.o1" to "Perché i modelli sono scadenti",
    "q.m10#15.o2" to "Perché mancano i dati",
    "q.m10#15.o3" to "Perché la quota è alta",
    "q.m10#15.e" to "Fino a 3 giorni la tendenza è abbastanza credibile, oltre 7 giorni è solo un riferimento. Il programma deve prevedere tempo per «aspettare la finestra».",

    "q.m10#16.p" to "La differenza tra i dati di una stazione di valle e la quota che si vuole salire dipende soprattutto da?",
    "q.m10#16.o0" to "Differenza di quota, che cambia temperatura, velocità del vento e tipo di precipitazione",
    "q.m10#16.o1" to "Errore degli strumenti",
    "q.m10#16.o2" to "Fuso orario",
    "q.m10#16.o3" to "Latitudine",
    "q.m10#16.e" to "La «pioggia leggera» di una stazione di valle a 5.000 metri può essere «neve abbondante e vento forte». Leggendo una previsione bisogna sempre convertire la quota.",

    "q.m10#17.p" to "Se si sente il tuono entro 30 secondi dal lampo, significa che?",
    "q.m10#17.o0" to "Il temporale è ormai vicino: bisogna lasciare subito il terreno esposto",
    "q.m10#17.o1" to "Il temporale è lontano",
    "q.m10#17.o2" to "È sicuro",
    "q.m10#17.o3" to "È solo una coincidenza",
    "q.m10#17.e" to "La differenza tra velocità della luce e del suono permette di stimare la distanza. Più breve è l'intervallo, più vicino è il temporale: «30 secondi» è la soglia d'azione comunemente usata.",

    "q.m10#18.p" to "Perché la salita in vetta si programma spesso prima dell'alba?",
    "q.m10#18.o0" to "La neve gelata è più stabile e nel pomeriggio nuvole e vento sono di solito più forti",
    "q.m10#18.o1" to "Per fare fotografie",
    "q.m10#18.o2" to "Perché c'è meno gente",
    "q.m10#18.o3" to "Per abitudine delle guide",
    "q.m10#18.e" to "La neve dura e la finestra di tempo stabile sono le ragioni principali. Il prezzo è freddo e poco sonno, e va messo in conto prima.",

    "q.m10#19.p" to "Quando la finestra di meteo si restringe, cosa si rinuncia per primo?",
    "q.m10#19.o0" to "L'obiettivo della vetta, non il margine di sicurezza",
    "q.m10#19.o1" to "Lo strato caldo",
    "q.m10#19.o2" to "L'attrezzatura di riserva",
    "q.m10#19.o3" to "I dispositivi di comunicazione",
    "q.m10#19.e" to "Quando la finestra non basta, ciò che si comprime è spesso «il margine»: ed è proprio così che inizia l'incidente. La scelta corretta è rinunciare prima all'obiettivo.",

    // ---------- m11 Obiettivi: quattro 6.000 ----------
    "q.m11#12.p" to "Perché il versante sud dello Yuzhu è adatto come primo 6.000?",
    "q.m11#12.o0" to "Pendii di neve relativamente dolci, accesso raggiungibile, itinerario collaudato",
    "q.m11#12.o1" to "Perché è il più alto",
    "q.m11#12.o2" to "Perché è tecnicamente il più difficile",
    "q.m11#12.o3" to "Perché c'è poca gente",
    "q.m11#12.e" to "L'obiettivo del «primo 6.000» è verificare aclimatazione e resistenza, non affrontare la tecnica. Un itinerario collaudato riduce le incognite.",

    "q.m11#13.p" to "A quale catena appartiene il Qizi (Siguniang) Peak?",
    "q.m11#13.o0" to "Nyainqêntanglha",
    "q.m11#13.o1" to "Kunlun",
    "q.m11#13.o2" to "Himalaya",
    "q.m11#13.o3" to "Karakorum",
    "q.m11#13.e" to "Il Qizi si trova a Damxung, in Tibet, nella catena del Nyainqêntanglha. La catena determina clima e stagione: è un elemento chiave nella scelta della montagna.",

    "q.m11#14.p" to "Qual è l'uso più tipico del Lobuche East?",
    "q.m11#14.o0" to "Come passaggio e allenamento tecnico tra i 6.000 e gli 8.000 metri",
    "q.m11#14.o1" to "Come itinerario turistico",
    "q.m11#14.o2" to "Come pista da sci",
    "q.m11#14.o3" to "Come belvedere",
    "q.m11#14.e" to "È accanto al trekking dell'Everest, con pendii di neve ripidi e accesso comodo: è un 6.000 di transizione molto usato.",

    "q.m11#15.p" to "Qual è la caratteristica tecnica dell'Island Peak (Imja Tse)?",
    "q.m11#15.o0" to "Richiede cordata e progresso su ghiacciaio con crepacci: è un classico 6.000 tecnico",
    "q.m11#15.o1" to "È un semplice trekking",
    "q.m11#15.o2" to "Basta camminare sulla neve",
    "q.m11#15.o3" to "Non ha neve tutto l'anno",
    "q.m11#15.e" to "La «tecnica» dell'Island Peak sta nel ghiacciaio e nei crepacci, non nella parete rocciosa. Cordata e recupero da crepaccio sono capacità indispensabili.",

    "q.m11#16.p" to "Nella scelta di un 6.000, cosa conta più della quota?",
    "q.m11#16.o0" to "La forma dell'itinerario (neve, ghiacciaio, parete) e la difficoltà di ritirata",
    "q.m11#16.o1" to "Se il nome suona bene",
    "q.m11#16.o2" to "La distanza",
    "q.m11#16.o3" to "Il costo",
    "q.m11#16.e" to "A parità di 6.100 metri, un pendio di neve e un itinerario su ghiacciaio richiedono capacità di un ordine diverso. Prima la forma, poi la quota.",

    "q.m11#17.p" to "I requisiti di permesso e guida per un 6.000 sono di solito, rispetto a un 5.000?",
    "q.m11#17.o0" to "Più severi: spesso registrazione obbligatoria o guida",
    "q.m11#17.o1" to "Più permissivi",
    "q.m11#17.o2" to "Identici",
    "q.m11#17.o3" to "Non esistono requisiti",
    "q.m11#17.e" to "Più alta è la quota e più remoto l'itinerario, più stretti sono i controlli. Verificare prima è molto più semplice che chiedere ai piedi della montagna.",

    "q.m11#18.p" to "Perché su un 6.000 conviene «presumere che ci siano crepacci»?",
    "q.m11#18.o0" to "Con i ponti di neve non si può giudicare a vista: si procede in cordata come se ci fossero",
    "q.m11#18.o1" to "Perché i crepacci ci sono sempre",
    "q.m11#18.o2" to "Perché lo chiede la guida",
    "q.m11#18.o3" to "Perché lo impone l'assicurazione",
    "q.m11#18.e" to "«Non si vede» non significa «non c'è». Il costo della cordata è basso, il prezzo di una caduta in crepaccio è altissimo.",

    "q.m11#19.p" to "L'acclimatazione su un 6.000 è di solito, rispetto a un 5.000?",
    "q.m11#19.o0" to "Più lunga: si dorme più in alto e il recupero è più lento",
    "q.m11#19.o1" to "Più breve",
    "q.m11#19.o2" to "Uguale",
    "q.m11#19.o3" to "Non serve",
    "q.m11#19.e" to "Ogni gradino di quota richiede più tempo. Riportare il ritmo di un 5.000 su un 6.000 è una sottovalutazione comune.",

    // ---------- m12 Sistemi di corda avanzati e vantaggio meccanico ----------
    "q.m12#16.p" to "Qual è il vantaggio meccanico teorico di un sistema 3:1?",
    "q.m12#16.o0" to "Tirando 1 metro di corda il carico sale di circa 1/3 di metro",
    "q.m12#16.o1" to "Il carico si dimezza",
    "q.m12#16.o2" to "La velocità non cambia",
    "q.m12#16.o3" to "Non servono nodi autobloccanti",
    "q.m12#16.e" to "Il vantaggio meccanico corrisponde al numero di segmenti di corda che sostengono il carico. 3:1 significa che la forza necessaria è circa un terzo del carico (senza contare l'attrito).",

    "q.m12#17.p" to "Nelle manovre reali, l'efficienza di un sistema 5:1 è di solito?",
    "q.m12#17.o0" to "Inferiore al valore teorico, per le perdite di attrito di carrucole e corda",
    "q.m12#17.o1" to "Superiore al valore teorico",
    "q.m12#17.o2" to "Esattamente uguale al valore teorico",
    "q.m12#17.o3" to "Indipendente dall'attrito",
    "q.m12#17.e" to "Ogni carrucola introduce perdite, e l'efficienza reale è spesso il 60–70 % del teorico. Nel progetto va lasciato margine.",

    "q.m12#18.p" to "Usando un moschettone al posto di una carrucola come «punto di rinvio», qual è il costo principale?",
    "q.m12#18.o0" to "L'attrito aumenta in modo netto e l'efficienza cala",
    "q.m12#18.o1" to "La resistenza è insufficiente",
    "q.m12#18.o2" to "Si consuma l'imbrago",
    "q.m12#18.o3" to "Non si riesce a bloccare",
    "q.m12#18.e" to "Il moschettone devia la corda ma non riduce l'attrito, e una parte della forza viene assorbita. Se c'è una carrucola, va usata.",

    "q.m12#19.p" to "A cosa serve il «nodo autobloccante unidirezionale» in un sistema di recupero?",
    "q.m12#19.o0" to "Blocca dopo la trazione, impedendo al carico di tornare indietro",
    "q.m12#19.o1" to "Aumenta la resistenza",
    "q.m12#19.o2" to "Riduce l'attrito",
    "q.m12#19.o3" to "Unisce due corde",
    "q.m12#19.e" to "Senza bloccante, ogni volta che si lascia la presa il carico scivola indietro. Il bloccante è la chiave che trasforma «trazioni intermittenti» in «spostamento».",

    "q.m12#20.p" to "Perché in un sistema di recupero si mette un bloccante di backup?",
    "q.m12#20.o0" to "Il bloccante principale può slittare o cedere: il backup è l'ultima protezione",
    "q.m12#20.o1" to "Per estetica",
    "q.m12#20.o2" to "Per aumentare la trazione",
    "q.m12#20.o3" to "Per risparmiare corda",
    "q.m12#20.e" to "L'affidabilità di un bloccante dipende dall'abbinamento con il diametro della corda e dal suo stato. Nei sistemi critici il doppio bloccante è la norma.",

    "q.m12#21.p" to "Nel trascinare un ferito, il sistema va disposto in modo da?",
    "q.m12#21.o0" to "Seguire il terreno da vicino, evitando che il ferito urti la parete o una cornice",
    "q.m12#21.o1" to "Tirare il più in alto possibile",
    "q.m12#21.o2" to "Fare il più in fretta possibile",
    "q.m12#21.o3" to "Sollevare in verticale",
    "q.m12#21.e" to "I danni nel trascinamento vengono spesso dagli urti, non dalla trazione. La scelta della linea e la posizione degli ancoraggi contano allo stesso modo.",

    "q.m12#22.p" to "Qual è il prezzo di un sistema 6:1 rispetto a un 3:1?",
    "q.m12#22.o0" to "Serve più attrezzatura, si allestisce più lentamente e consuma più corda",
    "q.m12#22.o1" to "È più faticoso ma più veloce",
    "q.m12#22.o2" to "Non ha svantaggi",
    "q.m12#22.o3" to "Non si può recuperare",
    "q.m12#22.e" to "Più alto è il vantaggio meccanico, più complesso è l'allestimento e più corda serve. Nel soccorso «essere veloci» conta spesso più di «fare meno fatica».",

    "q.m12#23.p" to "Quando il sistema va «convertito» a metà manovra, qual è il requisito fondamentale?",
    "q.m12#23.o0" to "In ogni istante almeno un dispositivo regge il carico, senza momenti di scollegamento",
    "q.m12#23.o1" to "Fare in fretta",
    "q.m12#23.o2" to "Essere in due",
    "q.m12#23.o3" to "Usare la stessa corda",
    "q.m12#23.e" to "La conversione è il punto in cui gli incidenti di soccorso sono più frequenti. Ogni volta che si «smonta il vecchio», prima si costruisce il nuovo.",

    "q.m12#24.p" to "Quando la corda passa su uno spigolo vivo, cosa si deve fare?",
    "q.m12#24.o0" to "Mettere una protezione o cambiare il percorso, per non tagliare la calza",
    "q.m12#24.o1" to "Passare direttamente",
    "q.m12#24.o2" to "Tendere di più",
    "q.m12#24.o3" to "Sostituirla con una fettuccia",
    "q.m12#24.e" to "Una corda tagliata sotto carico perde resistenza di colpo. La protezione costa poco, il prezzo può essere una corda o una caduta.",

    "q.m12#25.p" to "Perché gli ancoraggi di un sistema di soccorso devono essere più robusti di quelli di una sosta normale?",
    "q.m12#25.o0" to "Devono reggere carico statico più oscillazioni dinamiche, e spesso c'è un solo sistema",
    "q.m12#25.o1" to "Perché è più importante",
    "q.m12#25.o2" to "Perché ci sono più persone",
    "q.m12#25.o3" to "Perché la corda è più lunga",
    "q.m12#25.e" to "In soccorso non c'è una seconda sosta che faccia da rete. Se l'ancoraggio cede, cadono due persone insieme.",

    "q.m12#26.p" to "Nel calcolare la forza necessaria per sollevare, oltre al vantaggio meccanico va considerato?",
    "q.m12#26.o0" to "Il peso del ferito e dell'attrezzatura, l'attrito di corda e carrucole, la resistenza del terreno",
    "q.m12#26.o1" to "Il meteo",
    "q.m12#26.o2" to "Il tempo",
    "q.m12#26.o3" to "Il peso dei compagni",
    "q.m12#26.e" to "La «forza teorica» viene spesso sottostimata. Sommando attrito e terreno, la forza reale può essere il doppio di quella teorica.",

    "q.m12#27.p" to "Appena il sistema è allestito, cosa va fatto per primo?",
    "q.m12#27.o0" to "Una prova a vuoto, per verificare percorso, bloccanti e ancoraggi",
    "q.m12#27.o1" to "Tirare subito la persona",
    "q.m12#27.o2" to "Fare una foto",
    "q.m12#27.o3" to "Raccogliere la corda",
    "q.m12#27.e" to "Una prova a vuoto intercetta l'80 % degli errori di allestimento. Costa dieci secondi e può evitare un cedimento del sistema.",
    // ---------- m13 Autosoccorso e recupero in cordata ----------
    "q.m13#14.p" to "Nella risalita con nodi autobloccanti (prusiking), qual è la sequenza corretta?",
    "q.m13#14.o0" to "In piedi (spingere su il bloccante) → sedersi (trasferire il peso) → spingere giù il bloccante → ripetere",
    "q.m13#14.o1" to "Spingere insieme i due bloccanti",
    "q.m13#14.o2" to "Spingere solo il bloccante superiore",
    "q.m13#14.o3" to "Tirare con le braccia",
    "q.m13#14.e" to "Il ciclo «in piedi, seduto, spingi» trasferisce il peso tra bloccante superiore e inferiore. Spingere i due insieme fa scivolare subito.",

    "q.m13#15.p" to "A cosa serve la staffa (foot loop) nella risalita autonoma?",
    "q.m13#15.o0" to "Trasferire il peso sulle gambe, riducendo il carico sulle braccia",
    "q.m13#15.o1" to "Aumentare l'attrito",
    "q.m13#15.o2" to "Collegare l'imbrago",
    "q.m13#15.o3" to "Segnare la quota",
    "q.m13#15.e" to "Tirando solo con le braccia ci si esaurisce in poche decine di metri. La staffa coinvolge le gambe ed è decisiva per riuscire a uscire.",

    "q.m13#16.p" to "Nel recupero in cordata, cosa va fatto per primo?",
    "q.m13#16.o0" to "Frenare e fissare, impedendo a chi è caduto di continuare a scivolare",
    "q.m13#16.o1" to "Scendere subito nel crepaccio",
    "q.m13#16.o2" to "Chiamare i soccorsi",
    "q.m13#16.o3" to "Fare fotografie",
    "q.m13#16.e" to "La frenata è l'unica cosa che non può aspettare. Solo dopo si parla di comunicazioni, sistema e trazione.",

    "q.m13#17.p" to "Quando la persona è appesa dentro il crepaccio, quali danni vanno temuti di più?",
    "q.m13#17.o0" to "Ipotermia, compressione della corda e traumi da urto",
    "q.m13#17.o1" to "Scottature solari",
    "q.m13#17.o2" to "Mal di montagna",
    "q.m13#17.o3" to "Disidratazione",
    "q.m13#17.e" to "Dentro il crepaccio la temperatura è bassissima e la sospensione ostacola la circolazione. Il recupero deve essere «rapido», non solo «possibile».",

    "q.m13#18.p" to "Perché nel recupero si dà subito alla persona caduta un «autobloccaggio»?",
    "q.m13#18.o0" to "Perché non dipenda più dalla corda principale e chi soccorre abbia le mani libere per costruire il sistema",
    "q.m13#18.o1" to "Perché non ci si fida della corda",
    "q.m13#18.o2" to "Perché lo prevede la norma",
    "q.m13#18.o3" to "Perché manca l'attrezzatura",
    "q.m13#18.e" to "L'autobloccaggio (nodo o piccozza) stabilizza la posizione e dà alla persona qualcosa da fare, riducendo il panico.",

    "q.m13#19.p" to "Se il ferito non può muoversi da solo, qual è il modo corretto di estrarlo dal crepaccio?",
    "q.m13#19.o0" to "Allestire un sistema 3:1 o 5:1 e tirare dall'alto",
    "q.m13#19.o1" to "Tirare la corda a mano",
    "q.m13#19.o2" to "Far salire il ferito da solo",
    "q.m13#19.o3" to "Avvolgere la corda in vita",
    "q.m13#19.e" to "Tirare a mano è quasi impossibile e fa perdere il controllo. Il recupero con sistema è l'unico modo affidabile.",

    "q.m13#20.p" to "Da dove viene la pressione di tempo in un recupero?",
    "q.m13#20.o0" to "Velocità dell'ipotermia, cambi del meteo, esaurimento della squadra",
    "q.m13#20.o1" to "Solo dalla stanchezza",
    "q.m13#20.o2" to "Solo dal meteo",
    "q.m13#20.o3" to "Solo dall'ipotermia",
    "q.m13#20.e" to "I tre fattori agiscono insieme. Il piano deve considerare «quanto tempo serve per finire», non solo «se si può fare».",

    "q.m13#21.p" to "Nelle comunicazioni di soccorso, qual è il mezzo meno affidabile?",
    "q.m13#21.o0" to "Gridare attraverso un dosso di neve",
    "q.m13#21.o1" to "La radio",
    "q.m13#21.o2" to "I segnali di corda",
    "q.m13#21.o3" to "Il fischietto",
    "q.m13#21.e" to "Vento, lunghezza della corda e terreno mangiano la voce. Concordare prima segnali di corda o di fischietto è più affidabile che gridare sul momento.",

    "q.m13#22.p" to "Perché le manovre di autosoccorso vanno allenate «su terreno sicuro fino a diventare automatiche»?",
    "q.m13#22.o0" to "In una caduta reale l'attenzione è occupata dalla paura: solo i gesti automatici vengono eseguiti",
    "q.m13#22.o1" to "Per l'esame",
    "q.m13#22.o2" to "Per la velocità",
    "q.m13#22.o3" to "Per estetica",
    "q.m13#22.e" to "È la logica comune a tutto l'addestramento al soccorso: portare il gesto a non richiedere riflessione lascia margine per osservare e giudicare.",

    "q.m13#23.p" to "Nel recupero in cordata, qual è il compito principale del secondo di cordata?",
    "q.m13#23.o0" to "Aiutare nella frenata, preparare il sistema, sorvegliare i rischi dall'alto",
    "q.m13#23.o1" to "Fare fotografie",
    "q.m13#23.o2" to "Continuare ad avanzare",
    "q.m13#23.o3" to "Raccogliere la corda",
    "q.m13#23.e" to "È qui il senso della cordata di tre: uno frena, uno costruisce il sistema, uno osserva. In due si deve fare tutto insieme.",

    "q.m13#24.p" to "Se la persona caduta non risponde, quale priorità prevale?",
    "q.m13#24.o0" to "Estrarla il prima possibile e iniziare le manovre di rianimazione, chiedendo aiuto esterno",
    "q.m13#24.o1" to "Costruire prima un 5:1",
    "q.m13#24.o2" to "Aspettare i soccorsi",
    "q.m13#24.o3" to "Annotare prima i dati",
    "q.m13#24.e" to "La mancanza di risposta significa una finestra temporale molto breve. In quel caso «essere rapidi» conta più di «fare meno fatica», e si usa il sistema più semplice possibile.",

    "q.m13#25.p" to "Dopo il recupero, qual è il passo che si trascura più spesso?",
    "q.m13#25.o0" to "Rivedere sistema e procedura, mettendo per iscritto i problemi",
    "q.m13#25.o1" to "Raccogliere la corda",
    "q.m13#25.o2" to "Scendere",
    "q.m13#25.o3" to "Mangiare",
    "q.m13#25.e" to "La differenza tra esercitazione e situazione reale emerge nel debriefing: quale passaggio è stato lento, quale nodo è stato fatto male, quale ordine nessuno ha sentito.",

    "q.m13#26.p" to "Perché il sistema di recupero deve essere «indipendente dalla corda principale»?",
    "q.m13#26.o0" to "La corda principale può essere danneggiata da schegge o spigoli ed è ancora sotto carico",
    "q.m13#26.o1" to "Perché lo prevede la norma",
    "q.m13#26.o2" to "Perché è più lunga",
    "q.m13#26.o3" to "Perché è più leggera",
    "q.m13#26.e" to "Appendere il sistema di recupero a una corda danneggiata e sotto carico significa sommare due rischi in uno.",

    "q.m13#27.p" to "In zona di crepacci, cosa deve decidere la squadra in anticipo?",
    "q.m13#27.o0" to "Chi frena, chi costruisce il sistema, come si comunica",
    "q.m13#27.o1" to "Chi va davanti",
    "q.m13#27.o2" to "Chi porta più peso",
    "q.m13#27.o3" to "Chi fa le foto",
    "q.m13#27.e" to "I ruoli vanno decisi prima di partire. Nei primi trenta secondi dopo una caduta nessuno ha tempo di discutere «chi fa cosa».",

    // ---------- m14 Valutazione del pericolo e decisione ----------
    "q.m14#17.p" to "Qual è la tipica manifestazione del «costo sommerso» nelle decisioni in montagna?",
    "q.m14#17.o0" to "Abbiamo speso tanti soldi e tanto tempo, non possiamo tornare a casa a mani vuote",
    "q.m14#17.o1" to "Le previsioni sono imprecise",
    "q.m14#17.o2" to "L'attrezzatura non basta",
    "q.m14#17.o3" to "I compagni sono lenti",
    "q.m14#17.e" to "Più si è investito, più difficile è rinunciare. Ma il costo già pagato non si recupera continuando: si aggiunge solo rischio nuovo.",

    "q.m14#18.p" to "In quali condizioni si presenta più facilmente il «pensiero di gruppo»?",
    "q.m14#18.o0" to "Squadra molto coesa, assenza di voci contrarie, leader che si esprime troppo presto",
    "q.m14#18.o1" to "Squadra molto divisa",
    "q.m14#18.o2" to "Pochi partecipanti",
    "q.m14#18.o3" to "Meteo cattivo",
    "q.m14#18.e" to "La coesione è un bene, ma soffoca il dissenso. Far parlare per primo il più giovane e designare un «avvocato del diavolo» sono contromisure comuni.",

    "q.m14#19.p" to "Che cos'è il «pregiudizio di conferma»?",
    "q.m14#19.o0" to "Cercare solo le informazioni che sostengono il proprio giudizio, ignorando le prove contrarie",
    "q.m14#19.o1" to "Non ricordare le informazioni",
    "q.m14#19.o2" to "Essere troppo prudenti",
    "q.m14#19.o3" to "Dipendere dagli altri",
    "q.m14#19.e" to "Se si vuole «salire oggi», si notano solo i segnali di bel tempo. L'unico antidoto è cercare attivamente il controesempio.",

    "q.m14#20.p" to "Perché le decisioni importanti richiedono una lista di controllo?",
    "q.m14#20.o0" to "Con stanchezza e pressione si saltano voci: la lista trasforma «ricordarsi» in «verificare una per una»",
    "q.m14#20.o1" to "Per avere un archivio",
    "q.m14#20.o2" to "Per sembrare professionali",
    "q.m14#20.o3" to "Perché lo prevede la norma",
    "q.m14#20.e" to "La lista non sostituisce il giudizio: serve a garantire che tutte le informazioni necessarie al giudizio siano presenti.",

    "q.m14#21.p" to "Qual è un esempio di «effetto ancora» in un programma di salita?",
    "q.m14#21.o0" to "Prendere «6 ore fino al campo» come riferimento e ignorare le condizioni reali dell'itinerario",
    "q.m14#21.o1" to "Fidarsi della guida",
    "q.m14#21.o2" to "Guardare la carta",
    "q.m14#21.o3" to "Misurare la temperatura",
    "q.m14#21.e" to "Una volta fissato un punto di riferimento, tutti i giudizi successivi si regolano su quello. Bisogna basarsi sul progresso reale, non sul valore del piano.",

    "q.m14#22.p" to "Qual è il valore di annotare una decisione (ora, motivo, conclusione)?",
    "q.m14#22.o0" to "Dà basi solide al debriefing e fa condividere alla squadra la stessa lettura dei fatti",
    "q.m14#22.o1" to "Per il rapporto",
    "q.m14#22.o2" to "Per l'assicurazione",
    "q.m14#22.o3" to "Per scrivere un libro",
    "q.m14#22.e" to "Senza annotazioni il debriefing diventa «ognuno dice la sua». Scrivere la cronologia mostra in quale momento si sarebbe potuto decidere prima.",

    "q.m14#23.p" to "Quale rischio concreto porta l'«alone dell'esperto»?",
    "q.m14#23.o0" to "Nessuno osa contestare un errore evidente, e l'errore viene eseguito senza ostacoli",
    "q.m14#23.o1" to "L'esperto si stanca",
    "q.m14#23.o2" to "L'esperto costa caro",
    "q.m14#23.o3" to "L'esperto non conosce l'itinerario",
    "q.m14#23.e" to "L'alone blocca la circolazione dell'informazione. Lo stato più pericoloso per una squadra non è «nessuno sa», ma «nessuno osa parlare».",

    // ---------- m17 Campi alti e gestione dei materiali ----------
    "q.m17#16.p" to "A cosa serve la «rotazione dei materiali» tra i campi alti?",
    "q.m17#16.o0" to "Avere in ogni campo la quantità giusta, evitando accumuli da una parte e mancanze dall'altra",
    "q.m17#16.o1" to "Per ridurre il peso",
    "q.m17#16.o2" to "Per facilitare le statistiche",
    "q.m17#16.o3" to "Per conformità",
    "q.m17#16.e" to "In spedizione i materiali si distribuiscono «per tratta». Senza una tabella di rotazione il risultato più comune è scoprire prima della vetta che al campo alto manca il gas.",

    "q.m17#17.p" to "Come va stimato il combustibile di un campo?",
    "q.m17#17.o0" to "Persone × giorni × consumo pro capite al giorno (sciogliere la neve è la voce più pesante)",
    "q.m17#17.o1" to "In base al numero di cartucce",
    "q.m17#17.o2" to "In base al peso",
    "q.m17#17.o3" to "A esperienza",
    "q.m17#17.e" to "Sciogliere la neve per l'acqua è la spesa di combustibile più grande in quota. La stima va fatta sul «meteo più freddo», non sulle condizioni ideali.",

    "q.m17#18.p" to "Su cosa si concentra il rinforzo di una tenda con vento forte?",
    "q.m17#18.o0" to "Angolo dei tiranti, punti di fissaggio sul lato sopravvento e zoccolo di neve",
    "q.m17#18.o1" to "Il colore della tenda",
    "q.m17#18.o2" to "La cerniera della camera interna",
    "q.m17#18.o3" to "Lo spessore del telo sottotenda",
    "q.m17#18.e" to "Una tenda cedendo di solito non strappa il tessuto: cede prima un punto di fissaggio. Doppi tiranti sul lato sopravvento e blocchi di neve sullo zoccolo sono la prassi.",

    "q.m17#19.p" to "Quali sono vantaggio e rischio di una buca nella neve su un pendio?",
    "q.m17#19.o0" to "Ottima resistenza al vento e calore; ma rischio di crollo e di monossido di carbonio",
    "q.m17#19.o1" to "Risparmia la tenda; ma è troppo fredda",
    "q.m17#19.o2" to "È comoda; ma è vietata",
    "q.m17#19.o3" to "Non ha rischi",
    "q.m17#19.e" to "Una buca nella neve richiede foro di ventilazione e valutazione dello spessore della volta. Mettere il fornello in una buca chiusa è lo scenario tipico di intossicazione da monossido.",

    "q.m17#20.p" to "Usando il fornello dentro la tenda, da cosa ci si deve proteggere soprattutto?",
    "q.m17#20.o0" to "Monossido di carbonio e incendio",
    "q.m17#20.o1" to "Umidità",
    "q.m17#20.o2" to "Il freddo",
    "q.m17#20.o3" to "Deformazione della tenda",
    "q.m17#20.e" to "Il monossido è incolore e inodore e i sintomi somigliano a quelli del mal di montagna. Va mantenuta la ventilazione e si opera preferibilmente nell'abside o fuori dalla tenda.",

    "q.m17#21.p" to "Qual è il principio di gestione dei rifiuti nei campi alti?",
    "q.m17#21.o0" to "Portare tutto giù, senza seppellire né bruciare nei campi alti",
    "q.m17#21.o1" to "Seppellire nella neve",
    "q.m17#21.o2" to "Bruciare",
    "q.m17#21.o3" to "Lasciarli al campo per la squadra successiva",
    "q.m17#21.e" to "In quota la decomposizione è lentissima e sia seppellire sia bruciare riemergono allo scioglimento. Portare giù è l'unica pratica conforme.",

    "q.m17#22.p" to "Sciogliendo la neve per l'acqua, come si guadagna efficienza?",
    "q.m17#22.o0" to "Mettere prima un po' d'acqua e poi la neve, con fiamma alta, evitando di scaldare a secco",
    "q.m17#22.o1" to "Riempire subito di neve",
    "q.m17#22.o2" to "Fiamma bassa e lunga",
    "q.m17#22.o3" to "Usare acqua fredda",
    "q.m17#22.e" to "Scaldare a secco brucia il fondo del pentolino ed è inefficientissimo. «Un fondo d'acqua più fiamma alta» fa risparmiare molto combustibile e tempo.",

    "q.m17#23.p" to "Come va organizzata la quota di sonno nei campi alti?",
    "q.m17#23.o0" to "Ruotare secondo il piano, evitando notti consecutive al campo più alto",
    "q.m17#23.o1" to "Più in alto è, meglio è",
    "q.m17#23.o2" to "Dormire sempre al campo più alto",
    "q.m17#23.o3" to "A caso",
    "q.m17#23.e" to "La rotazione concilia aclimatazione e recupero. Dormire notti consecutive in quota accumula stanchezza e rallenta tutto il programma.",

    // ---------- m18 Obiettivi: Muztagh Ata e Ama Dablam ----------
    "q.m18#16.p" to "Quali sono quota e posizione del Muztagh Ata?",
    "q.m18#16.o0" to "7.509 m, Akto nel Xinjiang, margine orientale del Pamir",
    "q.m18#16.o1" to "6.812 m, Nepal",
    "q.m18#16.o2" to "7.134 m, Kirghizistan",
    "q.m18#16.o3" to "8.163 m, Nepal",
    "q.m18#16.e" to "Il «padre dei ghiacci» è una delle prime scelte cinesi di livello 7.000: pendii di neve lunghissimi, con forte richiesta di aclimatazione e resistenza.",

    "q.m18#17.p" to "Qual è la difficoltà principale del Muztagh Ata?",
    "q.m18#17.o0" to "Aclimatazione in quota e resistenza sui lunghi pendii di neve, non la difficoltà tecnica",
    "q.m18#17.o1" to "Pareti verticali di roccia",
    "q.m18#17.o2" to "Crepacci fitti",
    "q.m18#17.o3" to "Arrampicata tecnica su ghiaccio",
    "q.m18#17.e" to "La difficoltà tecnica è relativamente contenuta, ma «lungo, alto e freddo» amplificano ogni carenza di preparazione e di aclimatazione.",

    "q.m18#18.p" to "In quale paese o regione si trova il Lenin Peak?",
    "q.m18#18.o0" to "Al confine tra Kirghizistan e Tagikistan",
    "q.m18#18.o1" to "Nepal",
    "q.m18#18.o2" to "Xinjiang, Cina",
    "q.m18#18.o3" to "Pakistan",
    "q.m18#18.e" to "Il Lenin Peak del Pamir è spesso il primo 7.000, ma richiede comunque di affrontare quota elevata e terreno glaciale.",

    "q.m18#19.p" to "Qual è la quota dell'Ama Dablam?",
    "q.m18#19.o0" to "6.812 m",
    "q.m18#19.o1" to "7.509 m",
    "q.m18#19.o2" to "7.126 m",
    "q.m18#19.o3" to "6.189 m",
    "q.m18#19.e" to "Sotto i 7.000 metri, ma il terreno misto roccia-neve su pareti ripidissime e l'enorme esposizione la pongono tecnicamente al livello di un 7.000 e oltre.",

    "q.m18#20.p" to "Per quale passaggio l'Ama Dablam è spesso usata come «pietra di paragone»?",
    "q.m18#20.o0" to "Preparazione tecnica e psicologica per gli 8.000",
    "q.m18#20.o1" to "Prima montagna in assoluto",
    "q.m18#20.o2" to "Itinerario sciistico",
    "q.m18#20.o3" to "Itinerario escursionistico",
    "q.m18#20.e" to "L'esposizione e la combinazione tecnica verificano «se si riesce ancora a fare il gesto giusto sotto pressione».",

    "q.m18#21.p" to "La finestra stagionale di un 7.000 è di solito?",
    "q.m18#21.o0" to "Più stretta di quella di un 5.000 o 6.000: la decidono venti d'alta quota e nevicate",
    "q.m18#21.o1" to "Aperta tutto l'anno",
    "q.m18#21.o2" to "Solo in inverno",
    "q.m18#21.o3" to "Identica a quella di bassa quota",
    "q.m18#21.e" to "Più alta è la quota, più la finestra dipende dai venti in quota e dal monsone. Una finestra stretta impone di «aspettare» e «ritirarsi» con più decisione.",

    "q.m18#22.p" to "Nello scegliere un obiettivo di 7.000, quale capacità va verificata per prima?",
    "q.m18#22.o0" to "Aver già completato più volte, con stabilità, lunghi pendii di neve e autogestione su un 6.000",
    "q.m18#22.o1" to "Il grado di arrampicata su roccia",
    "q.m18#22.o2" to "I tempi di corsa",
    "q.m18#22.o3" to "La quantità di attrezzatura",
    "q.m18#22.e" to "La soglia dei 7.000 è «tenuta e autonomia», non un singolo gesto tecnico. Prima si guarda il proprio percorso sui 6.000.",

    "q.m18#23.p" to "Per queste montagne, permessi e logistica richiedono di solito?",
    "q.m18#23.o0" to "Pratiche con settimane di anticipo, guida, trasporto a dorso e materiali per i campi",
    "q.m18#23.o1" to "Pratiche sul posto",
    "q.m18#23.o2" to "Nessun permesso",
    "q.m18#23.o3" to "Solo un biglietto",
    "q.m18#23.e" to "Più l'itinerario è remoto, più lunga è la catena logistica. Trattare permessi e logistica come «parte della preparazione tecnica» costa molto meno che rimediare all'ultimo.",

    // ---------- m19 Limiti fisiologici agli 8.000 ----------
    "q.m19#19.p" to "La «zona della morte» è di solito sopra quale quota?",
    "q.m19#19.o0" to "8.000 metri",
    "q.m19#19.o1" to "6.000 metri",
    "q.m19#19.o2" to "7.000 metri",
    "q.m19#19.o3" to "5.000 metri",
    "q.m19#19.e" to "Sopra gli 8.000 metri la pressione è circa un terzo di quella al livello del mare: il corpo non riesce a restare in equilibrio e consuma soltanto.",

    "q.m19#20.p" to "A 8.000 metri, perché anche «riposare» non permette un vero recupero?",
    "q.m19#20.o0" to "L'apporto di ossigeno non basta a sostenere la riparazione: il corpo è in bilancio negativo",
    "q.m19#20.o1" to "Perché fa troppo freddo",
    "q.m19#20.o2" to "Perché si dorme male",
    "q.m19#20.o3" to "Perché si è disidratati",
    "q.m19#20.e" to "È la base fisiologica di «meglio restare il meno possibile». Tutta la tattica è costruita per «ridurre l'esposizione».",

    "q.m19#21.p" to "Nel calo cognitivo d'alta quota, qual è la manifestazione più pericolosa?",
    "q.m19#21.o0" to "Non accorgersi che il proprio giudizio è peggiorato",
    "q.m19#21.o1" to "Avere poca memoria",
    "q.m19#21.o2" to "Reagire lentamente",
    "q.m19#21.o3" to "Non riuscire a concentrarsi",
    "q.m19#21.e" to "La carenza di ossigeno indebolisce prima di tutto la capacità di autovalutarsi. È il motivo per cui si «esternalizzano» le decisioni: liste scritte, verifica da parte di altri.",

    // ---------- m20 Sistemi di ossigeno e rifornimento ----------
    "q.m20#20.p" to "Perché «capacità utilizzabile» e «capacità nominale» di una bombola di ossigeno non coincidono?",
    "q.m20#20.o0" to "La pressione residua rende inutilizzabile l'ultima parte, e il freddo riduce la pressione",
    "q.m20#20.o1" to "Perché ci sono perdite",
    "q.m20#20.o2" to "Perché è etichettata male",
    "q.m20#20.o3" to "Per usura della maschera",
    "q.m20#20.e" to "Nel calcolo va usata la «quantità utilizzabile». Prendere il valore nominale come utilizzabile è la causa più comune di «ossigeno finito prima» nel giorno di vetta.",

    "q.m20#21.p" to "Qual è il prezzo di aumentare la portata di ossigeno?",
    "q.m20#21.o0" to "L'autonomia si accorcia in proporzione e servono più bombole di riserva",
    "q.m20#21.o1" to "Nessun prezzo",
    "q.m20#21.o2" to "Si rompe la maschera",
    "q.m20#21.o3" to "La bombola si congela",
    "q.m20#21.e" to "Portata e autonomia sono inversamente proporzionali. Aumentando la portata bisogna ricalcolare il fabbisogno totale e le riserve.",
    // ---------- m21 I 14 Ottomila (1): Himalaya ----------
    "q.m21#18.p" to "Qual è la quota ufficiale più recente dell'Everest?",
    "q.m21#18.o0" to "8.848,86 m (misurazione congiunta Cina-Nepal del 2020)",
    "q.m21#18.o1" to "8.848 m",
    "q.m21#18.o2" to "8.850 m",
    "q.m21#18.o3" to "8.846 m",
    "q.m21#18.e" to "8.848,86 m è il valore pubblicato congiuntamente nel 2020. Il classico 8.848 m dei vecchi manuali resta diffuso: è normale trovare entrambi.",

    "q.m21#19.p" to "Qual è la posizione del Lhotse rispetto all'Everest?",
    "q.m21#19.o0" to "Immediatamente a sud dell'Everest, spesso salito sulla stessa linea",
    "q.m21#19.o1" to "A nord dell'Everest",
    "q.m21#19.o2" to "Nel Nepal occidentale",
    "q.m21#19.o3" to "Nel Karakorum",
    "q.m21#19.e" to "Le due cime condividono una parte della via del Colle Sud, per questo «Everest + Lhotse» viene spesso organizzato nella stessa spedizione.",

    "q.m21#20.p" to "Dove si trova il Kangchenjunga?",
    "q.m21#20.o0" to "Al confine tra Nepal e India",
    "q.m21#20.o1" to "Al confine tra Cina e Nepal",
    "q.m21#20.o2" to "In Pakistan",
    "q.m21#20.o3" to "In Bhutan",
    "q.m21#20.e" to "Terza vetta del mondo, al confine tra Nepal e India (Sikkim): permessi e logistica sono relativamente complessi.",

    "q.m21#21.p" to "Qual è la caratteristica dell'Annapurna I?",
    "q.m21#21.o0" to "Mortalità relativamente alta, itinerario ripido con forte rischio di valanghe e caduta sassi",
    "q.m21#21.o1" to "È la più facile",
    "q.m21#21.o2" to "È la più alta",
    "q.m21#21.o3" to "Si sale tutto l'anno",
    "q.m21#21.e" to "È una delle più rischiose fra gli Ottomila. Il dato ricorda che l'ordine per altezza non è l'ordine per difficoltà.",

    // ---------- m22 I 14 Ottomila (2): Karakorum ----------
    "q.m22#17.p" to "Quali sono la quota ufficiale e il soprannome del K2?",
    "q.m22#17.o0" to "8.611 m, «montagna selvaggia»",
    "q.m22#17.o1" to "8.586 m, «leopardo delle nevi»",
    "q.m22#17.o2" to "8.126 m, «montagna nuda»",
    "q.m22#17.o3" to "8.080 m, «cima nascosta»",
    "q.m22#17.e" to "Il K2 è la seconda vetta del mondo e da tempo figura ai primi posti fra gli Ottomila per difficoltà tecnica e mortalità.",

    "q.m22#18.p" to "Quali sono il soprannome e il rischio principale del Nanga Parbat?",
    "q.m22#18.o0" to "«Montagna nuda»: il dislivello enorme porta con sé valanghe e caduta sassi",
    "q.m22#18.o1" to "«Padre dei ghiacci»",
    "q.m22#18.o2" to "«Cima nascosta»",
    "q.m22#18.o3" to "«Montagna che uccide»",
    "q.m22#18.e" to "La sua parete sud è uno dei maggiori dislivelli rocciosi del mondo. Itinerari esposti, meteo variabile e ritirata difficile.",

    "q.m22#19.p" to "Quali sono le quote del Gasherbrum I e II?",
    "q.m22#19.o0" to "8.080 m e 8.035 m",
    "q.m22#19.o1" to "8.051 m e 8.080 m",
    "q.m22#19.o2" to "8.611 m e 8.586 m",
    "q.m22#19.o3" to "8.188 m e 8.167 m",
    "q.m22#19.e" to "GI 8.080, GII 8.035. Le due cime vengono spesso confrontate, ma itinerari e difficoltà sono molto diversi.",

    "q.m22#20.p" to "Qual è la quota del Broad Peak?",
    "q.m22#20.o0" to "8.051 m",
    "q.m22#20.o1" to "8.035 m",
    "q.m22#20.o2" to "8.080 m",
    "q.m22#20.o3" to "8.126 m",
    "q.m22#20.e" to "Il Broad Peak, 8.051 m, è spesso considerato uno degli Ottomila tecnicamente più accessibili, ma conserva lunghi pendii di neve e rischio d'alta quota.",

    "q.m22#21.p" to "Quanti Ottomila si trovano in Pakistan?",
    "q.m22#21.o0" to "Cinque",
    "q.m22#21.o1" to "Tre",
    "q.m22#21.o2" to "Quattro",
    "q.m22#21.o3" to "Due",
    "q.m22#21.e" to "K2, Nanga Parbat, Gasherbrum I e II, Broad Peak: cinque in tutto.",

    // ---------- m23 Esame finale completo (1) ----------
    "q.m23#18.p" to "Scenario: a 7.500 m un compagno mostra atassia e l'ossigeno basta per 2 ore. Cosa si fa per primo?",
    "q.m23#18.o0" to "Scendere subito somministrando ossigeno e avvisare il campo base perché prepari il supporto",
    "q.m23#18.o1" to "Riposare e osservare",
    "q.m23#18.o2" to "Dare prima un farmaco",
    "q.m23#18.o3" to "Proseguire fino al campo e trattare lì",
    "q.m23#18.e" to "L'atassia fa sospettare un HACE. La discesa è l'unica misura di efficacia certa, l'ossigeno serve a guadagnare tempo.",

    "q.m23#19.p" to "Scenario: nel giorno di vetta la corda fissa risulta sfilacciata dalla squadra precedente. Cosa si fa?",
    "q.m23#19.o0" to "Non usare quel tratto: cambiare linea o ritirarsi",
    "q.m23#19.o1" to "Usarla comunque con attenzione",
    "q.m23#19.o2" to "Avvisare solo chi viene dopo",
    "q.m23#19.o3" to "Annotare e proseguire",
    "q.m23#19.e" to "La resistenza di una corda consumata non è stimabile. La corda fissa è «la linea di vita di tutti»: non si compensa con «stare attenti».",

    "q.m23#20.p" to "Scenario: a 6.500 m arriva una tempesta di neve con visibilità di 5 metri. Qual è la scelta più ragionevole?",
    "q.m23#20.o0" to "Costruire un riparo sul posto e aspettare, oppure rientrare con il GPS lungo la traccia già registrata",
    "q.m23#20.o1" to "Continuare a cercare la via",
    "q.m23#20.o2" to "Dividersi per cercare",
    "q.m23#20.o3" to "Sedersi e aspettare il sereno",
    "q.m23#20.e" to "Con il white-out «cercare la via» porta quasi sempre fuori rotta. Fermarsi a costruire un riparo o seguire la traccia registrata sono le uniche due opzioni praticabili.",

    "q.m23#21.p" to "Scenario: tutta la squadra è d'accordo di proseguire, solo tu senti che non va, ma non sai spiegare perché. Cosa fai?",
    "q.m23#21.o0" to "Dire chiaramente «non mi torna» e chiedere alla squadra di ricontrollare insieme le informazioni chiave",
    "q.m23#21.o1" to "Obbedire alla maggioranza",
    "q.m23#21.o2" to "Seguire in silenzio",
    "q.m23#21.o3" to "Tornare indietro da solo",
    "q.m23#21.e" to "L'intuizione è spesso il segnale di «qualcosa che si è notato ma non si è ancora messo in parole». Dirla ad alta voce permette alla squadra di verificare i fatti insieme.",

    // ---------- m24 Esame finale completo (2) ----------
    "q.m24#18.p" to "Scenario: nel giorno di vetta si è 4 ore indietro, il vento aumenta e un compagno rallenta. Qual è il giudizio più ragionevole?",
    "q.m24#18.o0" to "Ritirarsi secondo le condizioni di rientro fissate, annotando su cosa si è basata la decisione",
    "q.m24#18.o1" to "Proseguire e valutare in vetta",
    "q.m24#18.o2" to "Mandare indietro da solo chi è lento",
    "q.m24#18.o3" to "Accelerare per recuperare",
    "q.m24#18.e" to "Quando compaiono tre segnali insieme, la ragione per «continuare» viene di solito dalla pressione dell'obiettivo, non dai fatti. Le condizioni di rientro esistono per questo.",

    "q.m24#19.p" to "Scenario: un compagno ha dispnea a riposo ma la saturazione è ancora 80 %. Cosa si fa?",
    "q.m24#19.o0" to "Trattarlo come HAPE: riposo, ossigeno, preparare la discesa",
    "q.m24#19.o1" to "Continuare a osservare",
    "q.m24#19.o2" to "Farlo bere di più",
    "q.m24#19.o3" to "Dargli un analgesico",
    "q.m24#19.e" to "I sintomi vengono prima dei numeri. La dispnea a riposo è il segnale centrale dell'HAPE, e la discesa è la misura più affidabile.",

    "q.m24#20.p" to "Scenario: su un tratto di corda fissa un ancoraggio è dubbio e la squadra è già a metà. Cosa si fa?",
    "q.m24#20.o0" to "Smettere di usare quel tratto, aggiungere un backup o cambiare linea, mettendo prima le persone in posizione sicura",
    "q.m24#20.o1" to "Passare in fretta",
    "q.m24#20.o2" to "Avvisare solo chi viene dopo",
    "q.m24#20.o3" to "Continuare a usarlo",
    "q.m24#20.e" to "«Siamo già a metà» non è una ragione per continuare. Il cedimento di un ancoraggio ha conseguenze sistemiche, non individuali.",

    "q.m24#21.p" to "Scenario: la spedizione è finita. Cosa vale la pena conservare soprattutto?",
    "q.m24#21.o0" to "Un debriefing scritto con cronologia, criteri delle decisioni ed errori commessi",
    "q.m24#21.o1" to "Le fotografie",
    "q.m24#21.o2" to "La lista dell'attrezzatura",
    "q.m24#21.o3" to "Le ricevute di spesa",
    "q.m24#21.e" to "Il debriefing trasforma «un'esperienza» in «competenza». Scrivere «in quale momento si sarebbe potuto decidere prima» è ciò che rende possibile deciderlo prima la volta dopo.",

    // ---------- m25 Psicologia d'alta quota e abitudini decisionali ----------
    "q.m25#12.p" to "Dopo un ritiro, qual è il debriefing più utile?",
    "q.m25#12.o0" to "Rivedere su cosa si basava il giudizio di allora: quali informazioni sono state trascurate, in quale momento si poteva decidere prima",
    "q.m25#12.o1" to "Annotare solo la conclusione",
    "q.m25#12.o2" to "Attribuire tutto alla fortuna",
    "q.m25#12.o3" to "Non parlarne più",
    "q.m25#12.e" to "Lo scopo non è attribuire colpe, ma trasformare «la prossima volta accorgersene prima» in esperienza concreta. Scrivere la cronologia serve più che scrivere le sensazioni.",
    // ---------- l19 Pianificazione della salita e decisione di ritirata ----------
    "q.l19#16.p" to "Un piano di salita eseguibile deve contenere, fra le informazioni «negative»?",
    "q.l19#16.o0" to "A quali condizioni si rinuncia, da dove si scende e fino a dove",
    "q.l19#16.o1" to "Solo l'itinerario di salita",
    "q.l19#16.o2" to "Solo la lista dell'attrezzatura",
    "q.l19#16.o3" to "Solo il budget",
    "q.l19#16.e" to "Un piano che dice solo «come riuscire» perde forza sotto pressione. Le condizioni di ritirata vanno scritte prima.",

    "q.l19#17.p" to "A cosa serve un «itinerario alternativo» nel piano?",
    "q.l19#17.o0" to "Quando l'itinerario principale non è praticabile, resta comunque un'opzione attuabile",
    "q.l19#17.o1" to "Per estetica",
    "q.l19#17.o2" to "Per risparmiare",
    "q.l19#17.o3" to "Per conformità",
    "q.l19#17.e" to "L'alternativa evita che, quando il piano principale si blocca, si insista per forza. Senza piano B, il piano A diventa l'unica scommessa.",

    "q.l19#18.p" to "Perché le condizioni di ritirata vanno «fissate in anticipo»?",
    "q.l19#18.o0" to "Con la stanchezza e la pressione dell'obiettivo si tende ad allargare continuamente i criteri",
    "q.l19#18.o1" to "Perché non si ricordano",
    "q.l19#18.o2" to "Perché lo prevede la norma",
    "q.l19#18.o3" to "Perché lo chiede la guida",
    "q.l19#18.e" to "I criteri devono essere concreti: a che ora, con quale vento, con quale visibilità, con quali sintomi e in chi. Un criterio vago equivale a nessun criterio.",

    "q.l19#19.p" to "Quando nella squadra qualcuno vuole ritirarsi e altri vogliono salire, qual è la gestione più sensata?",
    "q.l19#19.o0" to "Tornare ai criteri concordati prima e giudicare sui fatti, non sulle intenzioni",
    "q.l19#19.o1" to "Votare",
    "q.l19#19.o2" to "Seguire il capo",
    "q.l19#19.o3" to "Separarsi",
    "q.l19#19.e" to "Trasformare il disaccordo in un «confronto con i criteri» evita che diventi un conflitto personale. I criteri sono stati fissati prima, non inventati sul posto.",

    "q.l19#20.p" to "Fino a che livello va studiata in anticipo la via di ritirata?",
    "q.l19#20.o0" to "Conoscere le svolte chiave, i punti di corda doppia e la posizione dei campi di riserva",
    "q.l19#20.o1" to "Conoscere la direzione generale",
    "q.l19#20.o2" to "Non serve",
    "q.l19#20.o3" to "Si guarda una volta sul posto",
    "q.l19#20.e" to "Ci si ritira spesso con cattivo tempo. Con visibilità scarsa, «la direzione generale» equivale quasi a nessuna informazione.",

    "q.l19#21.p" to "Come si lascia di solito il margine di tempo in un piano?",
    "q.l19#21.o0" to "Un 20–30 % di margine su ogni tratta, più un giorno dedicato ai ritardi per meteo",
    "q.l19#21.o1" to "Nessun margine",
    "q.l19#21.o2" to "Solo un giorno",
    "q.l19#21.o3" to "Calcolando sulla velocità massima",
    "q.l19#21.e" to "Il margine è il budget dell'imprevisto. Un piano saturo crolla del tutto alla prima variazione.",

    // ---------- l20 Procedure di emergenza e soccorso ----------
    "q.l20#16.p" to "In una richiesta di soccorso, quale informazione si dimentica più spesso?",
    "q.l20#16.o0" to "La differenza tra le coordinate attuali e l'«ultima posizione nota»",
    "q.l20#16.o1" to "Il nome",
    "q.l20#16.o2" to "Il numero di persone",
    "q.l20#16.o3" to "Il meteo",
    "q.l20#16.e" to "«Dove sono ora» e «dove ho confermato l'ultima volta di essere» sono due informazioni diverse: la seconda determina l'area di ricerca.",

    "q.l20#17.p" to "Perché il soccorso in elicottero è spesso difficile in alta quota?",
    "q.l20#17.o0" to "L'aria rarefatta riduce portanza e carico utile, e le finestre di meteo sono brevi",
    "q.l20#17.o1" to "Perché costa molto",
    "q.l20#17.o2" to "Perché non ci sono rotte",
    "q.l20#17.o3" to "Perché i piloti non vogliono",
    "q.l20#17.e" to "È qui la ragione per cui «non si può contare sull'elicottero come piano». La capacità di autosoccorso e di attendere i soccorsi va costruita in proprio.",

    "q.l20#18.p" to "Chi deve lanciare la richiesta di soccorso?",
    "q.l20#18.o0" to "La persona di contatto designata, che la invia allo scadere del tempo secondo il piano",
    "q.l20#18.o1" to "Chiunque la veda",
    "q.l20#18.o2" to "Il ferito stesso",
    "q.l20#18.o3" to "Il giorno dopo",
    "q.l20#18.e" to "Un referente designato evita il «tutti pensavano che l'avesse fatto qualcun altro». Il piano deve dire «a che ora, chi, a chi».",

    "q.l20#19.p" to "Qual è di solito l'ordine di priorità del primo soccorso sul posto?",
    "q.l20#19.o0" to "Emostasi e vie aeree → riscaldare → immobilizzare → trasportare",
    "q.l20#19.o1" to "Prima il trasporto",
    "q.l20#19.o2" to "Prima l'immobilizzazione",
    "q.l20#19.o3" to "Prima il dolore",
    "q.l20#19.e" to "Si tratta prima ciò che uccide in pochi minuti, poi ciò che peggiora in poche ore. In alta quota il riscaldamento va anticipato.",

    "q.l20#20.p" to "Durante l'attesa dei soccorsi, cosa deve fare soprattutto la squadra?",
    "q.l20#20.o0" to "Costruire un riparo, mantenere il calore, segnalare la posizione e conservare le energie",
    "q.l20#20.o1" to "Continuare a cercare la via",
    "q.l20#20.o2" to "Dividersi per cercare aiuto",
    "q.l20#20.o3" to "Consumare tutta l'attrezzatura",
    "q.l20#20.e" to "L'obiettivo dell'attesa è «resistere fino all'arrivo dei soccorsi», non «risolvere da soli». Le energie sono la risorsa più preziosa.",

    "q.l20#21.p" to "Nel passaggio di consegne ai soccorritori, quali informazioni servono di più?",
    "q.l20#21.o0" to "Cronologia, evoluzione delle condizioni, trattamenti già fatti, materiali rimasti",
    "q.l20#21.o1" to "Le sensazioni provate",
    "q.l20#21.o2" to "Il panorama dell'itinerario",
    "q.l20#21.o3" to "La marca dell'attrezzatura",
    "q.l20#21.e" to "Cronologia e registro dei trattamenti determinano le valutazioni mediche successive. Consegnare per iscritto è più affidabile che raccontare a voce.",

    // ---------- t01 Difficoltà dell'itinerario e autovalutazione ----------
    "q.t01#0.p" to "Per valutare la difficoltà di un itinerario escursionistico, quale gruppo di informazioni basta di più?",
    "q.t01#0.o0" to "I chilometri",
    "q.t01#0.o1" to "Distanza + dislivello cumulato + fondo + rifornimenti e punti di uscita",
    "q.t01#0.o2" to "La quota massima",
    "q.t01#0.o3" to "Quanto ci hanno messo gli altri",
    "q.t01#0.e" to "I chilometri sono solo una voce. Sugli stessi 10 km, con 80 m o 800 m di dislivello il tempo può variare di due o tre volte; e il fondo, sterrato, ghiaia o roccia bagnata, cambia il rischio di storta.",

    "q.t01#1.p" to "Due itinerari sono entrambi di 10 km: A con 80 m di dislivello, B con 800 m. Qual è la differenza principale?",
    "q.t01#1.o0" to "La bellezza del panorama",
    "q.t01#1.o1" to "Tempo e dispendio fisico: B richiede circa due o tre volte A",
    "q.t01#1.o2" to "La quota",
    "q.t01#1.o3" to "Quasi nessuna",
    "q.t01#1.e" to "Il dislivello è la variabile che si trascura di più. Per esperienza, ogni 100 m di salita equivalgono a circa 500 m di pianura: 800 m di dislivello aggiungono di fatto 4 km.",

    "q.t01#2.p" to "Alla prima escursione, quali condizioni deve soddisfare un itinerario adatto?",
    "q.t01#2.o0" to "Concludibile entro 3 ore",
    "q.t01#2.o1" to "Dislivello cumulato entro 300 m",
    "q.t01#2.o2" to "Presenza di strade o paesi per scendere a metà percorso",
    "q.t01#2.o3" to "Campo pieno del telefono per tutto il percorso",
    "q.t01#2.e" to "Le prime tre sono confini di rischio controllabili. Il segnale è una questione di fortuna e non va messo nel piano: molte valli non ne hanno affatto.",

    "q.t01#3.p" to "Perché i «punti di uscita» vanno verificati prima del panorama?",
    "q.t01#3.o0" to "Di solito lì ci sono i bagni",
    "q.t01#3.o1" to "Se meteo o energie peggiorano si può scendere da lì, senza dover finire per forza il percorso",
    "q.t01#3.o2" to "Per le fotografie",
    "q.t01#3.o3" to "Perché lo richiede l'assicurazione",
    "q.t01#3.e" to "Il punto di uscita è ciò che trasforma «devo finire» in «posso fermarmi». Il piano deve sapere, per ogni tratto, dove è la discesa più vicina e quanto tempo serve per raggiungerla.",

    "q.t01#4.p" to "Lo stesso itinerario dopo la pioggia diventa molto più difficile: qual è il motivo principale?",
    "q.t01#4.o0" to "La temperatura scende",
    "q.t01#4.o1" to "Il fondo diventa scivoloso e fangoso, può servire guadare, e insieme aumentano tempo e rischio di storte",
    "q.t01#4.o2" to "Il panorama peggiora",
    "q.t01#4.o3" to "C'è meno gente",
    "q.t01#4.e" to "Il fondo scivoloso allunga il tempo e aumenta la probabilità di scivolare e distorcersi. Un percorso da 4 ore, dopo la pioggia, va stimato su 5–6 e richiede di rivalutare alcuni tratti ripidi in discesa.",

    "q.t01#5.p" to "Un compagno dice «questa via l'ho fatta in 4 ore». Come va interpretato?",
    "q.t01#5.o0" to "Allora la farò anch'io in 4 ore",
    "q.t01#5.o1" to "È il tempo di una persona esperta: la squadra deve calcolare 1,3–1,5 volte, sul più lento",
    "q.t01#5.o2" to "Significa che l'itinerario è semplice",
    "q.t01#5.o3" to "Non è un riferimento utilizzabile",
    "q.t01#5.e" to "Il tempo altrui dipende da forma fisica, carico e familiarità. La squadra calcola la durata sul più lento, aggiungendo pause, foto e ricerca della via: solo così si avvicina al reale.",

    "q.t01#6.p" to "Per stimare la durata di un'escursione, qual è il calcolo approssimativo più usato?",
    "q.t01#6.o0" to "Tempo base sulla distanza, più 30 minuti ogni 300–500 m di dislivello",
    "q.t01#6.o1" to "Solo la distanza",
    "q.t01#6.o2" to "Solo il dislivello",
    "q.t01#6.o3" to "In base al peso",
    "q.t01#6.e" to "La sola distanza sottostima il costo della salita. Calcolando separatamente «tempo di distanza + tempo di dislivello» e moltiplicando per un coefficiente di squadra, l'errore si riduce molto.",

    "q.t01#7.p" to "Perché confermare i «punti di uscita» prima di partire?",
    "q.t01#7.o0" to "Potendo scendere a metà, si può davvero parlare di sicurezza e di aggiustamenti",
    "q.t01#7.o1" to "Per le fotografie",
    "q.t01#7.o2" to "Per risparmiare sul biglietto",
    "q.t01#7.o3" to "Per viaggiare leggeri",
    "q.t01#7.e" to "Il punto di uscita è la «valvola di sicurezza» dell'itinerario. Senza, resta solo una strada: andare fino in fondo.",

    // ---------- t02 Scarpe, calze e piedi ----------
    "q.t02#0.p" to "Qual è il criterio più importante di calzata per uno scarpone da trekking?",
    "q.t02#0.o0" to "Più stretto è, più stabile",
    "q.t02#0.o1" to "Il tallone non scivola e in discesa le dita non urtano la punta",
    "q.t02#0.o2" to "Più grande è, più comodo",
    "q.t02#0.o3" to "Contano marca e prezzo",
    "q.t02#0.e" to "La prova va fatta nel pomeriggio, con le calze da trekking, camminando su un tratto in discesa. Se il piede scorre dentro la scarpa, in salita sfrega il tendine e in discesa batte le dita: in entrambi i casi si formano vesciche.",

    "q.t02#1.p" to "Qual è la causa più diretta delle vesciche?",
    "q.t02#1.o0" to "Scarpe troppo nuove",
    "q.t02#1.o1" to "Umidità, sfregamento e pressione localizzata che si sommano",
    "q.t02#1.o2" to "Camminare troppo a lungo",
    "q.t02#1.o3" to "Il colore delle calze",
    "q.t02#1.e" to "Raramente agisce un fattore solo. La sabbia nella scarpa crea pressione locale, il sudore ammorbidisce la pelle, e mezz'ora di cammino fa il resto.",

    "q.t02#2.p" to "Qual è il gruppo di pratiche più efficace per prevenire le vesciche?",
    "q.t02#2.o0" to "Mettere cerotti anti-sfregamento sui punti sensibili, tenere le calze asciutte, cambiarle a metà",
    "q.t02#2.o1" to "Indossare due paia di calze di cotone",
    "q.t02#2.o2" to "Ammollare i piedi prima di uscire",
    "q.t02#2.o3" to "Camminare senza fermarsi per non togliere le scarpe",
    "q.t02#2.e" to "Il cerotto sposta lo sfregamento dalla pelle al cerotto, il cambio di calze risolve l'umidità. Insieme bloccano la maggior parte delle vesciche.",

    "q.t02#3.p" to "In una lunga discesa, come vanno gestiti i lacci?",
    "q.t02#3.o0" to "Stringerli di più, per ridurre lo scivolamento del piede in avanti",
    "q.t02#3.o1" to "Allentarli del tutto",
    "q.t02#3.o2" to "Lasciarli come in salita",
    "q.t02#3.o3" to "Stringere solo la parte della caviglia",
    "q.t02#3.e" to "In discesa il piede scivola verso la punta. Stringendo la parte centrale e la caviglia e lasciando più lasso il collo del piede si blocca il tallone senza comprimere il dorso.",

    "q.t02#4.p" to "Compare un «punto caldo» sul piede — arrossato, caldo, dolente alla pressione. Cosa si fa?",
    "q.t02#4.o0" to "Fermarsi subito e trattarlo",
    "q.t02#4.o1" to "Mettere un cerotto anti-sfregamento o nastro adesivo",
    "q.t02#4.o2" to "Controllare che calze e scarpe non abbiano pieghe o sabbia",
    "q.t02#4.o3" to "Continuare e vedere se si buca",
    "q.t02#4.e" to "Il punto caldo è una fase reversibile e bastano due minuti; dopo la rottura la pelle è lesa, ogni passo allarga la ferita e si può infettare.",

    "q.t02#5.p" to "Perché sulle lunghe distanze si sconsigliano le calze di cotone?",
    "q.t02#5.o0" to "Il cotone assorbe il sudore senza smaltirlo: bagnato aumenta lo sfregamento e non tiene caldo",
    "q.t02#5.o1" to "Costano troppo",
    "q.t02#5.o2" to "Non traspirano e fanno odore",
    "q.t02#5.o3" to "Perdono colore",
    "q.t02#5.e" to "La fibra di cotone bagnata aderisce alla pelle e il coefficiente di attrito sale; se la temperatura cala, la calza bagnata porta via calore molto in fretta. Lana o fibre sintetiche smaltiscono l'umidità e tengono un po' di calore anche bagnate.",

    "q.t02#6.p" to "A cosa serve l'allacciatura con «blocco del tallone»?",
    "q.t02#6.o0" to "Fissare il tallone al retro della scarpa, riducendo l'urto delle dita in discesa",
    "q.t02#6.o1" to "Rendere la scarpa più stretta",
    "q.t02#6.o2" to "Facilitare la calzata",
    "q.t02#6.o3" to "Ridurre l'usura",
    "q.t02#6.e" to "In discesa il piede scivola in avanti e le dita che sbattono ripetutamente sulla punta sono la causa principale di unghie nere e vesciche. Bloccare il tallone risolve direttamente il problema.",

    "q.t02#7.p" to "Comprando scarpe da trekking, quale margine si consiglia di solito?",
    "q.t02#7.o0" to "Circa un dito davanti alle dita, perché dopo molto cammino il piede si gonfia",
    "q.t02#7.o1" to "Adesione perfetta",
    "q.t02#7.o2" to "Un numero in più",
    "q.t02#7.o3" to "Due numeri in più",
    "q.t02#7.e" to "Dopo ore di cammino il piede si gonfia leggermente. Un dito di margine evita l'urto in discesa senza essere così largo da far sfregare.",

    // ---------- t03 Zaino e carico ----------
    "q.t03#0.p" to "Qual è di solito il limite di carico in escursione?",
    "q.t03#0.o0" to "Il 10–20 % del peso corporeo, con i principianti al limite inferiore",
    "q.t03#0.o1" to "Più pesante è, più sicuro",
    "q.t03#0.o2" to "Il 30 % del peso corporeo",
    "q.t03#0.o3" to "Non c'è limite",
    "q.t03#0.e" to "Il peso si traduce direttamente in carico sulle articolazioni e consumo di ossigeno. Alla prima uscita di più giorni, tenere lo zaino al 12–15 % del peso corporeo e arrivare in fondo con energie significa aver scelto la misura giusta.",

    "q.t03#1.p" to "Dove vanno messi gli oggetti pesanti nello zaino?",
    "q.t03#1.o0" to "Vicino alla schiena, fra le scapole e la vita",
    "q.t03#1.o1" to "In fondo allo zaino",
    "q.t03#1.o2" to "All'esterno",
    "q.t03#1.o3" to "Nel cappuccio",
    "q.t03#1.e" to "Un peso vicino alla schiena e all'altezza del baricentro oscilla il meno possibile. In fondo tira verso il basso e carica la zona lombare; all'esterno allontana il baricentro e fa compensare collo e spalle.",

    "q.t03#2.p" to "Come si dividono correttamente spallacci e cintura lombare?",
    "q.t03#2.o0" to "Gli spallacci portano il carico",
    "q.t03#2.o1" to "La cintura porta la maggior parte del peso, gli spallacci tengono aderente e stabilizzano",
    "q.t03#2.o2" to "La cintura è solo decorativa",
    "q.t03#2.o3" to "È indifferente",
    "q.t03#2.e" to "La cintura trasferisce il peso al bacino, la parte del corpo che regge meglio. Spallacci troppo stretti comprimono i vasi della spalla e dopo qualche ora le braccia si intorpidiscono.",

    "q.t03#3.p" to "Quali oggetti vanno nel cappuccio o all'esterno?",
    "q.t03#3.o0" to "Giacca antipioggia, carta, frontale",
    "q.t03#3.o1" to "L'acqua della giornata e il cibo da cammino",
    "q.t03#3.o2" to "I pali della tenda agganciati all'esterno",
    "q.t03#3.o3" to "La borraccia più pesante",
    "q.t03#3.e" to "Nel cappuccio e all'esterno vanno solo cose «da usare subito» o di forma particolare. Un peso esterno rovina il baricentro e si impiglia in rami e rocce sui sentieri stretti.",

    "q.t03#4.p" to "Cosa comporta uno zaino che non aderisce alla schiena?",
    "q.t03#4.o0" to "Il baricentro si sposta indietro, collo e spalle compensano, e in discesa si è meno stabili",
    "q.t03#4.o1" to "È solo antiestetico",
    "q.t03#4.o2" to "La capacità diminuisce",
    "q.t03#4.o3" to "Nessun effetto",
    "q.t03#4.e" to "Se resta uno spazio fra schienale e dorso, lo zaino oscilla a ogni passo. Per stabilizzarlo ci si sporge in avanti e si alzano le spalle: dopo qualche ora la zona lombare è la prima a cedere.",

    "q.t03#5.p" to "Perché si consiglia di pesare lo zaino prima di partire?",
    "q.t03#5.o0" to "Conoscere il peso di base è l'unico modo per capire che cosa è superfluo",
    "q.t03#5.o1" to "Lo controllano in aeroporto",
    "q.t03#5.o2" to "Per pubblicarlo sui social",
    "q.t03#5.o3" to "Non ha utilità pratica",
    "q.t03#5.e" to "Pesare trasforma «sembra un po' pesante» in un numero. Togliendo posate duplicate, vestiti in più e bottiglie piene si risparmiano spesso due o tre chili.",

    "q.t03#6.p" to "Il limite di peso di uno zaino da trekking è comunemente indicato nel?",
    "q.t03#6.o0" to "20–25 % del peso corporeo",
    "q.t03#6.o1" to "10 %",
    "q.t03#6.o2" to "40 %",
    "q.t03#6.o3" to "Non esiste un limite",
    "q.t03#6.e" to "Oltre questa proporzione aumentano in modo netto il dispendio in salita e il rischio di infortuni. L'alleggerimento comincia da «quello che non si porta».",

    "q.t03#7.p" to "Qual è la funzione principale dei bastoncini in discesa?",
    "q.t03#7.o0" to "Ripartire il carico sul ginocchio e offrire un terzo punto di appoggio",
    "q.t03#7.o1" to "Aumentare la velocità",
    "q.t03#7.o2" to "Ridurre il peso dello zaino",
    "q.t03#7.o3" to "Difendersi",
    "q.t03#7.e" to "In discesa l'urto sul ginocchio è diverse volte quello in salita. I bastoncini trasferiscono parte del carico alla parte superiore del corpo e danno un terzo appoggio.",

    // ---------- t04 Andatura, idratazione ed energia ----------
    "q.t04#0.p" to "Per mantenere un'andatura sostenibile in salita, qual è il comportamento corretto?",
    "q.t04#0.o0" to "Tenere un'intensità da «riuscire a dire una frase intera» e riposare prima di stancarsi",
    "q.t04#0.o1" to "Salire tutto d'un fiato fino in cima e poi riposare",
    "q.t04#0.o2" to "Seguire il più veloce",
    "q.t04#0.o3" to "Restare sempre molto lenti",
    "q.t04#0.e" to "Il «test della parola» è il metro di intensità più semplice. Se non si riesce a dire una frase intera bisogna rallentare; fermarsi quando manca il fiato costa un recupero molto più lungo.",

    "q.t04#1.p" to "Qual è il ritmo corretto per bere?",
    "q.t04#1.o0" to "Bere quando viene sete",
    "q.t04#1.o1" to "Piccoli sorsi ogni 20–30 minuti, con sali minerali nelle giornate calde",
    "q.t04#1.o2" to "Bere un litro in una volta",
    "q.t04#1.o3" to "Bere il meno possibile per non dover andare in bagno",
    "q.t04#1.e" to "Quando arriva la sete manca già circa l'1–2 % del peso corporeo in acqua, e lucidità e resistenza iniziano a calare. Bere a piccoli sorsi a intervalli regolari si assorbe meglio di un litro tutto insieme.",

    "q.t04#2.p" to "Qual è il modo più efficace di integrare energia durante il cammino?",
    "q.t04#2.o0" to "30–60 g di carboidrati all'ora, in piccole dosi frequenti",
    "q.t04#2.o1" to "Un pasto abbondante quando arriva la fame",
    "q.t04#2.o2" to "Solo bevande sportive",
    "q.t04#2.o3" to "Resistere con la forza di volontà fino al campo",
    "q.t04#2.e" to "La quantità di carboidrati assorbibile in un'ora è limitata: mangiarne troppi in una volta dà solo gonfiore. Mangiare camminando (frutta secca, barrette, pane) è più stabile che fermarsi a fare un pasto.",

    "q.t04#3.p" to "Quali sono i segnali precoci di ipoglicemia?",
    "q.t04#3.o0" to "Mani che tremano, sudore freddo",
    "q.t04#3.o1" to "Irritabilità improvvisa o rallentamento dei riflessi",
    "q.t04#3.o2" to "Vista che si offusca o senso di vuoto",
    "q.t04#3.o3" to "Energia che improvvisamente aumenta",
    "q.t04#3.e" to "Quando compaiono questi segnali ci si ferma e si prendono 15–20 g di carboidrati rapidi (zucchero, succo): in dieci minuti il miglioramento è evidente. Insistere può portare allo svenimento.",

    "q.t04#4.p" to "Perché le pause non dovrebbero superare i 10 minuti?",
    "q.t04#4.o0" to "Il corpo si raffredda e i muscoli si irrigidiscono: ripartire costa più energia",
    "q.t04#4.o1" to "I compagni si lamentano",
    "q.t04#4.o2" to "Si perde tempo",
    "q.t04#4.o3" to "Non c'è una ragione",
    "q.t04#4.e" to "Dopo una sosta lunga la frequenza cardiaca scende e la temperatura muscolare cala: il primo chilometro alla ripresa pesa il doppio. Meglio molte pause brevi che una lunga.",

    "q.t04#5.p" to "In quali condizioni si verifica di solito il «crollo» in escursione?",
    "q.t04#5.o0" to "Dopo 2–3 ore dall'inizio, quando il glicogeno si esaurisce e nel frattempo si è quasi non integrato",
    "q.t04#5.o1" to "Prima di partire il primo giorno",
    "q.t04#5.o2" to "In discesa",
    "q.t04#5.o3" to "Quando si è dormito poco",
    "q.t04#5.e" to "Le riserve di glicogeno coprono circa 90–120 minuti di attività a intensità media. Oltre quel tempo senza carboidrati arrivano la mancanza improvvisa di forze, le vertigini e la voglia di non parlare.",

    "q.t04#6.p" to "Qual è l'indicatore soggettivo più pratico per capire se l'andatura è giusta?",
    "q.t04#6.o0" to "Il «test della parola»: si riesce ancora a dire una frase intera",
    "q.t04#6.o1" to "Il numero di battiti",
    "q.t04#6.o2" to "Quanto si suda",
    "q.t04#6.o3" to "La frequenza dei passi",
    "q.t04#6.e" to "Riuscire a dire una frase intera indica che si è ancora in campo aerobico. Non riuscirci significa intensità troppo alta: sulle lunghe distanze le energie finiscono prima.",

    "q.t04#7.p" to "Nelle giornate calde, qual è il momento più trascurato per integrare i sali minerali?",
    "q.t04#7.o0" to "Prima di partire e nella prima metà della giornata, invece di aspettare i crampi",
    "q.t04#7.o1" to "Dopo la discesa",
    "q.t04#7.o2" to "Prima di dormire",
    "q.t04#7.o3" to "Durante i pasti",
    "q.t04#7.e" to "Quando arrivano i crampi la carenza è già installata. Integrare poco, presto e per tutta la durata è più efficace che bere molto a posteriori.",
    // ---------- t05 Progettare un itinerario di più giorni ----------
    "q.t05#0.p" to "Nel progettare un itinerario di più giorni, cosa si definisce per primo?",
    "q.t05#0.o0" to "I limiti giornalieri di distanza e dislivello, e i punti di rifornimento e di uscita",
    "q.t05#0.o1" to "Quali luoghi di interesse ci sono lungo il percorso",
    "q.t05#0.o2" to "In quale rifugio dormire",
    "q.t05#0.o3" to "Che foto fare",
    "q.t05#0.e" to "Prima si traccia la linea del «massimo che si può camminare in un giorno», poi ci si mette dentro il percorso. Facendo il contrario si costruiscono itinerari impossibili, e poi si è costretti a camminare di notte.",

    "q.t05#1.p" to "A cosa servono i giorni di riserva?",
    "q.t05#1.o0" to "A non dover comprimere tutto in marce notturne quando meteo o infortuni causano ritardi",
    "q.t05#1.o1" to "A dormire un po' di più",
    "q.t05#1.o2" to "A lasciare tempo per le fotografie",
    "q.t05#1.o3" to "A nulla di concreto",
    "q.t05#1.e" to "Su un itinerario di più giorni i ritardi arrivano quasi sempre. Con un giorno di riserva il ritardo significa solo saltare una tappa; senza, diventa camminare di notte o forzare un tratto pericoloso.",

    "q.t05#2.p" to "Quali tempi si sottostimano più spesso?",
    "q.t05#2.o0" to "Cercare la via e correggere gli errori",
    "q.t05#2.o1" to "Prendere e filtrare l'acqua",
    "q.t05#2.o2" to "Montare il campo, cucinare, rimettere tutto",
    "q.t05#2.o3" to "Camminare in piano",
    "q.t05#2.e" to "La distanza sulla carta corrisponde solo alla voce «camminare». In una giornata reale ci sono anche ricerca della via, acqua, tenda, cucina e chiusura dello zaino: in genere 1,5–2 ore in più.",

    "q.t05#3.p" to "Con quale densità conviene mettere i punti di uscita?",
    "q.t05#3.o0" to "Almeno un bivio o un paese raggiungibile ogni giorno",
    "q.t05#3.o1" to "Uno solo per tutto l'itinerario",
    "q.t05#3.o2" to "Non servono",
    "q.t05#3.o3" to "Uno ogni cinque giorni",
    "q.t05#3.e" to "Punti di uscita troppo radi equivalgono a scrivere nel piano «devo finire per forza». Solo sapendo, per ogni tratto, dov'è la discesa più vicina si ha una vera possibilità di scelta.",

    "q.t05#4.p" to "Perché non conviene mettere la giornata più lunga il primo giorno?",
    "q.t05#4.o0" to "Il primo giorno si è nelle condizioni e nella lucidità peggiori, senza adattamento a carico e quota",
    "q.t05#4.o1" to "Il primo giorno il panorama è brutto",
    "q.t05#4.o2" to "Il primo giorno di solito piove",
    "q.t05#4.o3" to "Non fa differenza",
    "q.t05#4.e" to "Il corpo ha bisogno di uno o due giorni: spalle e schiena si adattano al carico, i piedi alle scarpe, la persona al ritmo. Mettere la giornata più difficile a metà percorso aumenta le probabilità di riuscita e riduce gli infortuni.",

    "q.t05#5.p" to "Se in tabella c'è scritto «arrivo previsto in 6 ore», cosa va aggiunto?",
    "q.t05#5.o0" to "L'ora limite di arrivo, oltre la quale si applica l'alternativa",
    "q.t05#5.o1" to "La temperatura prevista",
    "q.t05#5.o2" to "Il telefono dei compagni",
    "q.t05#5.o3" to "Niente",
    "q.t05#5.e" to "Il tempo previsto è un'aspettativa, l'ora limite è una linea di decisione. Superata l'ora limite senza essere arrivati, si usa il campo di riserva o si torna indietro, invece di continuare a scommettere.",

    "q.t05#6.p" to "Perché un itinerario di più giorni deve prevedere giorni di riserva?",
    "q.t05#6.o0" to "Meteo, infortuni e ritardi nei trasporti mangiano tempo: senza riserva si comprime il margine di sicurezza",
    "q.t05#6.o1" to "Per riposare",
    "q.t05#6.o2" to "Per le fotografie",
    "q.t05#6.o3" to "Per risparmiare",
    "q.t05#6.e" to "Il giorno di riserva è «parte del piano». Considerarlo uno spreco significa che alla fine a essere compressi saranno riposo e sicurezza.",

    "q.t05#7.p" to "In un itinerario di più giorni, a che ora conviene consigliare l'arrivo al campo?",
    "q.t05#7.o0" to "Lasciando 1–2 ore di luce per montare il campo e cucinare",
    "q.t05#7.o1" to "All'ultimo momento prima del buio",
    "q.t05#7.o2" to "Più tardi è, più fresco è",
    "q.t05#7.o3" to "Non importa",
    "q.t05#7.e" to "Montare il campo al buio è inefficientissimo e fa trascurare i pericoli della piazzola. Scrivere l'«ora di arrivo al campo» nell'itinerario è una forma di disciplina.",

    // ---------- t06 Scelta e montaggio del campo ----------
    "q.t06#0.p" to "A che distanza dall'acqua si consiglia di mettere il campo?",
    "q.t06#0.o0" to "5 m",
    "q.t06#0.o1" to "60 m",
    "q.t06#0.o2" to "200 m",
    "q.t06#0.o3" to "Più vicino è, meglio è",
    "q.t06#0.e" to "60 m è il minimo richiesto da quasi tutte le aree protette. Più vicino si inquina la fonte e si finisce sulla strada che gli animali percorrono di notte. Anche lavarsi e lavare i piatti va fatto ad almeno 60 m dall'acqua.",

    "q.t06#1.p" to "Quali posizioni vanno evitate nello scegliere il campo?",
    "q.t06#1.o0" to "La zona di caduta sassi subito sotto un pendio ripido",
    "q.t06#1.o1" to "Il letto asciutto di un torrente",
    "q.t06#1.o2" to "Sotto un grande albero isolato",
    "q.t06#1.o3" to "Il punto in cui passa una pista di animali",
    "q.t06#1.e" to "Sono quattro posizioni «tranquille finché va bene, gravi quando va male»: caduta sassi, piena, fulmine, animali. Il campo è il luogo dove si resta fermi tutta la notte, e su questi rischi non c'è margine.",

    "q.t06#2.p" to "Perché si consiglia una leggera pendenza per il campo?",
    "q.t06#2.o0" to "Favorisce il drenaggio ed evita ristagni quando piove",
    "q.t06#2.o1" to "Si dorme meglio",
    "q.t06#2.o2" to "È più ordinato",
    "q.t06#2.o3" to "Evita che la tenda si deformi",
    "q.t06#2.e" to "Un piano perfettamente livellato con un temporale si allaga. Un 2–3° di pendenza fa scorrere l'acqua e, dormendo con la testa più in alto, non si scivola verso il fondo.",

    "q.t06#3.p" to "Come si orienta la tenda per essere più stabile?",
    "q.t06#3.o0" to "Ingresso sottovento, lato lungo sopravvento",
    "q.t06#3.o1" to "Ingresso sopravvento",
    "q.t06#3.o2" to "Come capita",
    "q.t06#3.o3" to "Verso il sole",
    "q.t06#3.e" to "Con l'ingresso sottovento non entra vento quando si apre, e neanche la pioggia. Con il lato lungo sopravvento la superficie esposta è minima e i pali lavorano in modo più uniforme.",

    "q.t06#4.p" to "Perché non si monta il campo su una cresta?",
    "q.t06#4.o0" to "C'è molto vento e il rischio di fulmini è alto",
    "q.t06#4.o1" to "Il panorama è troppo aperto",
    "q.t06#4.o2" to "Il terreno è troppo duro",
    "q.t06#4.o3" to "È troppo vicino all'acqua",
    "q.t06#4.e" to "La cresta è il punto più alto del terreno: il vento non trova ostacoli e con i temporali è il luogo più esposto ai fulmini. Il campo va arretrato sul lato sottovento, un po' più in basso.",

    "q.t06#5.p" to "Cosa si fa dopo aver smontato il campo?",
    "q.t06#5.o0" to "Ripristinare il terreno, portare via tutti i rifiuti e controllare che non resti nulla",
    "q.t06#5.o1" to "Andarsene",
    "q.t06#5.o2" to "Seppellire i rifiuti nel terreno",
    "q.t06#5.o3" to "Lasciare la legna per il prossimo",
    "q.t06#5.e" to "Il campo è un posto che useranno anche altri. Controllare picchetti, imballaggi e briciole e recuperare il più possibile l'erba calpestata è il minimo di cortesia.",

    // ---------- t07 Cucina e piano alimentare ----------
    "q.t07#0.p" to "Come si stima a grandi linee il consumo di combustibile?",
    "q.t07#0.o0" to "30–50 g di gas per persona al giorno",
    "q.t07#0.o1" to "200 g per persona al giorno",
    "q.t07#0.o2" to "50 g per squadra al giorno",
    "q.t07#0.o3" to "Non serve stimarlo",
    "q.t07#0.e" to "Su un itinerario normale, in cui si scalda soprattutto acqua, 30–50 g per persona al giorno sono prudenti. Con freddo, neve da sciogliere e molta cucina bisogna salire, e meglio portare una cartuccia di riserva.",

    "q.t07#1.p" to "Quali caratteristiche vanno privilegiate nel piano alimentare?",
    "q.t07#1.o0" to "Alta densità energetica",
    "q.t07#1.o1" to "Facile conservazione, che non si deteriori",
    "q.t07#1.o2" to "Poco da lavare e poco da strofinare in pentola",
    "q.t07#1.o3" to "Lunga cottura in pentola",
    "q.t07#1.e" to "Nello zaino ogni grammo costa fatica, in pentola ogni minuto costa combustibile. Cibi liofilizzati, frutta secca, fiocchi d'avena e pane, cioè «basta aggiungere acqua», sono i più convenienti.",

    "q.t07#2.p" to "Perché in quota si preferiscono i carboidrati?",
    "q.t07#2.o0" to "Consumano meno ossigeno nella digestione e si trasformano in fretta in energia disponibile",
    "q.t07#2.o1" to "Costano meno",
    "q.t07#2.o2" to "Pesano meno",
    "q.t07#2.o3" to "Non fa differenza",
    "q.t07#2.e" to "I grassi hanno più calorie per grammo, ma il loro metabolismo richiede più ossigeno. In carenza di ossigeno i carboidrati sono il combustibile che «consuma meno ossigeno».",

    "q.t07#3.p" to "Usando il fornello in tenda, qual è l'avvertenza più importante?",
    "q.t07#3.o0" to "Mantenere la ventilazione, per evitare l'intossicazione da monossido di carbonio",
    "q.t07#3.o1" to "Tenere la fiamma bassa",
    "q.t07#3.o2" to "Non parlare",
    "q.t07#3.o3" to "Accendere prima una candela per scaldare",
    "q.t07#3.e" to "I sintomi iniziali del monossido (mal di testa, sonnolenza) sono quasi indistinguibili dal mal di montagna e dalla stanchezza, e spesso l'incidente avviene mentre si dorme. La tenda deve avere un foro di ventilazione.",

    "q.t07#4.p" to "Dopo aver preso acqua in natura, qual è il trattamento più affidabile?",
    "q.t07#4.o0" to "Bollire per 1 minuto",
    "q.t07#4.o1" to "Filtrare con un panno",
    "q.t07#4.o2" to "Lasciar decantare",
    "q.t07#4.o3" to "Aggiungere zucchero",
    "q.t07#4.e" to "L'ebollizione uccide batteri, virus e parassiti. I filtri sono limitati sui virus e le pastiglie chimiche richiedono tempo di attesa. In quota l'acqua bolle a temperatura più bassa, quindi il tempo di ebollizione va allungato.",

    "q.t07#5.p" to "Qual è il modo migliore di preparare le razioni?",
    "q.t07#5.o0" to "Confezionarle per giorno con la data, così non si fruga in tutto il sacco",
    "q.t07#5.o1" to "Versare tutto in un unico sacco",
    "q.t07#5.o2" to "Mettere le confezioni originali nello zaino",
    "q.t07#5.o3" to "Dividere per gusti",
    "q.t07#5.e" to "Le razioni per giorno controllano il ritmo dei consumi ed evitano «si mangia troppo all'inizio e non basta alla fine». La data serve anche a sapere quale sacchetto aprire prima.",

    // ---------- t08 Introduzione al comportamento con il meteo ----------
    "q.t08#0.p" to "Quali sono le tre informazioni meteo più importanti prima di partire?",
    "q.t08#0.o0" to "Tendenza sulle 24–48 ore, probabilità di precipitazioni, vento e temperatura percepita",
    "q.t08#0.o1" to "La massima del giorno",
    "q.t08#0.o2" to "Il meteo di ieri",
    "q.t08#0.o3" to "L'umidità dell'aria",
    "q.t08#0.e" to "Sapere solo «quanti gradi ci sono oggi» dice poco. La tendenza dice se cambiare programma, la probabilità di pioggia dice cosa portare, il vento dice la temperatura percepita e se si riesce a stare in piedi allo scoperto.",

    "q.t08#1.p" to "Un cumulonembo con la sommità che si allarga a incudine indica cosa?",
    "q.t08#1.o0" to "Che il temporale è maturo, con possibili precipitazioni intense, grandine e fulmini",
    "q.t08#1.o1" to "Che il tempo sta per migliorare",
    "q.t08#1.o2" to "Che sono solo nubi alte, senza conseguenze",
    "q.t08#1.o3" to "Che sta per nevicare",
    "q.t08#1.e" to "L'incudine indica che la corrente ascensionale ha raggiunto la tropopausa e la nube è nella fase più intensa. Bisogna lasciare al più presto creste, terreno aperto e alberi isolati.",

    "q.t08#2.p" to "Quali segnali possono precedere l'arrivo di un temporale?",
    "q.t08#2.o0" to "Tuoni in lontananza",
    "q.t08#2.o1" to "Base delle nuvole che scurisce e si abbassa",
    "q.t08#2.o2" to "Vento che gira all'improvviso e temperatura che cala di colpo",
    "q.t08#2.o3" to "Capelli che si rizzano e pelle che formicola",
    "q.t08#2.e" to "L'ultimo è il segnale di una carica già forte, quindi di un fulmine possibile molto vicino: bisogna abbassare la quota e accovacciarsi con i piedi uniti, mai sdraiarsi.",

    "q.t08#3.p" to "Con un temporale in corso, quale comportamento è corretto?",
    "q.t08#3.o0" to "Lasciare creste e alberi isolati, abbassare la quota e tenere circa 50 m fra le persone",
    "q.t08#3.o1" to "Ripararsi sotto l'albero più alto",
    "q.t08#3.o2" to "Continuare a correre lungo la cresta",
    "q.t08#3.o3" to "Stringersi tutti insieme per scaldarsi",
    "q.t08#3.e" to "Il fulmine colpisce preferibilmente il punto più alto. Distribuirsi serve a far sì che, se uno viene colpito, gli altri possano soccorrerlo: stringersi trasforma un fulmine in più feriti.",

    "q.t08#4.p" to "Qual è il segno più precoce e affidabile di ipotermia?",
    "q.t08#4.o0" to "Brividi continui, movimenti impacciati, parole impastate",
    "q.t08#4.o1" to "Pelle arrossata",
    "q.t08#4.o2" to "Sudorazione abbondante",
    "q.t08#4.o3" to "Battito rallentato",
    "q.t08#4.e" to "I brividi sono il tentativo del corpo di produrre calore. La scomparsa dei brividi non è un miglioramento, ma possibile segno di peggioramento. Ordine di intervento: riparo dal vento, abiti asciutti, isolamento, bevande calde.",

    "q.t08#5.p" to "A parità di temperatura, perché con il vento si sente più freddo?",
    "q.t08#5.o0" to "Il vento accelera la perdita di calore dalla pelle: la temperatura percepita è molto più bassa di quella dell'aria",
    "q.t08#5.o1" to "Il vento spinge aria fredda dentro i vestiti",
    "q.t08#5.o2" to "È un effetto psicologico",
    "q.t08#5.o3" to "Per l'umidità",
    "q.t08#5.e" to "È l'effetto del raffreddamento da vento. Con 0 °C e 40 km/h la temperatura percepita è vicina a −10 °C. Per decidere come vestirsi bisogna guardare la temperatura percepita, non il numero dell'aria.",

    // ---------- t15 Carta e navigazione pratica ----------
    "q.t15#0.p" to "Prima di entrare in montagna, qual è la cosa più importante da fare con la mappa del telefono?",
    "q.t15#0.o0" to "Scaricare le mappe offline e verificare che il posizionamento funzioni senza rete",
    "q.t15#0.o1" to "Svuotare la cache",
    "q.t15#0.o2" to "Passare al tema scuro",
    "q.t15#0.o3" to "Attivare il risparmio energetico",
    "q.t15#0.e" to "Mappa offline più traccia offline è l'unica soluzione che funziona quando «c'è batteria ma non c'è segnale».",

    "q.t15#1.p" to "Su una carta 1:50.000, 2 centimetri corrispondono a quanti metri sul terreno?",
    "q.t15#1.o0" to "1.000 metri",
    "q.t15#1.o1" to "100 metri",
    "q.t15#1.o2" to "500 metri",
    "q.t15#1.o3" to "2.000 metri",
    "q.t15#1.e" to "1 centimetro = 500 metri, quindi 2 centimetri = 1.000 metri. Sbagliando la scala, tutto il resto è sbagliato.",

    "q.t15#2.p" to "Più le curve di livello sono ravvicinate, cosa indica?",
    "q.t15#2.o0" to "Che il pendio è più ripido",
    "q.t15#2.o1" to "Che il pendio è più dolce",
    "q.t15#2.o2" to "Che la quota è più alta",
    "q.t15#2.o3" to "Che il sentiero è più largo",
    "q.t15#2.e" to "La vicinanza indica un dislivello maggiore nella stessa distanza orizzontale. È così che si capisce «se questo tratto sarà faticoso».",

    "q.t15#3.p" to "Per orientarsi sul terreno, qual è il metodo più affidabile e indipendente dall'elettronica?",
    "q.t15#3.o0" to "Bussola più carta",
    "q.t15#3.o1" to "Guardare come crescono gli alberi",
    "q.t15#3.o2" to "Guardare la direzione delle nuvole",
    "q.t15#3.o3" to "Andare a sensazione",
    "q.t15#3.e" to "La vegetazione e le nuvole danno solo indicazioni accessorie, con errori molto grandi. Bussola e carta sono l'unica combinazione stabile.",

    "q.t15#4.p" to "Accorgendosi di aver forse sbagliato strada, cosa si fa per primo?",
    "q.t15#4.o0" to "Fermarsi e riguardare tre riferimenti evidenti per confermare la posizione",
    "q.t15#4.o1" to "Continuare ad avanzare cercando la via",
    "q.t15#4.o2" to "Accelerare per recuperare",
    "q.t15#4.o3" to "Telefonare a un amico",
    "q.t15#4.e" to "Fermarsi e riguardare è l'unico modo per trasformare «mi sembra di aver sbagliato» in «ho sbagliato». Continuare non fa che aumentare l'errore.",

    "q.t15#5.p" to "Cosa va preparato in anticipo nel pacchetto di navigazione offline?",
    "q.t15#5.o0" to "Le mappe offline",
    "q.t15#5.o1" to "La traccia dell'itinerario (GPX)",
    "q.t15#5.o2" to "Una fonte di energia di riserva",
    "q.t15#5.o3" to "I social network",
    "q.t15#5.e" to "Le prime tre garantiscono «funziona anche senza segnale». I social, in montagna, non hanno rete e non aiutano.",

    "q.t15#6.p" to "Metti in ordine una verifica di posizione.",
    "q.t15#6.o0" to "Aprire la mappa offline e localizzare la posizione attuale",
    "q.t15#6.o1" to "Confrontare con il terreno per confermare il versante e la forma delle curve di livello",
    "q.t15#6.o2" to "Individuare il prossimo riferimento evidente",
    "q.t15#6.o3" to "Confermare la direzione di marcia e la distanza residua",
    "q.t15#6.e" to "Localizzarsi non è «guardare il puntino blu», ma «far coincidere il puntino con il terreno». Il secondo passo è quello decisivo.",

    "q.t15#7.p" to "Un compagno dice «seguiamo la gente, non può essere sbagliato». Qual è la risposta più sensata?",
    "q.t15#7.o0" to "La gente può andare altrove: prima si verifica l'itinerario, poi si segue",
    "q.t15#7.o1" to "Seguire è la cosa più semplice",
    "q.t15#7.o2" to "Con molta gente è per forza sicuro",
    "q.t15#7.o3" to "Basta chiedere",
    "q.t15#7.e" to "Al bivio «la gente» sta spesso percorrendo un'altra linea. Controllare la carta costa dieci secondi.",
    // ---------- t09 Mal di montagna e ritmo di salita ----------
    "q.t09#0.p" to "Sopra i 3.000 m, a quale velocità si consiglia di salire con la quota di sonno?",
    "q.t09#0.o0" to "Entro 500 m al giorno",
    "q.t09#0.o1" to "1.000 m al giorno",
    "q.t09#0.o2" to "1.500 m al giorno",
    "q.t09#0.o3" to "Senza limiti",
    "q.t09#0.e" to "«Salire in alto, dormire in basso» è la strategia più usata: di giorno si può arrivare più in alto, ma la quota di sonno non dovrebbe crescere più di 500 m al giorno. Salire troppo in fretta è la causa principale di AMS.",

    "q.t09#1.p" to "Qual è il gruppo di segni più tipico del mal acuto di montagna (AMS)?",
    "q.t09#1.o0" to "Mal di testa, con nausea o inappetenza, più vertigini e debolezza",
    "q.t09#1.o1" to "Dolori articolari ed eruzioni cutanee",
    "q.t09#1.o2" to "Tosse persistente con sangue",
    "q.t09#1.o3" to "Febbre a 39 °C",
    "q.t09#1.e" to "I tre elementi contano insieme: il solo mal di testa può venire da disidratazione o stanchezza, ma con inappetenza e debolezza somiglia molto di più a un AMS.",

    "q.t09#2.p" to "Compaiono sintomi di AMS: qual è la gestione corretta?",
    "q.t09#2.o0" to "Fermare la salita, aclimatarsi sul posto o scendere",
    "q.t09#2.o1" to "Prendere un farmaco e proseguire secondo il piano",
    "q.t09#2.o2" to "Bere di più e continuare, passerà",
    "q.t09#2.o3" to "Accelerare fino al campo e riposare lì",
    "q.t09#2.e" to "Il principio centrale è «non salire con i sintomi». Se sono lievi e le condizioni lo permettono si resta un giorno in più sul posto; se peggiorano bisogna scendere.",

    "q.t09#3.p" to "Quali sono i segnali di pericolo che impongono di scendere subito?",
    "q.t09#3.o0" to "Dispnea anche a riposo",
    "q.t09#3.o1" to "Andatura instabile, come se si fosse ubriachi",
    "q.t09#3.o2" to "Confusione o comportamento anomalo",
    "q.t09#3.o3" to "Un leggero mal di testa",
    "q.t09#3.e" to "I primi tre fanno sospettare un HAPE o un HACE già in corso. La direzione è una sola: scendere, somministrando ossigeno e chiedendo supporto medico.",

    "q.t09#4.p" to "Perché si consiglia di «dormire più in basso»?",
    "q.t09#4.o0" to "Di notte il respiro diventa più superficiale e l'ipossia è massima: dormire più in basso riduce la carenza notturna",
    "q.t09#4.o1" to "In basso c'è più silenzio",
    "q.t09#4.o2" to "In basso fa più caldo",
    "q.t09#4.o3" to "In basso il panorama è migliore",
    "q.t09#4.e" to "Durante il sonno la ventilazione cala e la saturazione scende sotto i valori della veglia. Mettere il campo qualche centinaio di metri sotto il punto più alto della giornata è un margine che si lascia al proprio io notturno.",

    "q.t09#5.p" to "Chi è più in forma è anche meno soggetto al mal di montagna?",
    "q.t09#5.o0" to "Non necessariamente: contano soprattutto la velocità di salita e le differenze individuali",
    "q.t09#5.o1" to "Sì, più si è in forma più si è al sicuro",
    "q.t09#5.o2" to "No, più si è in forma più si sta male",
    "q.t09#5.o3" to "Dipende solo dall'età",
    "q.t09#5.e" to "Chi è molto allenato spesso cammina più veloce e sale più in alto, e proprio per questo sta peggio. Tenere separati forma fisica e capacità di aclimatazione è essenziale in quota.",

    // ---------- t10 Caldo e protezione solare in quota ----------
    "q.t10#0.p" to "Il sistema di vestiario per un trekking d'alta quota si divide di solito in quante parti?",
    "q.t10#0.o0" to "Strato che smaltisce il sudore, strato caldo, strato antivento",
    "q.t10#0.o1" to "Intimo e giacca",
    "q.t10#0.o2" to "Cotone, lana, cerata",
    "q.t10#0.o3" to "Più strati ci sono, meglio è",
    "q.t10#0.e" to "La stratificazione non serve a «portare di più», ma a poter regolare in ogni momento. Si toglie lo strato esterno quando si suda e lo si rimette appena ci si ferma: il raffreddamento avviene spesso proprio nei dieci minuti di sosta.",

    "q.t10#1.p" to "Ogni 1.000 m di quota, di quanto aumenta circa l'intensità degli ultravioletti?",
    "q.t10#1.o0" to "10–12 %",
    "q.t10#1.o1" to "2 %",
    "q.t10#1.o2" to "50 %",
    "q.t10#1.o3" to "Non cambia",
    "q.t10#1.e" to "L'aria è più sottile e filtra meno gli ultravioletti. Aggiungendo il riflesso della neve, circa l'80 %, l'esposizione reale di viso e naso equivale quasi a «prendere due volte il sole».",

    "q.t10#2.p" to "Cosa deve comprendere la protezione solare in quota?",
    "q.t10#2.o0" to "Occhiali UV400",
    "q.t10#2.o1" to "Crema SPF50+, riapplicata ogni 2–3 ore",
    "q.t10#2.o2" to "Burrocacao con filtro solare",
    "q.t10#2.o3" to "Cappello a tesa o bandana",
    "q.t10#2.e" to "I quattro oggetti coprono quattro zone: occhi, pelle, labbra, viso. Le labbra non hanno melanina a proteggerle, sono le prime a screpolarsi e le più trascurate.",

    "q.t10#3.p" to "Perché mani e piedi sono i primi a raffreddarsi?",
    "q.t10#3.o0" to "Il corpo dà priorità alla temperatura centrale e restringe i vasi delle estremità",
    "q.t10#3.o1" to "Hanno poca ciccia",
    "q.t10#3.o2" to "Si muovono poco",
    "q.t10#3.o3" to "È un effetto psicologico",
    "q.t10#3.e" to "È un normale meccanismo di difesa. Per questo il riscaldamento va concentrato sul tronco: se il centro è caldo, le estremità ricevono sangue. Aggiungere solo guanti senza scaldare il tronco serve poco.",

    "q.t10#4.p" to "Guanti e calze si sono bagnati: cosa si fa?",
    "q.t10#4.o0" to "Cambiarli subito: uno strato intimo bagnato porta via calore in continuazione",
    "q.t10#4.o1" to "Tenerli, camminando si asciugano",
    "q.t10#4.o2" to "Strizzarli e basta",
    "q.t10#4.o3" to "Cambiarli il giorno dopo",
    "q.t10#4.e" to "Un tessuto bagnato conduce il calore diverse volte più in fretta di uno asciutto. Una volta che mani e piedi si intorpidiscono i movimenti rallentano, e sia manovrare l'attrezzatura sia camminare diventano più soggetti a errore.",

    "q.t10#5.p" to "Che cos'è la cecità da neve?",
    "q.t10#5.o0" to "Una bruciatura ultravioletta della cornea, con dolore intenso, fotofobia e lacrimazione dopo 6–12 ore",
    "q.t10#5.o1" to "Un affaticamento degli occhi per il riflesso della neve",
    "q.t10#5.o2" to "Un congelamento del bulbo oculare",
    "q.t10#5.o3" to "Una carenza di vitamina A",
    "q.t10#5.e" to "La cecità da neve è ritardata: durante il giorno non si sente nulla, il dolore arriva la sera. La prevenzione dipende quasi solo dagli occhiali, che servono anche con cielo coperto e in mezzo alla nebbia di neve.",

    // ---------- t11 Alimentazione e sonno in quota ----------
    "q.t11#0.p" to "Se in quota non si riesce a mangiare, cosa si fa?",
    "q.t11#0.o0" to "Mangiare attivamente, in piccole dosi frequenti, privilegiando i carboidrati",
    "q.t11#0.o1" to "Non mangiare e aspettare che torni l'appetito",
    "q.t11#0.o2" to "Bere solo acqua calda",
    "q.t11#0.o3" to "Tirare avanti con il caffè",
    "q.t11#0.e" to "In quota il deficit energetico rallenta direttamente l'acclimatazione. Spezzare un pasto in più piccoli spuntini è molto più fattibile che obbligarsi a finire un piatto intero.",

    "q.t11#1.p" to "Qual è l'indicatore più semplice per capire se si beve abbastanza?",
    "q.t11#1.o0" to "Il colore delle urine, che deve restare giallo chiaro",
    "q.t11#1.o1" to "Bere 3 litri al giorno",
    "q.t11#1.o2" to "Non avere sete",
    "q.t11#1.o3" to "Il peso che non cambia",
    "q.t11#1.e" to "Il colore delle urine è l'indicatore di idratazione più diretto. Giallo scuro significa già poco; del tutto trasparente può voler dire troppo, e in quel caso servono un po' di elettroliti.",

    "q.t11#2.p" to "Qual è la causa più frequente di sonno cattivo in quota?",
    "q.t11#2.o0" to "Il respiro periodico dovuto all'ipossia, che sveglia ripetutamente dal sonno leggero",
    "q.t11#2.o1" to "La tenda scomoda",
    "q.t11#2.o2" to "Troppo silenzio",
    "q.t11#2.o3" to "Aver camminato poco di giorno",
    "q.t11#2.e" to "È un fenomeno fisiologico: non vale la pena angosciarsi per «non aver dormito otto ore». Ciò che va preso sul serio è l'insonnia accompagnata da mal di testa e nausea, che può essere AMS.",

    "q.t11#3.p" to "Quali abitudini aiutano a dormire meglio in quota?",
    "q.t11#3.o0" to "Non cenare troppo abbondante",
    "q.t11#3.o1" to "Non bere alcol",
    "q.t11#3.o2" to "Bere un po' d'acqua prima di dormire",
    "q.t11#3.o3" to "Usare acetazolamide sotto indicazione medica",
    "q.t11#3.e" to "Le prime tre si possono gestire da soli, l'ultima richiede la valutazione di un medico. L'uso di un farmaco è una decisione medica e non va consigliato tra compagni.",

    "q.t11#4.p" to "Perché in quota l'alcol è più pericoloso del normale?",
    "q.t11#4.o0" to "Deprime la respirazione, aggrava l'ipossia e maschera i sintomi dell'AMS",
    "q.t11#4.o1" to "Disidrata",
    "q.t11#4.o2" to "Impedisce di dormire",
    "q.t11#4.o3" to "Ha troppe calorie",
    "q.t11#4.e" to "In quota lo stimolo respiratorio è già indebolito e l'alcol lo deprime ancora. Il problema maggiore è che l'aspetto da ubriaco somiglia molto a un HACE iniziale, e si sbaglia la valutazione.",

    "q.t11#5.p" to "La caffeina si può usare in quota?",
    "q.t11#5.o0" to "Con moderazione, ma non al posto di riposo e idratazione",
    "q.t11#5.o1" to "Del tutto no",
    "q.t11#5.o2" to "Più se ne prende, meglio è",
    "q.t11#5.o3" to "Solo al mattino",
    "q.t11#5.e" to "Un caffè non provoca il mal di montagna e non cura la stanchezza. Può aiutare un po' sul mal di testa, ma usarlo per resistere sposta solo il problema più avanti.",

    // ---------- t12 Squadra e preparazione psicologica ----------
    "q.t12#0.p" to "Qual è la preparazione psicologica più importante prima di partire?",
    "q.t12#0.o0" to "Accettare che «forse non si arriva», considerando la rinuncia come parte del piano",
    "q.t12#0.o1" to "Decidere di non mollare mai",
    "q.t12#0.o2" to "Scriversi l'obiettivo sul dorso della mano",
    "q.t12#0.o3" to "Non dire alla famiglia dove si va",
    "q.t12#0.e" to "Solo scrivendo la rinuncia nel piano una persona si ferma quando è il momento. Al contrario, prendere «devo arrivare» come obiettivo porta a ignorare i segnali di pericolo pur di arrivare.",

    "q.t12#1.p" to "Ci si accorge di non reggere il ritmo della squadra: qual è la cosa migliore?",
    "q.t12#1.o0" to "Dirlo con sincerità e chiedere che la squadra cammini al passo del più lento",
    "q.t12#1.o1" to "Stringere i denti per non rallentare gli altri",
    "q.t12#1.o2" to "Restare indietro in silenzio",
    "q.t12#1.o3" to "Scendere da soli senza avvisare",
    "q.t12#1.e" to "Forzare porta all'esaurimento in poche ore, e poi si sbaglia o ci si fa male più facilmente. Camminare al passo del più lento è efficienza oltre che sicurezza.",

    "q.t12#2.p" to "Quali metodi aiutano davanti all'esposizione e alla paura del vuoto?",
    "q.t12#2.o0" to "Guardare a tratti dove si mettono i piedi, senza fissare la distanza",
    "q.t12#2.o1" to "Rallentare il respiro e portare l'attenzione sul gesto",
    "q.t12#2.o2" to "Mantenere tre punti di appoggio, con movimenti piccoli",
    "q.t12#2.o3" to "Chiudere gli occhi e passare in fretta",
    "q.t12#2.e" to "La paura rende il respiro corto e i movimenti rigidi, e la rigidità è proprio la fonte degli errori. Riportare l'attenzione al «prossimo appoggio» è il modo più efficace.",

    "q.t12#3.p" to "Dove sta il problema nel pensiero «siamo già arrivati fin qui, non possiamo tornare a mani vuote»?",
    "q.t12#3.o0" to "Prende il tempo già speso come ragione per continuare a rischiare",
    "q.t12#3.o1" to "È poco propositivo",
    "q.t12#3.o2" to "Fa camminare troppo piano",
    "q.t12#3.o3" to "Non c'è nessun problema",
    "q.t12#3.e" to "Il tempo già speso non torna continuando, ma continuare può portare a un costo nuovo e irreversibile. Il giudizio guarda avanti, non indietro.",

    "q.t12#4.p" to "Cosa deve concordare la squadra prima di partire?",
    "q.t12#4.o0" to "Chi ha il diritto di fermare il gruppo, il punto di ritrovo in caso di separazione, dopo quanto tempo scatta il protocollo",
    "q.t12#4.o1" to "Chi fa le fotografie",
    "q.t12#4.o2" to "Chi cammina più veloce",
    "q.t12#4.o3" to "Chi porta più peso",
    "q.t12#4.e" to "Trasformare «fermare il gruppo» in un permesso concesso prima, e non in un atto di coraggio personale, è ciò che permette di parlare quando è il momento. Vale lo stesso per punto di ritrovo e protocollo.",

    "q.t12#5.p" to "Umore che crolla all'improvviso, voglia di non parlare, movimenti rallentati: a cosa si pensa per primo?",
    "q.t12#5.o0" to "A una carenza di energia o di acqua, oppure a un esordio di mal di montagna o ipotermia",
    "q.t12#5.o1" to "A un semplice cattivo umore",
    "q.t12#5.o2" to "A un problema di carattere",
    "q.t12#5.o3" to "Al bisogno di stare un po' da solo",
    "q.t12#5.e" to "All'aperto i cambi di umore sono spesso la prima faccia di un problema fisiologico. Prima si dà da mangiare, da bere, uno strato in più e si valuta lo stato; poi si parla di umore.",

    // ---------- t13 Pianificazione di lunga percorrenza e rifornimenti ----------
    "q.t13#0.p" to "Con quale densità si consiglia di mettere i punti di rifornimento su un lungo itinerario?",
    "q.t13#0.o0" to "Uno ogni 3–5 giorni",
    "q.t13#0.o1" to "Uno per tutto il percorso",
    "q.t13#0.o2" to "Uno al giorno",
    "q.t13#0.o3" to "Non servono rifornimenti",
    "q.t13#0.e" to "I punti di rifornimento spezzano il lungo itinerario in tratte valutabili e abbandonabili singolarmente. Con intervalli troppo lunghi, un solo ritardo dovuto al meteo si ripercuote su tutta la linea.",

    "q.t13#1.p" to "Qual è all'incirca il peso giornaliero di cibo liofilizzato?",
    "q.t13#1.o0" to "600–800 g",
    "q.t13#1.o1" to "200 g",
    "q.t13#1.o2" to "1,5 kg",
    "q.t13#1.o3" to "3 kg",
    "q.t13#1.e" to "600–800 g di piatti liofilizzati al giorno forniscono circa 2.500–3.000 kcal. Aggiungendo frutta secca e bustine d'olio, ad alta densità energetica, il totale sale un po'.",

    "q.t13#2.p" to "Quali norme vanno verificate prima di un lungo itinerario?",
    "q.t13#2.o0" to "Il permesso d'ingresso o dell'area protetta",
    "q.t13#2.o1" to "Se è consentito accendere fuochi all'aperto",
    "q.t13#2.o2" to "Se i rifiuti vanno portati fuori tutti",
    "q.t13#2.o3" to "Se si può far volare un drone",
    "q.t13#2.e" to "Non sono dettagli: entrare senza permesso può significare essere rimandati indietro, un fuoco irregolare in stagione secca provoca facilmente un incendio, e in molte aree protette i droni sono del tutto vietati.",

    "q.t13#3.p" to "Perché portare una parte del denaro in contanti?",
    "q.t13#3.o0" to "I punti di rifornimento, i paesi e i trasporti di montagna spesso accettano solo contanti, e la rete può mancare",
    "q.t13#3.o1" to "Per sembrare professionali",
    "q.t13#3.o2" to "Per livellare il tavolo",
    "q.t13#3.o3" to "Per pesare meglio",
    "q.t13#3.e" to "Più il luogo è remoto, più dipende dal contante. Le banconote di piccolo taglio sono le più utili; una riserva di emergenza va tenuta separata dalle spese quotidiane.",

    "q.t13#4.p" to "Come vanno preparate le comunicazioni di emergenza su un lungo itinerario?",
    "q.t13#4.o0" to "Un dispositivo satellitare o un localizzatore, più una carta su carta e il piano lasciato a un contatto",
    "q.t13#4.o1" to "Solo il telefono",
    "q.t13#4.o2" to "Solo il fischietto",
    "q.t13#4.o3" to "Niente",
    "q.t13#4.e" to "Molti itinerari lunghi non hanno segnale in nessun punto. Il dispositivo manda messaggi, mentre carta e piano permettono a chi resta a casa di sapere dove sei e quando allarmarsi.",

    "q.t13#5.p" to "Lasciare il 20 % di margine nel piano: che cosa significa concretamente?",
    "q.t13#5.o0" to "Cibo, combustibile, tempo e contanti due decimi in più del valore teorico",
    "q.t13#5.o1" to "Portare solo più acqua",
    "q.t13#5.o2" to "Lasciare solo più tempo",
    "q.t13#5.o3" to "Non serve",
    "q.t13#5.e" to "Il margine è lo spazio riservato all'imprevisto. Un giorno di ritardo per il meteo, due pasti in più sul fornello, una spesa di trasporto non prevista: nessuna di queste cose deve mettere subito in difficoltà il viaggio.",

    // ---------- t14 Pronto soccorso e chiamata di soccorso ----------
    "q.t14#0.p" to "Dopo una distorsione alla caviglia, quali sono i principi di trattamento sul posto?",
    "q.t14#0.o0" to "Riposo, ghiaccio o freddo, bendaggio compressivo, sollevamento (RICE)",
    "q.t14#0.o1" to "Caldo e massaggio immediati",
    "q.t14#0.o2" to "Continuare a camminare, tanto si scalda",
    "q.t14#0.o3" to "Massaggiare con forza per sciogliere l'ematoma",
    "q.t14#0.e" to "Nella fase acuta calore e massaggio aumentano sanguinamento e gonfiore. Nelle prime 48 ore si usano freddo, compressione e sollevamento; solo dopo si riprende il movimento in modo graduale.",

    "q.t14#1.p" to "Qual è l'ordine corretto di intervento su una persona in ipotermia?",
    "q.t14#1.o0" to "Riparo dal vento, abiti asciutti, isolamento dal terreno, bevande calde se cosciente, riscaldamento graduale",
    "q.t14#1.o1" to "Prima una bevanda calda, poi cambiare i vestiti",
    "q.t14#1.o2" to "Strofinare mani e piedi per far circolare il sangue",
    "q.t14#1.o3" to "Farla camminare in fretta per produrre calore",
    "q.t14#1.e" to "Prima si blocca la perdita di calore, poi si parla di riscaldamento. Strofinare gli arti o obbligare a camminare può riportare sangue freddo al centro e peggiorare la situazione.",

    "q.t14#2.p" to "Sospettando un colpo di calore, qual è il primo passo?",
    "q.t14#2.o0" to "Portare subito all'ombra in un luogo ventilato, slacciare i vestiti e iniziare il raffreddamento fisico",
    "q.t14#2.o1" to "Far bere molta acqua",
    "q.t14#2.o2" to "Farla continuare a camminare, tanto suderà",
    "q.t14#2.o3" to "Coprirla per evitare che prenda freddo",
    "q.t14#2.e" to "Nel colpo di calore il problema centrale è il fallimento della termoregolazione: prima si raffredda, poi si reidrata. Con coscienza alterata non si fa bere, per evitare l'inalazione.",

    "q.t14#3.p" to "Quali informazioni deve contenere una richiesta di soccorso?",
    "q.t14#3.o0" to "Posizione precisa o coordinate",
    "q.t14#3.o1" to "Numero di persone e condizioni dei feriti",
    "q.t14#3.o2" to "Attrezzatura e rifornimenti disponibili",
    "q.t14#3.o3" to "Contatti e carica residua della batteria",
    "q.t14#3.e" to "Chi soccorre deve sapere per prima cosa «dove, quante persone, quanto gravi, per quanto ancora ce la fanno». Se le informazioni sono incomplete si perdono spesso ore in verifiche.",

    "q.t14#4.p" to "Come va definito il protocollo in caso di mancanza di notizie?",
    "q.t14#4.o0" to "Con orari di controllo fissi: dopo quanto tempo chi chiama chi e quando si allerta il soccorso",
    "q.t14#4.o1" to "Si vede sul momento",
    "q.t14#4.o2" to "Basta dire alla famiglia la zona di massima",
    "q.t14#4.o3" to "Non serve un protocollo",
    "q.t14#4.e" to "Il protocollo deve essere concreto: a che ora, se non ci sono notizie, si telefona; dopo quante ore si contatta il soccorso locale. Un «se serve mi chiami» equivale a nessun protocollo.",

    "q.t14#5.p" to "In quali casi è obbligatorio chiedere soccorso invece di continuare a gestire da soli?",
    "q.t14#5.o0" to "Quando la persona non si può muovere, la coscienza è alterata o la situazione continua a peggiorare",
    "q.t14#5.o1" to "Solo quando si è un po' stanchi",
    "q.t14#5.o2" to "Quando le scarpe fanno male",
    "q.t14#5.o3" to "Quando si è due ore indietro sul programma",
    "q.t14#5.e" to "La soglia va pensata prima: se si cammina, si è coscienti e si sta migliorando, si può scendere da soli; se non si cammina, non si è coscienti o si sta peggiorando, bisogna chiamare il prima possibile.",
    // ---------- t16 Vita al campo e igiene in natura ----------
    "q.t16#0.p" to "Qual è la divisione di base in tre zone di un campo?",
    "q.t16#0.o0" to "Zona notte, zona cucina e latrina, separate",
    "q.t16#0.o1" to "Uomini, donne, comune",
    "q.t16#0.o2" to "Tenda, auto, fuoco",
    "q.t16#0.o3" to "Non serve dividere",
    "q.t16#0.e" to "La divisione risolve tre cose: il rischio di fiamme libere, gli odori che attirano animali e la contaminazione igienica incrociata.",

    "q.t16#1.p" to "Per la buca da latrina, quali profondità e distanza dall'acqua sono ragionevoli?",
    "q.t16#1.o0" to "15–20 centimetri di profondità, ad almeno 60 metri dall'acqua",
    "q.t16#1.o1" to "5 centimetri di profondità, a 5 metri dall'acqua",
    "q.t16#1.o2" to "Più profonda e più lontana è, meglio è",
    "q.t16#1.o3" to "Non serve scavare",
    "q.t16#1.e" to "Troppo poco profonda non decompone, troppo vicina inquina la fonte. 60 metri è la distanza comunemente adottata.",

    "q.t16#2.p" to "Come va gestita la carta igienica?",
    "q.t16#2.o0" to "Messa in un sacchetto e portata via",
    "q.t16#2.o1" to "Bruciata",
    "q.t16#2.o2" to "Interrata nella buca",
    "q.t16#2.o3" to "Lasciata nell'erba",
    "q.t16#2.e" to "Bruciare carta in stagione secca è un rischio d'incendio, e interrarla la fa riemergere con lo scioglimento della neve o con gli animali che scavano. Portarla via è la soluzione più pulita.",

    "q.t16#3.p" to "Come si smaltisce correttamente l'acqua per lavare i piatti?",
    "q.t16#3.o0" to "Filtrare i residui e disperdere l'acqua, portando via i residui",
    "q.t16#3.o1" to "Versarla direttamente nel torrente",
    "q.t16#3.o2" to "Versarla accanto alla tenda",
    "q.t16#3.o3" to "Versarla nella buca da latrina",
    "q.t16#3.e" to "I residui sono inquinamento e richiamo per gli animali: si filtrano e si portano via. L'acqua rimasta si disperde, per non concentrarla in un punto solo.",

    "q.t16#4.p" to "Quali sono le tre cose più importanti per la cura dei piedi durante un trekking?",
    "q.t16#4.o0" to "Lavarsi i piedi ogni giorno, cambiare con calze asciutte, far asciugare le scarpe",
    "q.t16#4.o1" to "Camminare di più",
    "q.t16#4.o2" to "Indossare calze spesse",
    "q.t16#4.o3" to "Mettere una pomata",
    "q.t16#4.e" to "Vesciche e macerazione nascono da «umidità più sfregamento». Tenere asciutto è più efficace di qualsiasi pomata.",

    "q.t16#5.p" to "Quali pratiche vanno evitate per l'igiene del campo?",
    "q.t16#5.o0" to "Mangiare dentro la tenda",
    "q.t16#5.o1" to "Lasciare residui di cibo nel campo",
    "q.t16#5.o2" to "Lavare i piatti vicino all'acqua",
    "q.t16#5.o3" to "Mettere le scarpe nell'abside prima di dormire",
    "q.t16#5.e" to "Le prime tre portano animali e contaminazione nella zona dove si dorme. Le scarpe nell'abside sono una pratica comune, purché prima si scrollino bene.",

    "q.t16#6.p" to "Metti in ordine le operazioni di smontaggio del campo al mattino.",
    "q.t16#6.o0" to "Raccogliere prima il sacco a pelo e metterlo nel sacco impermeabile",
    "q.t16#6.o1" to "Raccogliere oggetti minuti e rifiuti dentro la tenda",
    "q.t16#6.o2" to "Smontare la tenda e scrollare rugiada e brina",
    "q.t16#6.o3" to "Controllare il campo e verificare che non resti nulla",
    "q.t16#6.e" to "L'ultimo passo è il più facile da saltare, ed è la voce più frequente di «perdita di punti» sul principio di non lasciare traccia.",

    "q.t16#7.p" to "Vicino al campo ci sono tracce di animali (escrementi, terreno scavato): cosa si fa?",
    "q.t16#7.o0" to "Appendere il cibo in alto o conservarlo ermeticamente, lontano dalla zona notte",
    "q.t16#7.o1" to "Continuare a cucinare dove si è",
    "q.t16#7.o2" to "Dargli un po' di cibo",
    "q.t16#7.o3" to "Mettere il cibo in tenda",
    "q.t16#7.e" to "Gli animali sono attratti dagli odori. Mettere il cibo in tenda è la cosa più pericolosa: porta l'animale esattamente dove si dorme.",

    // ---------- t17 Disidratazione, colpi di calore e traumi ----------
    "q.t17#0.p" to "Qual è l'indicatore di idratazione più pratico durante un trekking?",
    "q.t17#0.o0" to "Urine di colore giallo chiaro",
    "q.t17#0.o1" to "Il senso di sete",
    "q.t17#0.o2" to "Quanto si suda",
    "q.t17#0.o3" to "Il peso",
    "q.t17#0.e" to "Quando arriva la sete si è già in deficit. Il colore delle urine è il sistema di autoverifica quotidiano più economico.",

    "q.t17#1.p" to "Qual è il criterio centrale per riconoscere un colpo di calore?",
    "q.t17#1.o0" to "Temperatura centrale superiore a 40 °C con alterazione della coscienza",
    "q.t17#1.o1" to "Sudare molto",
    "q.t17#1.o2" to "Pelle arrossata",
    "q.t17#1.o3" to "Battito accelerato",
    "q.t17#1.e" to "L'alterazione della coscienza è il segnale chiave. Se sul posto non c'è un termometro si giudica dallo stato di coscienza e si raffredda subito.",

    "q.t17#2.p" to "Qual è l'ordine corretto di intervento su un colpo di calore?",
    "q.t17#2.o0" to "All'ombra → slacciare i vestiti → raffreddare → reintegrare gli elettroliti",
    "q.t17#2.o1" to "Prima reidratare, poi raffreddare",
    "q.t17#2.o2" to "Prima massaggiare gli arti",
    "q.t17#2.o3" to "Prima far bere",
    "q.t17#2.e" to "Il raffreddamento viene prima. La reidratazione richiede tempo, mentre il danno d'organo da calore è immediato.",

    "q.t17#3.p" to "Dopo una distorsione alla caviglia, nelle prime 48 ore cosa si fa?",
    "q.t17#3.o0" to "Freddo, compressione e sollevamento, evitando calore e massaggi energici",
    "q.t17#3.o1" to "Calore e massaggio",
    "q.t17#3.o2" to "Continuare a camminare",
    "q.t17#3.o3" to "Massaggiare con forza per sciogliere l'ematoma",
    "q.t17#3.e" to "Nella fase acuta calore e sfregamento aumentano sanguinamento e gonfiore. I quattro passi del RICE non si possono saltare.",

    "q.t17#4.p" to "Se la persona colpita da calore è incosciente, cosa si fa?",
    "q.t17#4.o0" to "Non forzare a bere: applicare impacchi freddi e chiedere aiuto al più presto",
    "q.t17#4.o1" to "Far bere molta acqua",
    "q.t17#4.o2" to "Dare pastiglie di sale",
    "q.t17#4.o3" to "Lasciarla bere da sola",
    "q.t17#4.e" to "Quando il riflesso della deglutizione non è affidabile, far bere provoca inalazione. In quel momento contano solo il raffreddamento e il soccorso professionale.",

    "q.t17#5.p" to "Una vescica impedisce di camminare: qual è il trattamento corretto?",
    "q.t17#5.o0" to "Disinfettare, drenare dal bordo, conservare l'epidermide e coprire con un cerotto",
    "q.t17#5.o1" to "Toglierla del tutto",
    "q.t17#5.o2" to "Bucarla al centro",
    "q.t17#5.o3" to "Non farci nulla",
    "q.t17#5.e" to "L'epidermide è la medicazione migliore. Bucare al centro la lacera facilmente.",

    "q.t17#6.p" to "Quali condizioni aumentano il rischio di colpo di calore in escursione?",
    "q.t17#6.o0" to "Umidità alta e assenza di vento",
    "q.t17#6.o1" to "Salite continue a mezzogiorno",
    "q.t17#6.o2" to "Bere solo acqua naturale senza elettroliti",
    "q.t17#6.o3" to "Indossare abiti chiari e traspiranti",
    "q.t17#6.e" to "Le prime tre indeboliscono la dispersione del calore o l'equilibrio elettrolitico. Gli abiti chiari e traspiranti sono invece una misura di raffreddamento.",

    "q.t17#7.p" to "Cosa non può mancare in una cassetta di primo soccorso da trekking?",
    "q.t17#7.o0" to "Cerotti per vesciche e medicazioni",
    "q.t17#7.o1" to "Analgesici e antipiretici",
    "q.t17#7.o2" to "Benda elastica",
    "q.t17#7.o3" to "Antibiotici",
    "q.t17#7.e" to "I primi tre coprono i problemi più frequenti in escursione: piedi, dolore, distorsioni. Gli antibiotici richiedono la valutazione di un medico.",

    "q.t17#8.p" to "Metti in ordine l'intervento su un esaurimento da calore.",
    "q.t17#8.o0" to "Fermare l'attività e portare all'ombra",
    "q.t17#8.o1" to "Slacciare i vestiti e iniziare il raffreddamento fisico",
    "q.t17#8.o2" to "Reintegrare liquidi con elettroliti",
    "q.t17#8.o3" to "Osservare coscienza e condizioni, chiedendo aiuto se necessario",
    "q.t17#8.e" to "Il senso dell'ordine è «togliere prima l'esposizione al calore». Continuare a camminare porta dall'esaurimento al colpo di calore.",

    "q.t17#9.p" to "Un compagno, salendo a mezzogiorno, ha mal di testa, nausea e pelle fredda e sudata: cosa si fa?",
    "q.t17#9.o0" to "Fermarsi subito, raffreddare, reintegrare elettroliti e osservare",
    "q.t17#9.o1" to "Continuare fino al campo",
    "q.t17#9.o2" to "Dargli un analgesico e proseguire",
    "q.t17#9.o3" to "Fargli mettere più vestiti",
    "q.t17#9.e" to "È il quadro tipico dell'esaurimento da calore. Continuando peggiora rapidamente, e il colpo di calore può essere fatale in poche decine di minuti.",
    // ---------- t18 Valutazione e scelta del punto di guado ----------
    "q.t18#0.p" to "Per decidere se si può guadare, qual è la coppia di grandezze decisive?",
    "q.t18#0.o0" to "Profondità × velocità della corrente",
    "q.t18#0.o1" to "La profondità",
    "q.t18#0.o2" to "La larghezza del fiume",
    "q.t18#0.o3" to "La temperatura dell'acqua",
    "q.t18#0.e" to "A parità di profondità, raddoppiando la velocità raddoppia la spinta. Misurare solo la profondità è l'errore di valutazione più comune in escursione.",

    "q.t18#1.p" to "Qual è il limite tecnico di sicurezza per un guado?",
    "q.t18#1.o0" to "Profondità × velocità superiore a 1,0 m²/s è considerato non guadabile",
    "q.t18#1.o1" to "Profondità superiore a 0,5 m",
    "q.t18#1.o2" to "Velocità superiore a 3 m/s",
    "q.t18#1.o3" to "Larghezza superiore a 20 m",
    "q.t18#1.e" to "1,0 vale per adulti in salute, su breve distanza e senza zaino pesante. Una squadra può darsi un limite interno di 0,8, ma è una scelta prudenziale, non lo standard.",

    "q.t18#2.p" to "Usando il rametto per misurare la corrente, qual è il criterio?",
    "q.t18#2.o0" to "Se bisogna trottare per seguirlo, la velocità supera quella del passo",
    "q.t18#2.o1" to "Se il rametto va a fondo",
    "q.t18#2.o2" to "Se il rametto gira",
    "q.t18#2.o3" to "Se la superficie fa schiuma",
    "q.t18#2.e" to "Seguirlo camminando lungo la riva è il metodo più immediato. Doversi mettere a trottare significa che la corrente è già troppo forte.",

    "q.t18#3.p" to "Oltre quale profondità conviene cambiare punto?",
    "q.t18#3.o0" to "Oltre la coscia della persona più bassa della squadra",
    "q.t18#3.o1" to "Oltre la vita del capo",
    "q.t18#3.o2" to "Oltre il ginocchio",
    "q.t18#3.o3" to "Oltre il petto",
    "q.t18#3.e" to "Si calcola sulla persona più bassa, non sul più forte. La squadra è limitata dal più debole: è la regola ferrea del guado.",

    "q.t18#4.p" to "Che cos'è il «run-out»?",
    "q.t18#4.o0" to "La zona a valle dove la corrente porterebbe una persona che perde l'appoggio",
    "q.t18#4.o1" to "La sponda ripida",
    "q.t18#4.o2" to "La pendenza dell'alveo",
    "q.t18#4.o3" to "Il bacino a monte",
    "q.t18#4.e" to "Se nel run-out ci sono cascate, tronchi caduti o sponde ripide, quel punto non si usa, anche se l'acqua davanti sembra bassa.",

    "q.t18#5.p" to "Nello scegliere il punto di guado, cosa si cerca per primo?",
    "q.t18#5.o0" to "Un tratto largo e poco profondo",
    "q.t18#5.o1" to "Un tratto stretto e profondo",
    "q.t18#5.o2" to "L'esterno di una curva",
    "q.t18#5.o3" to "Vicino a un tronco caduto",
    "q.t18#5.e" to "Più il fiume è largo, di solito più è basso e lento; l'esterno della curva è profondo e veloce, e un tronco è un punto di intrappolamento mortale.",

    "q.t18#6.p" to "Quanta crescita del livello basta a rendere pericoloso un punto prima sicuro?",
    "q.t18#6.o0" to "15 centimetri",
    "q.t18#6.o1" to "1 metro",
    "q.t18#6.o2" to "50 centimetri",
    "q.t18#6.o3" to "Una variazione così piccola non conta",
    "q.t18#6.e" to "15 centimetri cambiano già in modo netto velocità e profondità, soprattutto nei torrenti di fusione glaciale.",

    "q.t18#7.p" to "In quali casi conviene rinunciare del tutto a quel punto di guado?",
    "q.t18#7.o0" to "Non si vede il fondo e l'acqua è torbida",
    "q.t18#7.o1" to "A valle ci sono tronchi caduti o sponde ripide",
    "q.t18#7.o2" to "A monte ha appena piovuto forte",
    "q.t18#7.o3" to "L'alveo è una ghiaia piatta e dolce",
    "q.t18#7.e" to "Le prime tre significano «non posso valutare» oppure «non posso permettermi un errore». La ghiaia piatta è invece un buon fondo.",

    "q.t18#8.p" to "Quali interventi sull'attrezzatura vanno fatti prima di entrare in acqua?",
    "q.t18#8.o0" to "Slacciare la fibbia pettorale",
    "q.t18#8.o1" to "Allentare gli spallacci",
    "q.t18#8.o2" to "Stringere gli oggetti esterni, riducendo quello che trattiene acqua",
    "q.t18#8.o3" to "Mettere telefono e medicine nel sacco impermeabile",
    "q.t18#8.e" to "Le prime due servono a potersi liberare dello zaino, le altre due a non perdere materiali critici. Tutte e quattro si fanno prima di entrare in acqua.",

    "q.t18#9.p" to "Metti in ordine la sequenza decisionale di un guado.",
    "q.t18#9.o0" to "Chiedersi prima «devo proprio guadare?» (girare, cercare un ponte, aspettare che l'acqua scenda)",
    "q.t18#9.o1" to "Scegliere il punto e misurare profondità e velocità",
    "q.t18#9.o2" to "Verificare che zaino e abbigliamento siano trattati allo stesso modo da tutti",
    "q.t18#9.o3" to "Passare in formazione oppure con la soluzione a una persona",
    "q.t18#9.e" to "La prima domanda elimina gran parte del rischio. Molti la saltano e passano subito a studiare «come attraversare».",

    "q.t18#10.p" to "Nel pomeriggio il fiume è visibilmente più pieno che al mattino: qual è il motivo principale?",
    "q.t18#10.o0" to "La variazione giornaliera della fusione glaciale, con la portata massima nel pomeriggio",
    "q.t18#10.o1" to "Nel pomeriggio piove di più",
    "q.t18#10.o2" to "Una diga a monte rilascia acqua",
    "q.t18#10.o3" to "L'evaporazione",
    "q.t18#10.e" to "Nei fiumi alimentati dalla fusione la variazione giornaliera è regolare: minimo al mattino, massimo nel pomeriggio. Conviene guadare nella prima parte della giornata.",
    // ---------- t19 Formazioni e gestione della caduta in acqua ----------
    "q.t19#0.p" to "Qual è il modo corretto di formare un triangolo?",
    "q.t19#0.o0" to "In tre rivolti verso l'interno, afferrando spalle o zaino, muovendo una persona e una gamba per volta",
    "q.t19#0.o1" to "In tre fianco a fianco tenendosi per mano, avanzando insieme",
    "q.t19#0.o2" to "In fila indiana",
    "q.t19#0.o3" to "Due che ne portano uno",
    "q.t19#0.e" to "Muovere il passo tutti insieme fa perdere l'appoggio all'intera formazione nello stesso istante. Tenersi per le mani stanca e le mani scivolano: meglio spalle o zaino.",

    "q.t19#1.p" to "Nella formazione in linea, dove vanno messi i più forti?",
    "q.t19#1.o0" to "Alle due estremità (soprattutto a monte)",
    "q.t19#1.o1" to "Al centro",
    "q.t19#1.o2" to "In fondo",
    "q.t19#1.o3" to "In qualsiasi posizione",
    "q.t19#1.e" to "L'estremità a monte assorbe la spinta principale della corrente, quella a valle fa da rete. I meno esperti stanno al centro, con un forte per lato.",

    "q.t19#2.p" to "Qual è il ritmo dei comandi durante il guado in formazione?",
    "q.t19#2.o0" to "«Un passo, stop, un passo»",
    "q.t19#2.o1" to "«Uno due uno» continuo",
    "q.t19#2.o2" to "Senza parlare",
    "q.t19#2.o3" to "Ognuno per conto suo",
    "q.t19#2.e" to "Il ritmo comune serve a «muovere una persona sola per volta». Il passo simultaneo è l'errore più frequente nelle formazioni.",

    "q.t19#3.p" to "Dopo una caduta in acqua, qual è il primo principio?",
    "q.t19#3.o0" to "Non rialzarsi in piedi",
    "q.t19#3.o1" to "Rialzarsi subito",
    "q.t19#3.o2" to "Afferrare la corda",
    "q.t19#3.o3" to "Afferrare un tronco",
    "q.t19#3.e" to "Il piede può incastrarsi in una fessura o sotto un tronco e la corrente spinge la persona sott'acqua: è il «foot entrapment», il meccanismo più tipico di morte nel guado.",

    "q.t19#4.p" to "Qual è la posizione corretta dopo la caduta?",
    "q.t19#4.o0" to "Sulla schiena, piedi verso valle e vicini alla superficie, testa sollevata",
    "q.t19#4.o1" to "A pancia in giù, nuotando",
    "q.t19#4.o2" to "In verticale, scalciando",
    "q.t19#4.o3" to "Rannicchiato",
    "q.t19#4.e" to "Sulla schiena con i piedi a valle si può spingere via un ostacolo con i piedi invece di inciamparci, e la testa resta protetta.",

    "q.t19#5.p" to "Riguardo alla cintura lombare durante il guado, qual è l'affermazione corretta?",
    "q.t19#5.o0" to "La scuola americana la slaccia per poter abbandonare lo zaino, quella neozelandese la tiene chiusa come galleggiante; l'importante è che la squadra faccia lo stesso",
    "q.t19#5.o1" to "Va sempre slacciata",
    "q.t19#5.o2" to "Va sempre chiusa",
    "q.t19#5.o3" to "Non importa",
    "q.t19#5.e" to "Le due impostazioni hanno premesse diverse. Il vero pericolo è «metà la slaccia e metà la chiude»: in soccorso non si riesce a coordinarci.",

    "q.t19#6.p" to "Se lo zaino si incastra sotto un masso, cosa si fa?",
    "q.t19#6.o0" to "Sollevare le braccia e sfilarlo dalle spalle, accettando di perdere lo zaino",
    "q.t19#6.o1" to "Tirarlo con forza",
    "q.t19#6.o2" to "Immergersi per slacciarlo",
    "q.t19#6.o3" to "Aspettare i compagni",
    "q.t19#6.e" to "Con lo zaino incastrato la corrente tiene la persona sotto. Alzare le braccia e sfilarlo è la manovra più rapida per liberarsi.",

    "q.t19#7.p" to "Qual è la manovra corretta prima di uscire dall'acqua?",
    "q.t19#7.o0" to "Slacciare prima la cintura, poi togliere lo spallaccio lato monte, lasciando che lo zaino venga davanti per aiutarsi a stare in piedi",
    "q.t19#7.o1" to "Alzarsi prima e poi togliere lo zaino",
    "q.t19#7.o2" to "Buttare lo zaino sulla riva",
    "q.t19#7.o3" to "Arrampicarsi direttamente",
    "q.t19#7.e" to "La spinta dello zaino può aiutare, ma con l'ordine sbagliato si perde l'appoggio. Prima la cintura, poi lo spallaccio a monte: è la sequenza standard.",

    "q.t19#8.p" to "Quali preparativi vanno fatti prima di un guado in formazione?",
    "q.t19#8.o0" to "Provare a terra le prese e i comandi",
    "q.t19#8.o1" to "Decidere chi sta all'estremità a monte",
    "q.t19#8.o2" to "Concordare come trattare cintura e fibbia pettorale",
    "q.t19#8.o3" to "Lasciare che ognuno scelga il proprio modo",
    "q.t19#8.e" to "La formazione vive di coordinamento, e il coordinamento si costruisce solo concordando prima. Se ognuno fa a modo suo, la formazione si sfalda in acqua.",

    "q.t19#9.p" to "Sul guado con corda di sicurezza, quali affermazioni sono corrette?",
    "q.t19#9.o0" to "Molte squadre non sono abbastanza addestrate: il rischio può superare il beneficio",
    "q.t19#9.o1" to "La corda va fissata a riva, mai legata a una persona",
    "q.t19#9.o2" to "Si passa dal lato a valle della corda",
    "q.t19#9.o3" to "La soluzione più sicura è una corda tesa in linea retta attraverso la corrente",
    "q.t19#9.e" to "Una corda tesa trasversalmente spinge la persona sott'acqua. L'uso della corda è una tecnica specifica, non si improvvisa sul posto.",

    "q.t19#10.p" to "Metti in ordine un guado in formazione.",
    "q.t19#10.o0" to "Scegliere il punto e verificare che il run-out sia sicuro",
    "q.t19#10.o1" to "Tutta la squadra slaccia la fibbia pettorale e concorda come trattare la cintura",
    "q.t19#10.o2" to "Provare a terra la formazione e i comandi",
    "q.t19#10.o3" to "Attraversare insieme spostandosi lateralmente, un passo per volta",
    "q.t19#10.o4" to "A riva, cambiarsi con abiti asciutti e bere qualcosa di caldo",
    "q.t19#10.e" to "L'ultimo passo è il più trascurato: l'ipotermia da acqua fredda è spesso più frequente della caduta stessa.",

    "q.t19#11.p" to "Un compagno in acqua si ferma di colpo e non si muove: qual è l'ipotesi più probabile?",
    "q.t19#11.o0" to "Ha il piede incastrato: serve aiuto immediato e va tenuto sulla schiena",
    "q.t19#11.o1" to "Si sta riposando",
    "q.t19#11.o2" to "Sta guardando il panorama",
    "q.t19#11.o3" to "Sta aspettando un comando",
    "q.t19#11.e" to "Fermarsi all'improvviso è il segno tipico del piede incastrato. In quel momento ha bisogno di «non agitarsi, restare sulla schiena, qualcuno che arrivi da monte».",

    // ---------- t20 Manutenzione e riparazione dell'attrezzatura ----------
    "q.t20#0.p" to "Quali sono i guasti più frequenti dell'attrezzatura su un lungo itinerario?",
    "q.t20#0.o0" to "Suola che si scolla e materassino che perde",
    "q.t20#0.o1" to "Cinghia dello zaino che si rompe",
    "q.t20#0.o2" to "Buco nella tenda",
    "q.t20#0.o3" to "Bastoncino che si spezza",
    "q.t20#0.e" to "I primi due portano direttamente a «non poter camminare» o «non poter dormire». Il controllo prima di partire deve guardare prima a quelli.",

    "q.t20#1.p" to "La suola inizia a scollarsi: qual è la soluzione migliore sul posto?",
    "q.t20#1.o0" to "Fissarla con nastro adesivo per fermare lo strappo, e usare la colla specifica in paese",
    "q.t20#1.o1" to "Fonderla con il fuoco",
    "q.t20#1.o2" to "Legarla con una corda",
    "q.t20#1.o3" to "Continuare a camminare e vedere se cade",
    "q.t20#1.e" to "Il nastro serve a «limitare il danno», non a riparare. Se lo strappo continua, l'intera suola si stacca e allora non si cammina più davvero.",

    "q.t20#2.p" to "Si spezza un palo della tenda: qual è la riparazione pratica sul posto?",
    "q.t20#2.o0" to "Infilare la boccola di riparazione sul punto rotto e continuare a usarla",
    "q.t20#2.o1" to "Avvolgerla in una palla di nastro adesivo",
    "q.t20#2.o2" to "Buttare la tenda",
    "q.t20#2.o3" to "Sostituire l'intero palo con un ramo",
    "q.t20#2.e" to "La boccola recupera gran parte della resistenza. Il nastro regge solo una o due notti e lascia peggiorare il punto rotto.",

    "q.t20#3.p" to "Si è fatto un piccolo foro nel piumino: qual è la gestione corretta?",
    "q.t20#3.o0" to "Mettere una toppa e premere, senza scuotere",
    "q.t20#3.o1" to "Scrollare via la piuma che esce",
    "q.t20#3.o2" to "Sigillarlo con il fuoco",
    "q.t20#3.o3" to "Cucirlo stretto",
    "q.t20#3.e" to "Scuotere fa uscire la piuma dal foro in continuazione. Toppa più leggera pressione è la soluzione più efficace per fermare la perdita.",

    "q.t20#4.p" to "Quale NON è una causa frequente di perdita del materassino?",
    "q.t20#4.o0" to "Esposizione al sole",
    "q.t20#4.o1" to "Sassi appuntiti sul terreno",
    "q.t20#4.o2" to "Valvola non chiusa bene",
    "q.t20#4.o3" to "Cuciture affaticate",
    "q.t20#4.e" to "Il sole non buca direttamente la camera d'aria. Oltre alle altre tre voci, la causa più comune è il terreno non pulito prima di stendere il materassino.",

    "q.t20#5.p" to "Cosa vale la pena portare in un kit di riparazione da trekking?",
    "q.t20#5.o0" to "Nastro Dyneema",
    "q.t20#5.o1" to "Toppe per materassino e colla",
    "q.t20#5.o2" to "Fibbie di ricambio",
    "q.t20#5.o3" to "Un set di cacciaviti",
    "q.t20#5.e" to "Le prime tre coprono i tre guasti più frequenti: telo della tenda, camera d'aria, fibbie dello zaino. Il cacciavite è peso che non si usa.",

    "q.t20#6.p" to "Quali controlli vale la pena fare ogni giorno, arrivati al campo, in cinque minuti?",
    "q.t20#6.o0" to "Se c'è sabbia o sassolini nelle scarpe",
    "q.t20#6.o1" to "Se le calze sono fradicie",
    "q.t20#6.o2" to "Cuciture e fibbie dello zaino",
    "q.t20#6.o3" to "La lunghezza dei bastoncini",
    "q.t20#6.e" to "I primi due determinano lo stato dei piedi, il terzo se domani una cinghia si romperà all'improvviso. La lunghezza dei bastoncini si regola in ogni momento e non serve controllarla ogni giorno.",

    "q.t20#7.p" to "Riguardo alla «scadenza» dell'attrezzatura, qual è l'idea corretta?",
    "q.t20#7.o0" to "Si giudica dall'intensità d'uso e dall'aspetto, non dall'anno di acquisto",
    "q.t20#7.o1" to "Il nuovo è sempre meglio",
    "q.t20#7.o2" to "Si cambia solo quando si rompe",
    "q.t20#7.o3" to "Più vecchio è, più è affidabile",
    "q.t20#7.e" to "Lo stesso oggetto, con frequenze d'uso diverse, dura molto diversamente. Guardare l'usura (suola, fibbie, trattamento) è più affidabile che guardare la data.",

    // ---------- t21 Marcia notturna e temporali ----------
    "q.t21#0.p" to "Qual è l'atteggiamento più ragionevole verso la marcia notturna?",
    "q.t21#0.o0" to "Non camminare se non è necessario; se lo è, rallentare e curare di più la gestione della formazione",
    "q.t21#0.o1" to "Di notte fa fresco, è il momento buono per avanzare",
    "q.t21#0.o2" to "Di notte è più sicuro",
    "q.t21#0.o3" to "Basta avere la frontale",
    "q.t21#0.e" to "Di notte la lettura del terreno e la navigazione diventano molto più difficili, e il tasso di incidenti sale. La marcia notturna è «quello che si fa quando non c'è alternativa», non una strategia.",

    "q.t21#1.p" to "Qual è la configurazione di illuminazione corretta per una marcia notturna?",
    "q.t21#1.o0" to "Frontale, batterie di riserva e una fonte di luce di riserva (torcetta o seconda frontale)",
    "q.t21#1.o1" to "Solo il flash del telefono",
    "q.t21#1.o2" to "Solo la frontale",
    "q.t21#1.o3" to "Una candela",
    "q.t21#1.e" to "Se la luce si spegne, di notte si perde la capacità di muoversi. La fonte di riserva è «ridondanza», con la stessa logica della ridondanza nei sistemi di corda.",

    "q.t21#2.p" to "Come va gestita la distanza fra le persone in una marcia notturna?",
    "q.t21#2.o0" to "Ridurla, con chi sta davanti che verifica di frequente che gli altri seguano, e qualcuno fermo ai bivi",
    "q.t21#2.o1" to "Aumentarla, ognuno per conto suo",
    "q.t21#2.o2" to "Lasciarla distribuire secondo la forma fisica",
    "q.t21#2.o3" to "Lasciare che chi resta indietro trovi la strada",
    "q.t21#2.e" to "Di notte il campo visivo è stretto e chi resta indietro è difficile da notare. Lasciare una persona ai bivi è l'assicurazione che costa meno.",

    "q.t21#3.p" to "Quale NON è un segnale precoce dell'arrivo di un temporale?",
    "q.t21#3.o0" to "Temperatura che sale gradualmente",
    "q.t21#3.o1" to "Cumulonembi che crescono rapidamente",
    "q.t21#3.o2" to "Tuoni sordi in lontananza",
    "q.t21#3.o3" to "Capelli che si rizzano e pelle che formicola",
    "q.t21#3.e" to "Quando arriva un temporale la temperatura di solito scende. I capelli che si rizzano indicano accumulo di carica: bisogna lasciare subito i punti alti.",

    "q.t21#4.p" to "Sorprendendoti un temporale in montagna, cosa si fa?",
    "q.t21#4.o0" to "Scendere rapidamente più in basso, lasciando creste, rive e alberi isolati",
    "q.t21#4.o1" to "Ripararsi sotto un grande masso in vetta",
    "q.t21#4.o2" to "Mettersi sotto un albero",
    "q.t21#4.o3" to "Continuare a camminare",
    "q.t21#4.e" to "Punti alti, rive e alberi isolati sono le vie preferenziali del fulmine. Scendere più in basso e distribuirsi è l'unica misura efficace.",

    "q.t21#5.p" to "Qual è la posizione corretta per limitare il rischio di fulmine?",
    "q.t21#5.o0" to "Accovacciarsi distanziati, con i piedi uniti, senza sdraiarsi",
    "q.t21#5.o1" to "Sdraiarsi a terra",
    "q.t21#5.o2" to "Stare in piedi, ben dritti",
    "q.t21#5.o3" to "Abbracciare un albero",
    "q.t21#5.e" to "Tenere i piedi uniti riduce la tensione di passo; sdraiarsi aumenta la superficie di contatto con il terreno ed è più pericoloso.",

    "q.t21#6.p" to "Durante un temporale, quali altri rischi vanno gestiti insieme?",
    "q.t21#6.o0" to "Ipotermia per il forte calo di temperatura",
    "q.t21#6.o1" to "Piena improvvisa per le piogge intense",
    "q.t21#6.o2" to "Perdita dell'orientamento per il crollo della visibilità",
    "q.t21#6.o3" to "Scottature da raggi ultravioletti",
    "q.t21#6.e" to "Il temporale porta spesso calo di temperatura, pioggia intensa e nebbia. È «un gruppo di rischi», non un rischio singolo.",

    "q.t21#7.p" to "Lasciare l'itinerario a un contatto che resta a casa, a cosa serve in una marcia notturna o con temporale?",
    "q.t21#7.o0" to "Se la squadra non arriva in orario, qualcuno dall'esterno può avviare la ricerca",
    "q.t21#7.o1" to "A essere gentili",
    "q.t21#7.o2" to "Al rimborso assicurativo",
    "q.t21#7.o3" to "A niente",
    "q.t21#7.e" to "Di notte e con maltempo il margine di errore è minimo. Il foglio di itinerario è la premessa perché «se succede qualcosa, qualcuno venga a cercarti».",
)
